// SOTERRA — os DADOS em espanhol (05/10). Nomes e descrições das tabelas do JOGO.DATA, por
// tabela → registro → campo; o registro é o caminho que o JOGO.I18n.percorre dá (o id, ou
// 'id/rooms/0'). Só entra na página quando o idioma é 'es' (index.html), logo depois do último
// js/core/data/*.js: ao registrar, o I18n troca os textos do DATA. O JUIZ NÃO LÊ ESTE ARQUIVO.
//
// É para EDITAR À MÃO: uma linha por registro. Regras (docs/IDIOMAS.md): os números são os
// mesmos do português, o glossário é fixo, e `node tools/i18n_falta.js` diz o que falta e o que
// ficou com número diferente depois de um ajuste de equilíbrio.
JOGO.I18n.registra('es', { dados: {
  "elementInfo": {
    "neutro": {"name":"Neutro","description":"La materia cruda del mundo enterrado. No ama ni odia a nadie: ningún clima lo ayuda, ningún clima lo hiere."},
    "fogo": {"name":"Fuego","description":"La memoria del sol, guardada en brasa. Come rápido y cobra caro. Odia el Agua, que la apaga."},
    "agua": {"name":"Agua","description":"Paciente, pesada, sin prisa alguna. Rodea lo que no puede romper. Odia el Fuego, que se la roba."},
    "terra": {"name":"Tierra","description":"Raíz, piedra y terquedad. Solo cede cuando alguien cava. Odia el Aire, que se la lleva un grano a la vez."},
    "ar": {"name":"Aire","description":"Lo que sobró del cielo cuando el cielo se hizo piedra. Nunca está donde apuntaste. Odia la Tierra, que lo atrapa."}
  },
  "weathers": {
    "calmo": {"name":"Calma","description":"El aire quieto de las salas que nadie abrió en mil años. Solo se mueve el polvo, y con pereza. Aquí ningún elemento tiene ventaja: la sala no opina sobre quién debe morir.","flavor":"El silencio no es paz. Es solo el ruido esperando su turno."},
    "chuva": {"name":"Lluvia","description":"El agua que la Gran Lousa atrapó allá arriba encuentra camino y baja por las grietas toda la noche. El suelo se vuelve espejo, el ruido se traga los pasos — y todo lo que arde empieza a sisear.","flavor":"Llueve hace mil años. Nadie tuvo valor de contárselo a la lluvia."},
    "estiagem": {"name":"Sequía","description":"El calor sube de las rejillas del piso y se queda, sin adónde ir. El sudor se seca antes de caer, la piedra cruje de sed y cada respiro cuesta un trago que nadie tiene. Aquí la brasa es reina.","flavor":"La sala entera es una boca abierta esperando que alguien diga \"agua\"."},
    "vendaval": {"name":"Vendaval","description":"Los respiraderos del mundo enterrado soplan todos a la vez y la sala se vuelve corredor de túnel. Las cuerdas silban, las tablas golpean, y lo que tiene raíz siente que lo desentierran a ráfagas.","flavor":"Aquí el viento no pasa: vive, y tú eres el visitante."},
    "tremor": {"name":"Temblor","description":"La Lousa baja un palmo más y el mundo recuerda que es de piedra. El suelo late como un corazón grande y lento, el polvo sube en cortinas y el aire pesa demasiado para cargar nada ligero.","flavor":"No es la piedra la que tiembla. Eres tú, y la piedra está de acuerdo."}
  },
  "classes": {
    "sumo": {"name":"Bárbaro","description":"Corpachón, capa raída y un hacha de dos manos: ocupa el cuello de botella y no se mueve. Provoca, traba, empuja y cobra caro cada casilla del tablero. Poca prisa, mucha presencia.","lore":"Cuando la Lousa descendió, los constructores sellaron los Cierres — y alguien tuvo que sostener el portón desde dentro. Él lo sostuvo, con el hacha del padre y la espalda contra la piedra. Mil años después aún golpea el mango contra el suelo cada mañana imaginaria: mientras el suelo responda, el mundo sigue en pie."},
    "arqueiro": {"name":"Cazador","description":"Sombrero de ala ancha y escopeta de dos cañones. Daño a distancia que se acumula: cada disparo deja una marca en el objetivo, y quien tiene demasiadas marcas recibe toda la cuenta de una vez. Débil de cerca, letal de lejos.","lore":"Fueron los cazadores quienes midieron el techo de piedra de los Cierres y concluyeron que aún cabía un disparo entre él y el suelo. Desde entonces marcan todo lo que se mueve: las marcas son un cuaderno de cuentas, y ningún Cierre vio jamás a un cazador perdonar una deuda."},
    "bruxo": {"name":"Brujo","description":"Áreas de media y larga distancia, maldiciones que trabajan solas y control del terreno. Borra salas enteras — si sobrevive al tiempo de conjuro.","lore":"Cuando el cielo se coaguló, hubo quien intentó leer la Lousa por dentro. Los que volvieron traían la caligrafía de la piedra pegada a las manos: ahora escriben en el aire lo que la Lousa escribió en el mundo, y el aire obedece igual. El sombrero puntiagudo es costumbre de la escuela: apunta al cielo que ya no existe."},
    "espadachim": {"name":"Pícaro","description":"Dos dagas, velocidad, invisibilidad y veneno. Vive de elegir el momento: entra por el flanco, corta dos veces y desaparece antes de la respuesta. Muere rápido si falla la ventana.","lore":"No existe la noche en un mundo sin cielo — existe la negrura entre dos linternas, y ahí vive él. Aprendió a andar en el intervalo de las luces y a devolver, en la punta de las dos dagas, la misma oscuridad que la Lousa entregó a todos."},
    "curandeiro": {"name":"Curandero","description":"Devuelve vida y bendice a quien lucha. No sostiene la línea ni arruina el terreno: lo que él hace, y nadie más hace, es mantener al grupo en pie un turno más.","lore":"Heredó de la abuela la linterna de luciérnagas y la regla de la casa: en el mundo enterrado, quien se apaga primero es quien dejó de cuidar a los demás. Mandó pulir la armadura hasta dejarla clara a propósito — en un Cierre oscuro, quien cae debe saber hacia dónde correr. Ella no piensa apagarse pronto."},
    "invocador": {"name":"Chamán","description":"Llena el tablero con el grimorio abierto en una mano: invoca criaturas que bloquean y muerden, arma trampas en las casillas de paso y fortalece a quien esté cerca. Solo es frágil; nunca está solo.","lore":"Pasó la vida oyendo al micelio de los Cierres contar quién murió dónde. Un día respondió — y algo del otro lado le encontró la gracia. Hoy no invoca nada: solo pide permiso, y el mundo enterrado le presta un pedazo de sí. Cada préstamo queda anotado en el grimorio: la deuda olvidada es la única que cobra intereses."},
    "minotauro": {"name":"Minotauro","description":"Demasiado grande para esquivar y demasiado terco para retroceder. Levanta muros donde no había camino y pone su propio escudo frente a quien sangra. No mata: decide por dónde puede andar el otro.","lore":"Pusieron al Minotauro a guardar el paso porque nadie más cabía en él. No cuenta los años: cuenta las piedras que ya levantó y las que aún levantará. Dice que el laberinto no es para perder a nadie — es para que quien entre tenga que elegir, y elegir despacio."}
  },
  "dificuldades": {
    "facil": {"nome":"Fácil","resumo":"Monstruos más débiles y clima suave. Paga menos."},
    "normal": {"nome":"Normal","resumo":"El juego como fue calibrado."},
    "dificil": {"nome":"Difícil","resumo":"Monstruos más duros y clima cruel. Paga mucho más."}
  },
  "spells": {
    "trap-neutro-alarme": {"name":"Estaca-Alarma (disparo)","description":"La estaca salta del suelo, atraviesa el pie de quien pisó y pita: 11–15 de daño neutro y −1 PP por 1 turno.","flavor":"Sirve más para avisar que para matar. Pero avisa con dolor."},
    "trap-fogo-brasa": {"name":"Trampa de Brasa (disparo)","description":"El carbón enterrado despierta: 17–21 de fuego en radio 1 y quemadura de 4–6 por 2 turnos.","flavor":"Entierra brasa como quien siembra. Cosecha gritos."},
    "trap-fogo-pira": {"name":"Trampa-Pira (disparo)","description":"Una pira entera doblada dentro de una casilla: 39–47 de fuego en radio 1 y quemadura de 9–12 por 2 turnos.","flavor":"La casilla recordó haber sido una fogata. Tú lo recordaste tarde."},
    "trap-agua-redemoinho": {"name":"Trampa-Remolino (disparo)","description":"El suelo se vuelve embudo: 14–18 de agua y el incauto es atraído 2 casillas hacia el centro.","flavor":"El agua quieta de mil años guarda una sola voluntad: bajar."},
    "trap-agua-sorvedouro": {"name":"Trampa-Sumidero (disparo)","description":"Se abre un desagüe del mundo antiguo: 35–42 de agua en radio 1 y succión de 3 casillas.","flavor":"Alguien, un día, tiró de esa tapa. Nadie la volvió a poner."},
    "trap-terra-laco": {"name":"Trampa-Lazo (disparo)","description":"Raíces cierran el tobillo: 13–17 de tierra y 0 PP por 2 turnos.","flavor":"El micelio no come rápido. Come con calma, para que dure."},
    "trap-terra-tremor": {"name":"Trampa-Temblor (disparo)","description":"La losa cede en radio 1: 36–44 de tierra y nadie se mueve de su lugar por 2 turnos.","flavor":"No es el hueco lo que lastima — es el susto de que el suelo tenga opinión."},
    "trap-ar-rajada": {"name":"Trampa-Ráfaga (disparo)","description":"Un respiradero guardado estalla: 13–18 de aire y lanzamiento de 3 casillas.","flavor":"Aire viejo, guardado desde antes de la Lousa, y de mal humor como corresponde."},
    "trap-ar-vortice": {"name":"Trampa-Vórtice (disparo)","description":"Un nudo de viento se desata en radio 1: 38–47 de aire y 4 casillas de lanzamiento.","flavor":"Quien diseñó los respiraderos nunca imaginó que alguien los cerraría a propósito."},
    "sumo-neutro-1": {"name":"Hachazo de Hierro","description":"El hacha cae sobre el pecho del adversario: 28–36 de daño neutro y 1 casilla de empuje. Dos veces por turno.","flavor":"En el portón se aprende pronto: primero sacas al otro de su lugar, después discutes."},
    "sumo-neutro-2": {"name":"Grito de Guerra","description":"Golpea el mango del hacha contra el suelo y ruge: todos los enemigos están obligados a atacarlo por 2 turnos, y gana 42 de escudo.","flavor":"El suelo del Cierre responde. Es la única respuesta que quedó."},
    "sumo-neutro-3": {"name":"Agarre de Oso","description":"Cierra la manopla en la garganta del enemigo: 14–20 de daño y 0 PP por 1 turno.","flavor":"No sujeta para lastimar. Sujeta para conversar."},
    "sumo-fogo-5": {"name":"Piel en Brasa","description":"La piel se calienta hasta agrietarse: devuelve 25% del daño recibido al agresor por 2 turnos y resiste 15% a fuego.","flavor":"Golpearlo es tocar la plancha. Todos la tocan una vez."},
    "sumo-fogo-10": {"name":"Filo Incandescente","description":"27–34 de fuego en el filo del hacha, y la marca sigue ardiendo 6–9 por 2 turnos.","flavor":"Su hacha deja firma. En brasa."},
    "sumo-fogo-12": {"name":"Estallido de Brasa","description":"Estalla hacia afuera cuando lo rodean: 26–32 de fuego en radio 1 y todos 1 casilla hacia atrás.","flavor":"Rodearlo es calentarlo. Nadie fue avisado."},
    "sumo-fogo-15": {"name":"Sangre Hirviente","description":"Hierve su propia sangre: +35 de poder por 2 turnos, al precio de 6–8 de quemadura propia por turno.","flavor":"Dicen que escupe vapor cuando está contento con la pelea."},
    "sumo-fogo-20": {"name":"Represalia Volcánica","description":"Provoca a toda la sala, viste 70 de escudo y devuelve 50% de todo lo que reciba por 2 turnos.","flavor":"La pregunta no es si le pegarán. Es cuántos seguirán en pie después de pegarle."},
    "sumo-fogo-30": {"name":"Furia de la Fragua","description":"El cuerpo entero se vuelve forja y revienta: 65–78 de fuego en radio 2, quemadura de 13–17 por 3 turnos, 2 casillas de empuje — y toda la sala entra en sequía.","flavor":"Así descubrió, hace mil años, que el Corazón del Cierre aún latía."},
    "sumo-agua-5": {"name":"Filo de Marea","description":"28–36 de agua con robo de vida y 1 casilla de empuje: golpea, bebe y aleja.","flavor":"El hacha sale mojada. El otro sale más seco."},
    "sumo-agua-10": {"name":"Paso Resbaladizo","description":"Moja el suelo de la sala y se desliza en él: +30 de esquiva y +1 PP por 2 turnos.","flavor":"Ciento cincuenta kilos deslizándose. Es más elegante de lo que parece."},
    "sumo-agua-12": {"name":"Ola de Hombro","description":"Un hombro de agua cruza la línea: 29–37 con robo de vida en todos, y 2 casillas de empuje.","flavor":"La cisterna aprendió a pelear mirando por el desagüe."},
    "sumo-agua-15": {"name":"Bebedor de Golpes","description":"Absorbe lo que venga: 60 de escudo, regeneración de 14–18 por 2 turnos y quita venenos y raíces.","flavor":"No cura. Se lo traga y lo digiere después."},
    "sumo-agua-20": {"name":"Marea Bruta","description":"Gira y suelta la marea: 36–44 de agua con robo de vida en radio 2 y 2 casillas de empuje para todos.","flavor":"Media sala retrocede. Él queda más gordo de vida que al empezar."},
    "sumo-agua-30": {"name":"Resaca Absoluta","description":"Atrae a toda la sala 3 casillas hacia su cuerpo, se traga 62–73 de agua con robo de vida y deja a todos sin PP por 1 turno.","flavor":"Cuando la cisterna respira hondo, todo el baile va con ella."},
    "sumo-terra-5": {"name":"Casco de Piedra","description":"Endurece la corteza: 63 de escudo y +20 de traba por 2 turnos — huir de él sale bastante más caro.","flavor":"No se pone más duro. Es el mundo el que se ablanda en comparación."},
    "sumo-terra-10": {"name":"Pisada Fundadora","description":"Pisa como quien asienta un cimiento: 21–28 de tierra en radio 1 y 0 PP por 1 turno.","flavor":"Su portón tiene mil años y nunca necesitó arreglo."},
    "sumo-terra-12": {"name":"Estaca Humana","description":"Se clava en el suelo y llama a todos: provocación por 2 turnos, 75 de escudo y 20% de resistencia a tierra.","flavor":"Lo plantaron ahí. Habrá que desenterrarlo."},
    "sumo-terra-15": {"name":"Raíces de Piedra","description":"Manda raíces bajo el suelo hasta el punto elegido: 26–33 de tierra en radio 1 y 0 PP por 2 turnos.","flavor":"Toda la sala es suya. Solo te prestó el suelo para pisar."},
    "sumo-terra-20": {"name":"Muralla Viva","description":"Se vuelve muro de carne y piedra: 120 de escudo, 25% de resistencia a tierra y +30 de traba por 3 turnos.","flavor":"Los constructores sellaban Cierres con portones. Él prescinde del portón."},
    "sumo-terra-30": {"name":"Montaña Andante","description":"Da un paso y la sala se parte: 54–65 de tierra en radio 2, nadie anda por 2 turnos, todos están obligados a enfrentarlo por 3 — y el polvo del temblor toma el aire.","flavor":"No es que la montaña haya aprendido a andar. Es que él nunca aceptó quedarse quieto."},
    "sumo-ar-5": {"name":"Embestida Bruta","description":"Se desliza hasta 4 casillas hacia el objetivo y lo embiste: 28–38 de daño de aire. La entrada gratis del tanque.","flavor":"Ciento cincuenta kilos no corren. Llegan."},
    "sumo-ar-10": {"name":"Arrojo Brutal","description":"Lo toma por el peto y lo lanza: 29–38 de aire y 3 casillas de vuelo (chocar duele más).","flavor":"Siempre apunta al obstáculo más cercano. Por economía de movimiento."},
    "sumo-ar-12": {"name":"Ciclón de Hacha","description":"Gira sobre sí mismo con el hacha extendida: 31–40 de aire en radio 1 y 2 casillas de empuje a todos.","flavor":"Quien estaba cerca pasa a espectador. Lejos, de preferencia."},
    "sumo-ar-15": {"name":"Tirón y Vuelta","description":"Un soplo-lazo arrastra al objetivo 4 casillas hacia él: 34–43 de aire y 0 PP por 1 turno. El tirador enemigo lo detesta.","flavor":"Le parece grosero conversar de lejos."},
    "sumo-ar-20": {"name":"Tifón de Hierro","description":"Cruza hasta 6 casillas en línea recta de furia: 65–79 de aire y 3 casillas de lanzamiento al final del trayecto.","flavor":"Todo el corredor oye el silbido antes de ver al bárbaro."},
    "sumo-ar-30": {"name":"Arrojo del Fin del Mundo","description":"Agarra, gira tres veces y suelta: 94–109 de aire, 6 casillas de vuelo y 2 turnos sin poder levantarse (0 PP).","flavor":"Entrenó mil años para el lanzamiento que por fin estrellara a alguien contra la Lousa."},
    "arqueiro-neutro-1": {"name":"Tiro Anotado","description":"14–19 de daño neutro y 1 marca en el objetivo (cada marca aumenta 5% todo el daño que reciba). Dos veces por turno.","flavor":"El disparo no es el cobro. Es solo el registro en el cuaderno."},
    "arqueiro-neutro-2": {"name":"Paso de Cierva","description":"Se desliza hasta 4 casillas a una casilla vacía, sin gastar PP. La distancia es la armadura del arquero.","flavor":"Nadie lo vio correr. Todos lo vieron ya lejos."},
    "arqueiro-neutro-3": {"name":"Cobrar la Cuenta","description":"Consume todas las marcas del objetivo: 9 de daño por marca, más 6–10 de daño neutro del disparo.","flavor":"Ningún cazador perdona una deuda. Como mucho, aplaza el vencimiento."},
    "arqueiro-fogo-5": {"name":"Carga Incendiaria","description":"14–19 de fuego, quemadura de 4–5 por 2 turnos y 1 marca.","flavor":"El cartucho va relleno con la resina que sobró del Invernadero. Huele a fin de tarde."},
    "arqueiro-fogo-10": {"name":"Salva de Chispas","description":"Tres disparos en abanico: 16–21 de fuego en radio 1 y 1 marca en cada impactado. Marcar a todo el grupo es el plan.","flavor":"Contabilidad en masa."},
    "arqueiro-fogo-12": {"name":"Hierro al Rojo","description":"19–23 de fuego y 1 marca que dura 4 turnos — la punta roja tarda en enfriarse.","flavor":"Marca ganado, marca enemigo. La técnica es la misma; la paciencia también."},
    "arqueiro-fogo-15": {"name":"Detonar las Brasas","description":"Enciende todas las marcas en radio 1: 12 de daño por marca de cada objetivo, más 17–23 de fuego en el área.","flavor":"Enciende el cuaderno entero de una vez. Es más rápido que sumar."},
    "arqueiro-fogo-20": {"name":"Lluvia de Brasas","description":"Decenas de perdigones en brasa caen en radio 2: 34–41 de fuego, quemadura de 9–12 por 2 turnos y 1 marca en todos.","flavor":"Llueve fuego en un mundo que no ve lluvia hace mil años. Justicia poética dudosa."},
    "arqueiro-fogo-30": {"name":"Cartuchera del Sol Muerto","description":"Vacía la cartuchera entera en radio 2: 39–47 de fuego, 20 de daño por marca acumulada en cada objetivo y quemadura de 10–13 por 3 turnos.","flavor":"Guardaba un cartucho de cuando aún había sol. Lo guardó hasta ahora."},
    "arqueiro-agua-5": {"name":"Tiro-Arpón","description":"14–19 de agua con robo de vida, atrae 2 casillas y deja 1 marca. Reubica al objetivo donde conviene.","flavor":"La cuerda es fina. Lo grueso es la voluntad del otro lado."},
    "arqueiro-agua-10": {"name":"Tiro del Manantial","description":"19–24 de agua con robo de vida y 1 marca: cada disparo devuelve aliento al tirador.","flavor":"Bebe de lejos. Es la única manera en que bebe un arquero."},
    "arqueiro-agua-12": {"name":"Línea de Corriente","description":"Una corriente cruza la línea: 20–25 de agua, 2 casillas de empuje y 1 marca en cada objetivo de la fila.","flavor":"Apunta al corredor, no a quien está en él."},
    "arqueiro-agua-15": {"name":"Detonar la Marea","description":"Estalla las marcas del objetivo en agua: 14 por marca, más 23–29 con robo de vida. Cobrar la cuenta cura.","flavor":"La deuda se vuelve bebida."},
    "arqueiro-agua-20": {"name":"Lluvia Fría","description":"Una nube de plomo helado en radio 2: 36–44 con robo de vida, atrae 2 casillas y marca a todos los impactados.","flavor":"Junta el rebaño antes de cobrar. Siempre fue más eficiente."},
    "arqueiro-agua-30": {"name":"Marea Marcada","description":"La marea obedece a la cuerda: atrae todo en radio 3 por 3 casillas, causa 41–49 de agua con robo de vida y detona las marcas a 18 por pila.","flavor":"Apuntó a la cisterna y dijo \"vengan\". Vinieron todos, incluida el agua."},
    "arqueiro-terra-5": {"name":"Plomo de Sílex","description":"18–22 de tierra y 1 marca de 4 turnos: la piedra queda clavada mucho después del disparo.","flavor":"Sílex tallado a mano, como se hacía antes de que el cielo fuera techo."},
    "arqueiro-terra-10": {"name":"Estaca en el Pie","description":"Clava al objetivo al suelo: 17–21 de tierra, 0 PP por 1 turno y 1 marca.","flavor":"Regla del cazador: quien no anda, no falla la cuenta."},
    "arqueiro-terra-12": {"name":"Tiro Perforante","description":"La bala atraviesa la fila entera: 23–29 de tierra y 1 marca en cada cuerpo del camino.","flavor":"Cañón de dos palmos, culata de raíz seca. No pide permiso."},
    "arqueiro-terra-15": {"name":"Detonar el Peñasco","description":"Las marcas se vuelven piedra y se derrumban: 13 por marca, 21–27 de tierra y 0 PP por 2 turnos.","flavor":"Cobrar una deuda con peñasco es grosero. También es definitivo."},
    "arqueiro-terra-20": {"name":"Salva de Menhires","description":"Menhires del tamaño de postes caen en radio 2: 34–42 de tierra, 0 PP por 2 turnos y 1 marca en todos.","flavor":"Nadie entiende cómo carga esas cosas en la cartuchera. Nadie pregunta."},
    "arqueiro-terra-30": {"name":"Bala-Menhir","description":"Una columna entera lanzada en línea recta: 62–73 de tierra en toda la fila, 22 por marca detonada y 3 turnos sin PP.","flavor":"Los constructores clavaban menhires para sostener el mundo. Él descubrió otro uso."},
    "arqueiro-ar-5": {"name":"Carga de Viento","description":"Barata y rápida: 13–17 de aire y 1 marca por solo 2 PA. La forma más eficiente de llenar al objetivo de marcas.","flavor":"Sin punta de metal: solo aire comprimido y mala intención."},
    "arqueiro-ar-10": {"name":"Tiro Saltarín","description":"20–24 de aire que saltan a otros 2 enemigos cercanos (−30% en cada salto) y marcan al primer objetivo.","flavor":"El plomo rebota en el techo de piedra. El techo, al menos, sirve para eso."},
    "arqueiro-ar-12": {"name":"Plomo Giratorio","description":"23–29 de aire, 2 casillas de empuje y 1 marca: mantiene el cuerpo a cuerpo siempre a un paso de distancia.","flavor":"Gira tanto que silba. El silbido ya es medio metro de retroceso."},
    "arqueiro-ar-15": {"name":"Detonar la Corriente","description":"Detona las marcas (12 por pila) y la descarga salta a otros 3 enemigos, perdiendo 25% en cada salto.","flavor":"La cuenta de uno es la noticia de todos."},
    "arqueiro-ar-20": {"name":"Vendaval de Plomo","description":"Un vendaval de plomo en radio 2: 39–48 de aire, 3 casillas de lanzamiento y 1 marca en cada objetivo.","flavor":"La mitad del plomo falla a propósito, solo para hacer viento."},
    "arqueiro-ar-30": {"name":"Tempestad Marcada","description":"Detona las marcas a 20 por pila y suelta una descarga de 33–41 que salta por hasta 5 enemigos (−20% por salto). El aire de la sala se vuelve vendaval.","flavor":"Soltó la cuerda y todo el Cierre pasó a deber algo."},
    "bruxo-neutro-1": {"name":"Barrena Arcana","description":"Un agujero limpio de energía cruda: 17–22 de daño neutro hasta 5 casillas. Dos veces por turno.","flavor":"La primera lección de la escuela: el mundo tiene agujeros. Haz más."},
    "bruxo-neutro-2": {"name":"Plaga Susurrada","description":"Maldición en radio 1: 7–9 de daño por turno durante 2 turnos y −15 de poder a los malditos.","flavor":"Nunca grita la plaga. La piedra ya es bastante sorda."},
    "bruxo-neutro-3": {"name":"Círculo de Plomo","description":"Dibuja un círculo pesado en el suelo: 5–8 de daño y −2 PP por 1 turno en radio 1.","flavor":"El plomo es el metal favorito de quien quiere que las cosas se queden donde están."},
    "bruxo-fogo-5": {"name":"Chispa Gemela","description":"17–22 de fuego y quemadura de 3–5 por 2 turnos. Lo básico que nunca sale del cuaderno.","flavor":"Dos chispas: una para acertar, otra para recordar."},
    "bruxo-fogo-10": {"name":"Cono de Cenizas","description":"Un abanico de cenizas calientes: 26–32 de fuego en cono y quemadura de 6–9 por 2 turnos.","flavor":"La ceniza es fuego con memoria."},
    "bruxo-fogo-12": {"name":"Meteoro Menor","description":"Arranca un pedazo del techo de piedra y lo deja caer encendido: 33–41 de fuego en radio 1.","flavor":"La Lousa devuelve lo que presta. Con intereses y temperatura."},
    "bruxo-fogo-15": {"name":"Brasero Prohibido","description":"Enciende el suelo en radio 2: 12–14 al instante y 10–13 por turno durante 3 turnos. Área que se paga con paciencia.","flavor":"Escrito en la puerta de la escuela: \"no encender braseros en recinto cerrado\". El mundo entero es recinto cerrado."},
    "bruxo-fogo-20": {"name":"Pira Doblada","description":"Dos piras dentro de la misma área: 27–33 de fuego en radio 2 y quemadura de 7–10 por 2 turnos.","flavor":"Doblar una pira es fácil. Lo difícil es desdoblarla después."},
    "bruxo-fogo-30": {"name":"Meteoro del Cierre","description":"Derriba un pedazo entero de la Lousa en llamas: 40–48 de fuego en radio 3, quemadura de 11–14 por 3 turnos y la sala entra en sequía.","flavor":"Leyó la piedra hasta el final. En la última página había una instrucción: \"tira de aquí\"."},
    "bruxo-agua-5": {"name":"Lanza de Agua","description":"17–22 de agua con robo de vida: el brujo bebe la mitad de lo que derrama.","flavor":"Agua de la cisterna, sazonada con mil años de malas compañías."},
    "bruxo-agua-10": {"name":"Sifón","description":"Atrae al objetivo 3 casillas, causa 26–33 de agua y disuelve su escudo por completo.","flavor":"El escudo es solo algo seco que aún no se mojó."},
    "bruxo-agua-12": {"name":"Maremoto","description":"Una ola recorre la línea: 33–42 de agua y 3 casillas de empuje a toda la fila.","flavor":"Limpia el corredor. Literalmente."},
    "bruxo-agua-15": {"name":"Charco Hambriento","description":"Abre un charco hambriento en radio 2: 18–23 de agua con robo de vida y todos atraídos 2 casillas hacia el centro.","flavor":"No es hondo. Solo es insistente."},
    "bruxo-agua-20": {"name":"Disolución","description":"Disuelve todos los escudos en radio 2, causa 30–37 de agua con robo de vida y deja 7–10 por turno durante 2 turnos.","flavor":"La cisterna nunca rompió una armadura. Solo esperó."},
    "bruxo-agua-30": {"name":"La Cisterna Recuerda","description":"Llama de vuelta el agua que ahogó a la corte: disuelve escudos, atrae 3 casillas, causa 41–50 con robo de vida en radio 3 y hace llover en la sala.","flavor":"Solo preguntó dónde estaban los dueños de la cisterna. Ella respondió mostrándolos."},
    "bruxo-terra-5": {"name":"Espina de Losa","description":"Una astilla de losa sube del suelo bajo los pies del objetivo: 19–24 de tierra.","flavor":"El piso del Cierre colabora. Siempre colaboró; nadie se lo había pedido."},
    "bruxo-terra-10": {"name":"Grillete de Raíz","description":"Raíces cierran el tobillo del objetivo: 0 PP por 2 turnos y 20–26 de tierra.","flavor":"El Invernadero manda saludos por el subsuelo."},
    "bruxo-terra-12": {"name":"Grieta","description":"Parte el suelo en línea recta: 35–44 de tierra y 0 PP por 1 turno a todos los que estén en ella.","flavor":"Después se cierra. Casi siempre."},
    "bruxo-terra-15": {"name":"Campo de Estacas","description":"Llena el área de estacas de piedra: 19–23 de tierra en radio 2 y 5–8 por turno durante 3 turnos a quien se quede.","flavor":"El área sigue ahí. Lo primero que suele irse es el sentido común."},
    "bruxo-terra-20": {"name":"Anillo de Menhires","description":"Un anillo de piedras sube a 2 casillas del centro: 32–38 de tierra y 0 PP por 2 turnos a quien esté en el anillo.","flavor":"Quien diseñó los círculos de piedra no los diseñó para quedarse adentro."},
    "bruxo-terra-30": {"name":"La Lousa Desciende","description":"Baja un palmo del cielo de piedra: 47–56 de tierra en radio 3, 3 turnos sin PP y toda la sala en temblor.","flavor":"Es el hechizo más prohibido de la escuela: repite, en miniatura, el día en que todo acabó."},
    "bruxo-ar-5": {"name":"Chasquido","description":"Un chasquido seco de presión: 14–19 de aire por solo 2 PA, hasta 6 casillas.","flavor":"Chasquea los dedos. El aire del otro lado de la sala chasquea con él."},
    "bruxo-ar-10": {"name":"Chispa Saltarina","description":"29–36 de aire que saltan a otros 2 enemigos cercanos, perdiendo 30% de fuerza en cada salto.","flavor":"Busca compañía. Siempre la encuentra."},
    "bruxo-ar-12": {"name":"Paso del Brujo","description":"Se teletransporta a una casilla vacía hasta a 5 de distancia. El mago frágil necesita una salida.","flavor":"No es magia elegante. Es la magia de quien no quiere recibir golpes."},
    "bruxo-ar-15": {"name":"Cono de Vendaval","description":"Un abanico de viento comprimido: 23–29 de aire y 3 casillas de lanzamiento a todo lo que esté en el cono.","flavor":"Los respiraderos del Cierre gimen cuando lo hace. Le parece bonito."},
    "bruxo-ar-20": {"name":"Tronada","description":"32–39 de aire que recorren hasta 5 cuerpos (4 saltos), perdiendo 25% en cada salto. La sala entera en un solo gesto.","flavor":"Jamás hubo trueno bajo la Lousa. Cree que hace falta."},
    "bruxo-ar-30": {"name":"Ojo de la Tempestad","description":"Abre un ojo de tempestad en radio 3: 41–50 de aire, 4 casillas de lanzamiento, descargas de 21–27 saltando por otros 4 cuerpos — y vendaval en la sala.","flavor":"Nadie bajo la Lousa había visto una tempestad. Ahora todos han visto una. Solo una."},
    "espadachim-neutro-1": {"name":"Estocada Rápida","description":"21–28 de daño neutro por 2 PA, dos veces por turno. Barato, rápido, sin drama.","flavor":"La hoja entra por el hueco entre la armadura y la distracción."},
    "espadachim-neutro-2": {"name":"Sombra Corta","description":"Desaparece entre dos linternas: invisible por 2 turnos enteros y +20 de esquiva por 2.","flavor":"En un mundo sin cielo, la sombra es el único lugar con espacio de sobra."},
    "espadachim-neutro-3": {"name":"Paso Lateral","description":"Se desliza hasta 4 casillas sin gastar PP, normalmente a la espalda de alguien.","flavor":"No rodea al enemigo. Es el enemigo el que queda mirando hacia el lado equivocado."},
    "espadachim-fogo-5": {"name":"Hoja de Brasa","description":"31–39 de fuego y quemadura de 7–11 por 2 turnos. Dos veces por turno.","flavor":"La hoja se pone roja sola desde que duerme con ella."},
    "espadachim-fogo-10": {"name":"Doble Corte Ardiente","description":"Dos cortes en X: 50–62 de fuego y 8–13 de quemadura por 2 turnos.","flavor":"El segundo corte es solo para que el primero no se enfríe."},
    "espadachim-fogo-12": {"name":"Venas en Llamas","description":"Calienta su propia sangre: +40 de poder por 2 turnos, a costa de 8–11 de quemadura propia por turno.","flavor":"Apuesta vieja: duele ahora, mata primero."},
    "espadachim-fogo-15": {"name":"Danza de Chispas","description":"Gira con las dos hojas encendidas: 42–53 de fuego en radio 1 y quemadura de 11–15 por 2 turnos.","flavor":"Quien lo rodeó paga la entrada del espectáculo."},
    "espadachim-fogo-20": {"name":"Estocada Escaldante","description":"La hoja entra en brasa blanca: 78–92 de fuego y 17–22 de quemadura por 2 turnos.","flavor":"Cauteriza en el camino de vuelta. Casi un favor."},
    "espadachim-fogo-30": {"name":"Siete Cortes de Llama","description":"Siete cortes en una sola respiración: disuelve el escudo del objetivo, 106–124 de fuego y quemadura de 23–30 por 3 turnos.","flavor":"Dicen que el séptimo corte llega cuando el objetivo ya cayó. Por capricho."},
    "espadachim-agua-5": {"name":"Hoja Sedienta","description":"31–39 de agua con robo de vida, dos veces por turno: el asesino que se mantiene solo.","flavor":"La hoja no está mojada. Tiene sed."},
    "espadachim-agua-10": {"name":"Niebla Salada","description":"Desaparece en una niebla de sal por 2 turnos y lava venenos y raíces del cuerpo.","flavor":"La sal cura, esconde, conserva. Él usa los tres sentidos."},
    "espadachim-agua-12": {"name":"Corte de la Corriente","description":"39–49 de agua hasta 2 casillas y 2 de empuje: corta y aparta antes de la respuesta.","flavor":"Corta a la ida y la corriente hace el resto del trabajo."},
    "espadachim-agua-15": {"name":"Paso de Lodo","description":"Resbala hasta 5 casillas por cualquier superficie mojada, sin gastar PP.","flavor":"Lo aprendió de los ahogadizos. Solo no aprendió la parte de hundirse."},
    "espadachim-agua-20": {"name":"Sanguijuela","description":"73–87 de agua con robo de vida y 14–20 de veneno por 2 turnos. Un golpe que paga su propia cuenta.","flavor":"No es crueldad. Es logística."},
    "espadachim-agua-30": {"name":"Ahogar en Sangre","description":"103–122 de agua con robo de vida (la mitad vuelve como vida), veneno de 16–21 por 3 turnos y 1 turno sin PP.","flavor":"La corte ahogada aplaudió. Fue la primera vez en mil años que alguien bailó bien."},
    "espadachim-terra-5": {"name":"Hoja Oxidada","description":"25–32 de tierra y 7–12 de infección por 3 turnos. El veneno del espadachín es paciente.","flavor":"No afila la hoja. Solo la deja lo bastante sucia."},
    "espadachim-terra-10": {"name":"Corte al Tobillo","description":"31–38 de tierra y 0 PP por 2 turnos: quien no anda no escapa del siguiente golpe.","flavor":"Regla del cuchillo: primero quita la huida, después lo demás."},
    "espadachim-terra-12": {"name":"Piel de Corteza","description":"Se cubre de corteza seca: 70 de escudo y 20% de resistencia a tierra por 2 turnos. El asesino también debe sobrevivir al contraataque.","flavor":"Corteza de un árbol que murió el día de la Lousa y nunca aceptó pudrirse."},
    "espadachim-terra-15": {"name":"Puñal de Sílex","description":"58–70 de tierra y 10–15 de infección por 3 turnos. La astilla se queda dentro.","flavor":"La piedra astillada ni se oxida ni perdona."},
    "espadachim-terra-20": {"name":"Emboscada Enterrada","description":"Se entierra en el polvo y espera: invisible por 2 turnos, +45 de poder y +20 de traba. El siguiente golpe es otro golpe.","flavor":"La paciencia es un arma que no hace ruido al desenvainarse."},
    "espadachim-terra-30": {"name":"Estocada del Menhir","description":"Clava la hoja como quien hinca un menhir: 99–118 de tierra, 3 turnos sin PP y 14–19 de infección por turno.","flavor":"Se queda de pie por educación. El cuerpo ya entendió que acabó."},
    "espadachim-ar-5": {"name":"Corte de Viento","description":"26–35 de aire hasta 2 casillas por 2 PA, dos veces por turno. Corta antes de tocar.","flavor":"El corte llega medio paso antes que la hoja. Nadie sabe explicarlo; él tampoco."},
    "espadachim-ar-10": {"name":"Paso del Viento","description":"Se teletransporta a cualquier casilla vacía hasta 6 de distancia. Entrada, salida o ambas.","flavor":"El aire del Cierre le debe algún favor antiguo."},
    "espadachim-ar-12": {"name":"Aliento Robado","description":"+2 PP y +25 de esquiva por 2 turnos: cruza la sala y escapa de cualquier traba.","flavor":"Roba aliento de los respiraderos. Lo devuelve en forma de problema."},
    "espadachim-ar-15": {"name":"Corte en Cadena","description":"56–70 de aire que saltan a 3 enemigos cercanos más, perdiendo 25% por salto.","flavor":"Un solo corte. La repetición es problema del viento."},
    "espadachim-ar-20": {"name":"Cambio de Sombras","description":"Cambia de lugar con cualquier unidad y corta al llegar: 53–66 de aire. Rescata a un aliado o entrega un enemigo.","flavor":"Cree que el tablero siempre está un poco mal."},
    "espadachim-ar-30": {"name":"Mil Cortes de Viento","description":"89–106 de aire que recorren hasta 6 cuerpos (5 saltos, solo −15% cada uno) y empujan a todos 2 casillas.","flavor":"Desenvaina una vez. El sonido llega después, y en varias partes de la sala."},
    "curandeiro-neutro-1": {"name":"Imposición de Manos","description":"Cura 21–26 de vida a un aliado (o a sí misma), dos veces por turno.","flavor":"Antes escupe en la mano. Dice que ayuda. Nadie se atreve a discrepar."},
    "curandeiro-neutro-2": {"name":"Espada Terca","description":"18–23 de daño neutro. La paladina también ataca, y la espada pesa como el deber.","flavor":"Era de la abuela. La abuela también pegaba con ella."},
    "curandeiro-neutro-3": {"name":"Bendición Breve","description":"+20 de poder a un aliado por 2 turnos. Corta, y hace una diferencia enorme.","flavor":"Alza el escudo ante el bárbaro antes de cada embestida. Él espera, por respeto."},
    "curandeiro-fogo-5": {"name":"Compresa Escaldante","description":"Cura 20–24 y da 15% de resistencia a fuego por 2 turnos. Arde, pero cierra.","flavor":"\"Va a arder un poquito.\" Siempre arde mucho."},
    "curandeiro-fogo-10": {"name":"Brasa Curativa","description":"19–24 de fuego a un enemigo, y la mitad vuelve como vida para ella. Curar atacando es el camino del fuego.","flavor":"La abuela lo llamaba \"reciclaje\"."},
    "curandeiro-fogo-12": {"name":"Aliento de Fragua","description":"+35 de poder y regeneración de 11–14 por 2 turnos a un aliado. Enciende a quien ya estaba caliente.","flavor":"Sopla al aliado como quien sopla brasa de forja. Funciona igual."},
    "curandeiro-fogo-15": {"name":"Anillo de Cenizas","description":"Golpea el escudo en el suelo y suelta un anillo de cenizas: 26–33 de fuego en radio 1 y 6–9 de quemadura por 2 turnos.","flavor":"Armadura clara y un ruido que llega al techo."},
    "curandeiro-fogo-20": {"name":"Corazón de Brasa","description":"Cura 53–65 y da +30 de poder por 2 turnos a todos los aliados en radio 2.","flavor":"Presta su propio corazón de brasa. Se devuelve en victoria."},
    "curandeiro-fogo-30": {"name":"La Llama que Cuida","description":"Cura 88–104 en radio 2, regenera 25–32 por 3 turnos, da +45 de poder y limpia venenos y raíces de todos los aliados.","flavor":"La linterna de la abuela tenía una sola luciérnaga. Ella descubrió cómo encender toda la sala con ella."},
    "curandeiro-agua-5": {"name":"Gota Buena","description":"Cura 24–29 hasta 6 casillas, dos veces por turno. La curación más eficiente del juego.","flavor":"Una gota. Promete que es solo una gota."},
    "curandeiro-agua-10": {"name":"Fuente Serena","description":"Regeneración de 14–19 por 3 turnos y limpieza de todos los venenos del aliado.","flavor":"Apoya la manopla en el suelo y sale agua. Nunca lo explicó."},
    "curandeiro-agua-12": {"name":"Tirón de Marea","description":"Atrae a cualquier unidad 3 casillas: rescata al aliado herido o saca al enemigo de su línea de tiro.","flavor":"\"Ven acá.\" Y viene."},
    "curandeiro-agua-15": {"name":"Ola Buena","description":"Cura 48–58 a todos los aliados en radio 2.","flavor":"La marea que sube levanta todos los barcos, incluso los agujereados."},
    "curandeiro-agua-20": {"name":"Corriente Sanadora","description":"Cura 59–69 al instante y 14–19 más por turno durante 2 turnos. El botón de \"no mueras\".","flavor":"El agua corriente no junta polvo. Ni luto."},
    "curandeiro-agua-30": {"name":"La Cisterna Buena","description":"Cura 88–104 en radio 3, regenera 27–36 por 3 turnos, limpia venenos y raíces, y hace llover dentro del Cierre.","flavor":"Hay una cisterna que mató a una corte entera. Ella pidió prestada la misma agua, con mejores modales."},
    "curandeiro-terra-5": {"name":"Corteza Amiga","description":"32 de escudo a un aliado por 2 turnos, dos veces por turno. El escudo es la curación que llega antes.","flavor":"Pide permiso al árbol muerto y el árbol presta la corteza."},
    "curandeiro-terra-10": {"name":"Emplasto de Barro","description":"Cura 28–33 y da 20% de resistencia a tierra por 2 turnos.","flavor":"Barro del arriate hondo. Huele mal, cura bien."},
    "curandeiro-terra-12": {"name":"Raíz Celosa","description":"Raíces atrapan a quien molesta: 0 PP por 2 turnos y 17–22 de tierra en radio 1.","flavor":"\"Quédate quietecito que ya vuelvo.\" Nadie se queda quietecito por voluntad propia."},
    "curandeiro-terra-15": {"name":"Cúpula de Raíces","description":"78 de escudo y regeneración de 12–17 por 2 turnos a todos los aliados en radio 2.","flavor":"Un invernadero portátil, hecho a las apuradas, con lo que había en el bolsillo."},
    "curandeiro-terra-20": {"name":"Piedra Amparo","description":"Cura 58–69, viste 75 de escudo por 2 turnos y arranca las raíces que sujetaban al aliado.","flavor":"Llega, empuja la piedra y el mundo deja de resbalar por un instante."},
    "curandeiro-terra-30": {"name":"Jardín Cerrado","description":"Cierra un jardín entero alrededor del grupo: cura 84–100, 176 de escudo, 25% de resistencia a tierra y 22–27 de regeneración por 3 turnos, en radio 3.","flavor":"Así hicieron los constructores los Cierres. Ella solo copió la idea, en tamaño de bolsillo."},
    "curandeiro-ar-5": {"name":"Soplo Dulce","description":"Cura 15–20 por solo 2 PA, dos veces por turno. Cura poco, cura siempre, sobran PA.","flavor":"Sopla la herida. Científicamente indefendible; funciona."},
    "curandeiro-ar-10": {"name":"Aliento Prestado","description":"+2 PP por 1 turno y +20 de iniciativa por 2 a un aliado: alcances que no existían pasan a existir.","flavor":"Guarda suspiros en un frasquito. Dice que son de gente que ya no los necesitaba."},
    "curandeiro-ar-12": {"name":"Cambio de Lugar","description":"Cambia de posición con cualquier unidad hasta 6 casillas. Saca al aliado del cerco y ocupa su lugar.","flavor":"Nunca fue de huir. Solo de cambiar de lugar con quien lo necesitaba más."},
    "curandeiro-ar-15": {"name":"Ráfaga Amiga","description":"Un soplo en abanico: 33–41 de aire y 3 casillas de empuje. Abre espacio alrededor de quien está cayendo.","flavor":"\"¡Permiso!\" Y media sala retrocede."},
    "curandeiro-ar-20": {"name":"Brisa Reparadora","description":"Cura 51–61 y da +1 PP por 2 turnos a todos los aliados en radio 2.","flavor":"Cura andando. El grupo entero aprende a andar junto."},
    "curandeiro-ar-30": {"name":"Respiración del Cierre","description":"Abre todos los respiraderos de la sala: cura 84–100 en radio 3, +2 PP y +40 de iniciativa por 3 turnos, y limpia venenos y raíces.","flavor":"Por tres turnos, todo el Cierre respira a su ritmo. Después vuelve a sofocar, como siempre."},
    "invocador-neutro-1": {"name":"Llamado Menor","description":"Invoca un Familiar en una casilla vacía: un cuerpo más para morder, aguantar y negar el paso.","flavor":"Nunca dice el nombre de la bestia. Dice que el nombre es compromiso."},
    "invocador-neutro-2": {"name":"Verbo del Pacto","description":"13–18 de daño neutro hasta 5 casillas. También ataca, cuando el rebaño está ocupado.","flavor":"La página la escribió alguien que también llamaba cosas. Nadie sabe con qué."},
    "invocador-neutro-3": {"name":"Estaca-Alarma","description":"Arma una estaca en la casilla elegida por 3 rondas: quien pise recibe 11–15 de daño y pierde 1 PP.","flavor":"El mundo enterrado está lleno de pasillos. Un pasillo es lugar de trampa."},
    "invocador-fogo-5": {"name":"Trampa de Brasa","description":"Entierra carbón vivo por 3 rondas: quien pise sufre 17–21 de fuego en radio 1 y se quema por 2 turnos.","flavor":"Planta brasa en fila, como quien siembra cebolla."},
    "invocador-fogo-10": {"name":"Perro de Brasa","description":"Invoca un Perro de Brasa: rápido, mordida caliente y explota al morir. Sirve vivo y muerto.","flavor":"Mueve la cola. La cola enciende el suelo."},
    "invocador-fogo-12": {"name":"Pacto Ardiente","description":"+35 de poder y 15% de resistencia a fuego por 2 turnos, para aliados y para las propias criaturas.","flavor":"Un pacto no es bondad. Es contrato con cláusula de desempeño."},
    "invocador-fogo-15": {"name":"Soplo del Pacto","description":"Algo sopla del otro lado del pacto: 24–30 de fuego en radio 1 y quemadura de 6–8 por 2 turnos.","flavor":"El soplo viene siempre de la misma dirección. Nadie quiere saber cuál."},
    "invocador-fogo-20": {"name":"Trampa-Pira","description":"Dobla una pira entera dentro de una casilla por 3 rondas: 39–47 de fuego en radio 1 y quemadura de 9–12 a quien pise.","flavor":"Avisa a los aliados por dónde no pisar. Una vez. Bajito."},
    "invocador-fogo-30": {"name":"Coloso de Magma","description":"Abre el suelo y llama a un Coloso de Magma al campo, y su calor deja la sala entera en sequía.","flavor":"El Corazón del Cierre de Brasa tiene un hermano mayor. Nadie lo invitaba desde la Lousa."},
    "invocador-agua-5": {"name":"Trampa-Remolino","description":"Abre un embudo de agua por 3 rondas: 14–18 de daño y 2 casillas de succión a quien pise.","flavor":"Un desagüe con opinión propia sobre por dónde debería andar la gente."},
    "invocador-agua-10": {"name":"Ninfa de la Marea","description":"Invoca una Ninfa de la Marea: cura a los aliados por su cuenta mientras el invocador se ocupa del resto.","flavor":"Nunca habla. Solo mira a quien sangra y lo resuelve."},
    "invocador-agua-12": {"name":"Pacto de la Fuente","description":"Regeneración de 10–13 por 3 turnos y limpieza de venenos en un aliado o criatura invocada.","flavor":"Firmado con agua. Es el tipo de contrato que luego se puede beber."},
    "invocador-agua-15": {"name":"Llamado de la Resaca","description":"23–29 de agua con robo de vida en radio 1 y 2 casillas de succión: arrastra al enemigo al centro del rebaño.","flavor":"Llama a la resaca como se llama a un perro grande: con cuidado."},
    "invocador-agua-20": {"name":"Trampa-Sumidero","description":"Un desagüe del mundo antiguo, armado por 3 rondas: 35–42 de agua en radio 1 y 3 casillas de succión.","flavor":"Destapó algo que los constructores habían tapado a propósito."},
    "invocador-agua-30": {"name":"Ahogado de la Cisterna","description":"Abre la tapa y deja subir lo que estaba abajo, y la lluvia viene con ello.","flavor":"La cisterna devuelve lo que tragó. Nunca de a uno."},
    "invocador-terra-5": {"name":"Trampa-Lazo","description":"Esconde un lazo de raíces por 3 rondas: 13–17 de tierra y 0 PP por 2 turnos a quien pise.","flavor":"Al micelio le encanta ese pedido. Lo hace gratis."},
    "invocador-terra-10": {"name":"Centinela de Piedra","description":"Invoca un Centinela de Piedra: lento, duro y terco, el tapón de pasillo del invocador.","flavor":"Se queda donde lo pusieron. Es lo más confiable del mundo enterrado."},
    "invocador-terra-12": {"name":"Pacto de Corteza","description":"41 de escudo y 20% de resistencia a tierra por 2 turnos a un aliado o criatura invocada.","flavor":"Corteza prestada de la propia pared del Cierre. La pared no se quejó."},
    "invocador-terra-15": {"name":"Estacas del Pacto","description":"Estacas suben del suelo en radio 1: 23–29 de tierra y 0 PP por 2 turnos. Prepara la casilla para la siguiente trampa.","flavor":"Primero atrapa, luego arma, luego espera. Siempre en ese orden."},
    "invocador-terra-20": {"name":"Trampa-Temblor","description":"Debilita la losa por 3 rondas: quien pise sufre 36–44 de tierra en radio 1 y queda 2 turnos sin PP.","flavor":"La mina trémula enseñó: no todo suelo está obligado a seguir siendo suelo."},
    "invocador-terra-30": {"name":"Gólem de la Montaña","description":"Levanta un Gólem de la Montaña: la criatura más dura que el mundo enterrado puede prestar. Un segundo tanque, gratis, cada turno.","flavor":"No invocó la montaña. Solo preguntó si se animaba a dar unos pasos."},
    "invocador-ar-5": {"name":"Trampa-Ráfaga","description":"Tapa un respiradero por 3 rondas: quien pise recibe 13–18 de aire y sale volando 3 casillas.","flavor":"Aire viejo, guardado con rabia. Vale por una patada."},
    "invocador-ar-10": {"name":"Halcón de la Tormenta","description":"Invoca un Halcón de la Tormenta: muchos PP, iniciativa alta y un pico que empuja. Llega antes que todos.","flavor":"No hay cielo para que vuele. Vuela igual, de rabia."},
    "invocador-ar-12": {"name":"Pacto del Viento","description":"+2 PP y +25 de iniciativa por 2 turnos a un aliado o criatura: todo el rebaño llega antes.","flavor":"Contrato corto, firmado en el aire, sin testigos."},
    "invocador-ar-15": {"name":"Soplo Cortante","description":"Un abanico de viento afilado: 28–35 de aire y 3 casillas de empuje, directo sobre las trampas.","flavor":"No empuja lejos. Empuja adonde ya está armado."},
    "invocador-ar-20": {"name":"Trampa-Vórtice","description":"Ata un nudo de viento en la casilla por 3 rondas: 38–47 de aire en radio 1 y 4 casillas de lanzamiento a quien pise.","flavor":"Desatar es fácil: basta pisar. Siempre es fácil, del lado equivocado."},
    "invocador-ar-30": {"name":"Ojo de la Tormenta","description":"Planta el centro quieto de la tempestad en el campo, y el vendaval se instala a su alrededor.","flavor":"En medio de la tempestad hay un lugar quieto. Ahí vive él."},
    "minotauro-neutro-1": {"name":"Topetazo","description":"Baja la cabeza y empuja: 16–22 de daño neutro y 1 casilla de empuje.","flavor":"No persigue. Decide por dónde no vas a pasar."},
    "minotauro-neutro-2": {"name":"Escudo de Hombro","description":"Pone su propio escudo delante de un aliado: 80 de escudo por 2 turnos.","flavor":"El escudo es suyo. La vida que guarda es tuya."},
    "minotauro-neutro-3": {"name":"Primera Piedra","description":"Alza un muro en una casilla vacía por 2 turnos: bloquea paso y visión. Las espinas hieren 30 al enemigo que termine su turno pegado o sea arrojado contra la piedra.","flavor":"No es para proteger a nadie. Es para que el otro tenga que dar la vuelta."},
    "minotauro-fogo-5": {"name":"Muro en Brasa","description":"Muro de 2 turnos que deja brasa armada al pie: quien pise se quema. Las espinas hieren 30 al enemigo que termine su turno pegado o sea arrojado contra la piedra.","flavor":"La piedra se enfría. La brasa debajo, no."},
    "minotauro-fogo-10": {"name":"Cuero Hirviente","description":"110 de escudo y devuelve 25% del daño recibido por 2 turnos.","flavor":"Le pegas y la mano te vuelve doliendo."},
    "minotauro-fogo-12": {"name":"Cornada Encendida","description":"25–33 de fuego en abanico al frente y 1 casilla de empuje a todos.","flavor":"No corre detrás. Abre espacio."},
    "minotauro-fogo-15": {"name":"Cerca de Fuego","description":"Levanta una línea de 3 muros y quema 16–22 a quien estaba en el camino. Las espinas hieren 30 al enemigo que termine su turno pegado o sea arrojado contra la piedra.","flavor":"Tres piedras, una decisión: por aquí, no."},
    "minotauro-fogo-20": {"name":"Yunque Vivo","description":"160 de escudo y 35% de daño devuelto, por 3 turnos, a un aliado.","flavor":"Quien golpea el yunque aprende sobre el yunque."},
    "minotauro-fogo-30": {"name":"La Fragua Cerrada","description":"Cierra un anillo de muros en radio 2 a tu alrededor y ganas 180 de escudo por 3 turnos. Las espinas hieren 30 al enemigo que termine su turno pegado o sea arrojado contra la piedra.","flavor":"La fragua no tiene puerta. Quien entró, se queda."},
    "minotauro-agua-5": {"name":"Muro Resbaladizo","description":"Muro de 2 turnos con el suelo mojado alrededor: quien se acerca resbala. Las espinas hieren 30 al enemigo que termine su turno pegado o sea arrojado contra la piedra.","flavor":"La piedra detiene el cuerpo. El charco decide el resto."},
    "minotauro-agua-10": {"name":"Casco de Marea","description":"90 de escudo y 16–24 de vida por turno, durante 3 turnos.","flavor":"La marea golpea y devuelve. Siempre devuelve."},
    "minotauro-agua-12": {"name":"Empujón de Ola","description":"19–26 de agua en abanico y 2 casillas de empuje.","flavor":"Nadie sujeta el agua. Ella te sujeta a ti."},
    "minotauro-agua-15": {"name":"Dique","description":"Una línea de 3 muros por 3 turnos, empujando 1 casilla a quien estaba ahí. Las espinas hieren 30 al enemigo que termine su turno pegado o sea arrojado contra la piedra.","flavor":"El río no discute con el dique. Solo lo rodea."},
    "minotauro-agua-20": {"name":"Cisterna Guardada","description":"120 de escudo y 20–28 de regeneración por turno, para ti y quien esté en radio 2.","flavor":"Él guarda el agua. El agua guarda a todos."},
    "minotauro-agua-30": {"name":"El Cerco de Agua","description":"Anillo de muros en radio 2 en el objetivo: 22–30 de agua y 1 de empuje a quien quedó dentro. Las espinas hieren 30 al enemigo que termine su turno pegado o sea arrojado contra la piedra.","flavor":"Cercar no es encerrar. Es elegir la salida por él."},
    "minotauro-terra-5": {"name":"Menhir","description":"Alza un muro que dura 4 turnos, el más terco de los cuatro caminos. Las espinas hieren 30 al enemigo que termine su turno pegado o sea arrojado contra la piedra.","flavor":"Lo pusieron ahí antes de que hubiera camino. El camino fue el que dio la vuelta."},
    "minotauro-terra-10": {"name":"Corteza de Piedra","description":"140 de escudo (el más grueso del juego) y +20% de resistencia a tierra por 2 turnos.","flavor":"No es armadura. Es el suelo diciendo que hoy no."},
    "minotauro-terra-12": {"name":"Golpe de Casco","description":"20–27 de tierra en radio 1 y 0 PP por 1 turno a quien esté cerca.","flavor":"El suelo tiembla una vez. Quien estaba de pie aprende."},
    "minotauro-terra-15": {"name":"Muralla","description":"Tres muros en línea, en pie por 4 turnos. Corta la sala en dos. Las espinas hieren 30 al enemigo que termine su turno pegado o sea arrojado contra la piedra.","flavor":"Toda muralla es una frase corta: no."},
    "minotauro-terra-20": {"name":"Cimiento","description":"190 de escudo y +15% de resistencia para ti y los aliados en radio 1, por 3 turnos.","flavor":"No levanta paredes. Levanta el suelo."},
    "minotauro-terra-30": {"name":"El Laberinto","description":"Cruz de muros de 4 turnos alrededor del objetivo, y 0 PP por 1 turno a quien quedó dentro. Las espinas hieren 30 al enemigo que termine su turno pegado o sea arrojado contra la piedra.","flavor":"El laberinto es suyo. Ustedes solo están de paso."},
    "minotauro-ar-5": {"name":"Pared de Soplo","description":"Muro de 1 turno, pero alzado desde lejos, y deja una ráfaga armada alrededor. Las espinas hieren 30 al enemigo que termine su turno pegado o sea arrojado contra la piedra.","flavor":"Dura un instante. El instante era lo que faltaba."},
    "minotauro-ar-10": {"name":"Escudo Ligero","description":"70 de escudo y +1 PP por 2 turnos: el escudo que no pesa.","flavor":"Proteger no es clavar en el lugar."},
    "minotauro-ar-12": {"name":"Cuerno de Viento","description":"21–29 de aire en una línea de 3 y 2 casillas de empuje.","flavor":"La embestida pasa. Su viento continúa."},
    "minotauro-ar-15": {"name":"Cerca Voladora","description":"Tres muros en línea, alzados a 6 casillas de distancia: el mayor alcance de la clase. Las espinas hieren 30 al enemigo que termine su turno pegado o sea arrojado contra la piedra.","flavor":"Cierra la puerta del otro lado de la sala."},
    "minotauro-ar-20": {"name":"Guardia Errante","description":"130 de escudo y +2 PP por 3 turnos. Protege a quien necesita correr.","flavor":"Su guardia anda contigo."},
    "minotauro-ar-30": {"name":"El Corral de Viento","description":"Anillo de muros hasta 6 casillas: empuja 2, causa 22–30 de aire y cierra el cerco. Las espinas hieren 30 al enemigo que termine su turno pegado o sea arrojado contra la piedra.","flavor":"Un corral no tiene que ser grande. Tiene que estar cerrado."}
  },
  "monsterSpells": {
    "m-thorn-shot": {"name":"Púa","description":"El vergajo azota el aire y dispara una espina dentada que silba hasta acertar.","flavor":"No corre tras nadie. No hace falta."},
    "m-root-grip": {"name":"Raíz-Traba","description":"Raíces brotan del piso y agarran los tobillos del objetivo: atrapado por 1 turno.","flavor":"El invernadero cree que eres abono en movimiento."},
    "m-pollen-bite": {"name":"Mordisco","description":"Un mordisco suave de dientecitos de polen. El peligro de verdad viene después.","flavor":"Sonríe todo el tiempo. Cosido, pero sonríe."},
    "m-burr-hug": {"name":"Abrazo Espinoso","description":"El abrojo se lanza sobre el objetivo y se pega, púas hacia adentro.","flavor":"Cariño de ovillo: duele y no se va."},
    "m-wasp-sting": {"name":"Aguijón Lustroso","description":"El aguijón de la avispa inyecta un veneno luminoso que arde por 2 turnos.","flavor":"La luz del abdomen es el último aviso amistoso del jardín."},
    "m-sap-mend": {"name":"Savia Dulce","description":"El saviero vierte savia dorada sobre las heridas de un aliado.","flavor":"Riega todo con el mismo cariño. Incluso lo que debería morir."},
    "m-sap-sugar": {"name":"Azúcar Bruta","description":"Una dosis de azúcar bruta deja al aliado frenético: +15 de poder por 2 turnos.","flavor":"Ninguna planta de esta sala sabe qué es la moderación."},
    "m-dew-web": {"name":"Tela de Rocío","description":"Hilos pesados de rocío se cierran sobre los pies del objetivo y se endurecen: atrapado por 1 turno.","flavor":"Cada gota de la tela es una lupa. Le gusta ver de cerca."},
    "m-dew-bite": {"name":"Picada de Rocío","description":"Los quelíceros inyectan una gota de agua vieja y quieta que pudre por dentro.","flavor":"Agua de invernadero: nunca hirvió, nunca se secó, nunca perdonó."},
    "m-shears": {"name":"Tijeretazo","description":"Las tijeras de podar de la Jardinera se cierran con un chasquido húmedo.","flavor":"No mata. Poda."},
    "m-vine-hook": {"name":"Liana-Garfio","description":"Una liana espinosa engancha al objetivo y lo arrastra 3 casillas hasta las tijeras.","flavor":"La mala hierba no decide dónde la arrancan."},
    "m-seed-toss": {"name":"Siembra","description":"La Jardinera planta una semilla que germina al instante, hambrienta.","flavor":"Su jardín nunca tuvo estación muerta."},
    "m-thorn-crown": {"name":"Corona de Espinas","description":"Un anillo de espinas brota a 2 casillas de la Jardinera y se cierra: daño e inmovilización a quien estaba alrededor, pero no a quien está pegado a ella.","flavor":"Demasiado cerca para la corona. Es el único lugar seguro del quiosco."},
    "m-sprout-bite": {"name":"Dientecitos","description":"El brotecito muerde con todas sus filas de dientes de semilla.","flavor":"Nació hace diez segundos y ya tiene enemigos."},
    "m-burr-nip": {"name":"Espinita","description":"Pequeño, pegajoso e irritante.","flavor":"La mitad del rencor, el doble de velocidad."},
    "m-spore-nip": {"name":"Mordisquito Pútrido","description":"El espolín muerde y deja moho en la herida.","flavor":"Ojos demasiado grandes, lealtad aún mayor."},
    "m-drowned-bite": {"name":"Tarascada","description":"El ahogadizo muerde y bebe: roba la vida que le falta.","flavor":"No tiene hambre. Tiene frío."},
    "m-eel-beam": {"name":"Nota Grave","description":"La morena sopla una nota por la flauta de su propio cráneo: un chorro de agua en línea recta.","flavor":"Sal de la línea. Ella te vuelve a poner en ella."},
    "m-eel-hook": {"name":"Lengua-Garfio","description":"Una lengua-arpón se dispara en línea recta y arrastra a la presa hacia el agua.","flavor":"Invitación formal de la corte ahogada."},
    "m-jelly-mend": {"name":"Pulso Salino","description":"La medusa pulsa y baña a un aliado en salmuera restauradora.","flavor":"Apaga el candelabro antes de discutir con los invitados."},
    "m-jelly-ward": {"name":"Membrana","description":"Una película gelatinosa envuelve al aliado y absorbe golpes.","flavor":"Translúcida, tibia, profundamente desagradable."},
    "m-brine-fist": {"name":"Puño de Salmuera","description":"Un puño de sal compacta cae como un ariete.","flavor":"Marea baja para andar, marea alta para golpear."},
    "m-drop-slam": {"name":"Chapoteo","description":"La gota se lanza entera sobre el objetivo. Es exactamente el sonido que imaginas.","flavor":"Chapoteo."},
    "m-droplet-splash": {"name":"Gota","description":"La gotita se lanza contra la espinilla del objetivo con toda la indignación que tiene. Plic.","flavor":"Pequeña, redonda, indignada."},
    "m-crab-pinch": {"name":"Pinza de Sumidero","description":"La pinza cierra con un chasquido de piedra y devuelve al objetivo una casilla atrás.","flavor":"Vive en el desagüe. El desagüe es suyo."},
    "m-crab-guard": {"name":"Casco Cerrado","description":"El cangrejo se cierra entero: 25 de escudo y +20% de resistencia a agua por 2 turnos.","flavor":"Mil años bajo el agua enseñan a cerrar la puerta."},
    "m-mist-song": {"name":"Cantar de Niebla","description":"Un silbido fino y desafinado deja resbaloso al aliado: +12 de esquiva por 2 turnos.","flavor":"La nota justa es la que nadie logra sostener."},
    "m-mist-shove": {"name":"Soplo de Niebla","description":"Una ráfaga húmeda empuja al objetivo 2 casillas, de preferencia hacia el canal.","flavor":"La cisterna tiene muchos agujeros y ninguna paciencia."},
    "m-tide-pull": {"name":"Marea Hambrienta","description":"La Baronesa inspira, y toda la sala se vuelve marea: todo en un radio de 3 casillas es arrastrado hasta ella.","flavor":"Ella recibe. Nadie rechaza la invitación de una anfitriona."},
    "m-bitter-gulp": {"name":"Trago Amargo","description":"La Baronesa se traga todo a su alrededor en un solo trago de salmuera ácida, que sigue corroyendo por 2 turnos.","flavor":"Atrae en un turno, bebe en el otro. Sal entre uno y otro."},
    "m-salt-lance": {"name":"Lanza de Sal","description":"Un cristal de sal afilado cruza la sala girando.","flavor":"Cubiertos de la corte."},
    "m-brine-spawn": {"name":"Verter","description":"La Baronesa se desborda, y lo que escurre cobra voluntad propia.","flavor":"Todo baile tiene invitados que nadie llamó."},
    "m-ember-claw": {"name":"Garra Encendida","description":"El tizón desgarra con garras en brasa viva.","flavor":"La risa es la mecha."},
    "m-anvil-crush": {"name":"Aplastamiento","description":"El yunque simplemente cae encima. Física básica, resultados excelentes.","flavor":"Nómbrala al final, pero nómbrala."},
    "m-ash-bolt": {"name":"Flecha de Ceniza","description":"El ceniciento señala con el dedo y el hollín obedece, volando en flecha.","flavor":"El hollín es solo fuego que aprendió a flotar."},
    "m-ash-veil": {"name":"Sudario de Ceniza","description":"El ceniciento se deshace en hollín suspendido por 1 turno: imposible de apuntar.","flavor":"Cambia de objetivo, o adivina."},
    "m-slag-slam": {"name":"Peso Muerto","description":"El montón de escoria se desploma sobre el objetivo en cámara lenta, hirviendo.","flavor":"Aquí empieza una muerte en tres actos."},
    "m-smith-hammer": {"name":"Mazazo","description":"El herrero trata al objetivo como una pieza mal forjada.","flavor":"Sin rostro, sin prisa, sin error."},
    "m-forge-temper": {"name":"Temple","description":"El herrero martilla al aliado como quien afila un arma: +20 de poder por 2 turnos.","flavor":"Un Yunque templado desmonta a un héroe."},
    "m-smith-plate": {"name":"Plancha Caliente","description":"Una placa de metal aún al rojo se suelda al aliado: 20 de escudo.","flavor":"Duele a los dos. Solo uno se preocupa."},
    "m-quench-lunge": {"name":"Embate de Temple","description":"El perro salta del foso de temple hasta 4 casillas y muerde aún goteando.","flavor":"Nació del agua que apaga espadas."},
    "m-quench-hiss": {"name":"Chirrido","description":"Un chorro de vapor hirviente despega el escudo del objetivo antes de quemarlo.","flavor":"El ruido que hace una protección al rendirse."},
    "m-chain-yank": {"name":"Tirón de Cadena","description":"La cadena del techo enlaza al objetivo, lo arrastra 3 casillas y lo sujeta al gancho por 1 turno.","flavor":"La fragua siempre necesitó carne colgada."},
    "m-chain-lash": {"name":"Cadenazo","description":"Eslabones gruesos giran y golpean de plano.","flavor":"Nada elegante. Muy eficaz."},
    "m-doom-hammer": {"name":"Martillo del Fin","description":"Magno alza el martillo con que se forjó el primer Cierre, y el mundo cruje cuando baja.","flavor":"La cruz entera paga por el objetivo que él eligió."},
    "m-bellows-blast": {"name":"Soplo de Fragua","description":"El pecho-fragua de Magno expulsa un vendaval incandescente que lanza al objetivo 3 casillas.","flavor":"De espaldas al foso, eso es una sentencia."},
    "m-spark-call": {"name":"Llamar Chispas","description":"Magno chasquea los dedos y una chispa echa a andar, con pésimas intenciones.","flavor":"Fabrica su propio ejército desechable."},
    "m-heart-brand": {"name":"Marca del Encendedor","description":"Magno acerca la llama al objetivo y deja una marca en brasa: +5% de daño recibido por acumulación, hasta 5 acumulaciones.","flavor":"Marca la pieza antes de golpearla."},
    "m-anvil-verdict": {"name":"Veredicto del Yunque","description":"Magno consume todas las marcas del objetivo de una vez: 9 de daño por acumulación.","flavor":"La pieza marcada vuelve al yunque. Siempre."},
    "m-stoke": {"name":"Avivarse","description":"Magno abre la parrilla de su propio pecho y sopla las brasas: +25 de poder.","flavor":"La fragua respira. La segunda mitad de la pelea es otra pelea."},
    "m-spark-tap": {"name":"Chasquido","description":"La chispa se pega y estalla. Duele más de lo que parece.","flavor":"Vive poco, acaba a lo grande."},
    "m-slag-drip": {"name":"Salpicadura","description":"Una salpicadura de escoria hirviente.","flavor":"Un trozo aún al rojo, arrastrándose con propósito."},
    "m-shrike-dive": {"name":"Rasante","description":"El alcaudón baja en picada por el vano del andamio y golpea al final de la caída.","flavor":"Usa la altura como si fuera un arma. Lo es."},
    "m-shrike-peck": {"name":"Picotazo de Tabla","description":"Un picotazo seco que empuja al objetivo una casilla atrás; en el andamio, una casilla es mucho.","flavor":"Empala lo que sobra en los clavos."},
    "m-gremlin-shove": {"name":"Encontronazo","description":"El gremlin da un hombrazo entusiasta y manda al objetivo 2 casillas hacia donde no hay suelo.","flavor":"Le parece hilarante. Todos los días."},
    "m-gremlin-swap": {"name":"Cambio-Tabla","description":"El gremlin cambia de lugar con la víctima, casi siempre para dejarla al borde.","flavor":"Nunca se queda con la peor tabla."},
    "m-rope-noose": {"name":"Lazo de Obra","description":"La soga viene en línea recta, enlaza y recoge 3 casillas, y el nudo sujeta por 1 turno.","flavor":"La obra recoge el material."},
    "m-rope-cinch": {"name":"Apretón de Nudo","description":"El nudo aprieta y deja la marca de la soga en la carne: +4% de daño recibido por acumulación.","flavor":"Cada vuelta de la soga es una promesa."},
    "m-kite-arc": {"name":"Arco de Pipa","description":"El hilo de la sierpe-pipa raya el aire cargado y salta hasta 2 enemigos vecinos, debilitándose en cada salto.","flavor":"En el vendaval, todo aquí es pararrayos."},
    "m-kite-whip": {"name":"Latigazo de Hilo","description":"La cola de cinta corta con el hilo de vidrio molido que la recubre.","flavor":"Hilo de cometa con vidrio corta el cuello de su dueño."},
    "m-ballast-drop": {"name":"Caída de Lastre","description":"El gólem vuelca un saco de piedras de su propio tronco sobre el objetivo.","flavor":"Es el único aquí que pesa. Se empeña en demostrarlo."},
    "m-ballast-anchor": {"name":"Anclar","description":"El gólem clava los pies en las juntas del andamio: 30 de escudo y provocación por 2 turnos.","flavor":"Mientras sostiene el viento, el viento lo consume."},
    "m-choir-hymn": {"name":"Silbido Coral","description":"Los tubos del coro afinan al mismo tono: el aliado se recompone y queda más resbaloso.","flavor":"Cuando cantan juntos, toda la obra vibra."},
    "m-choir-clear": {"name":"Soplo Limpio","description":"Una ráfaga limpia veneno, nudos y marcas del aliado, y deja una corriente tibia regenerando.","flavor":"Ventilar es la religión local."},
    "m-mote-buzz": {"name":"Zumbido","description":"El enjambre pasa rozando y se lleva un pedazo.","flavor":"Mil bichitos, una opinión."},
    "m-mote-nip": {"name":"Aguijón de Mota","description":"Una mota solitaria hace lo que puede.","flavor":"Solo es cómico. En dos, no tanto."},
    "m-nail-jab": {"name":"Pinchazo","description":"Un clavo vivo salta y se entierra donde cae.","flavor":"A la obra aún le sobran clavos."},
    "m-scaffold-collapse": {"name":"Derrumbar el Ala","description":"Cambota patea la viga maestra y toda la línea cede: daño y lanzamiento de 3 casillas.","flavor":"Derriba su propia obra sin dudar. Reconstruye después."},
    "m-rivet-volley": {"name":"Salva de Remaches","description":"Un abanico de remaches al rojo clavado en un cono de 3 casillas: cada remache es una marca abierta.","flavor":"Te convierte en parte de la estructura."},
    "m-raise-frame": {"name":"Levantar Plomada","description":"Cambota planta una armazón nueva y de ella sale caminando un clavín.","flavor":"La obra nunca para. Ese es el problema."},
    "m-headwind": {"name":"Viento de Proa","description":"Cambota abre todas las compuertas del pozo: el vendaval vuelve a soplar y él queda imposible de sujetar.","flavor":"La sala es su herramienta. Tú estás de visita."},
    "m-pick-swing": {"name":"Picazo","description":"El pico abre una fisura en la armadura y deja la marca de la veta: +5% de daño recibido por acumulación.","flavor":"Te lee como lee la roca: buscando dónde se parte."},
    "m-pick-verdict": {"name":"Golpe de Veta","description":"El espanto golpea justo donde marcó y la roca cede: 7 de daño por acumulación.","flavor":"Toda piedra tiene un solo golpe. Él memorizó el tuyo."},
    "m-firedamp-flare": {"name":"Llamarada de Grisú","description":"El hachón escupe una lengua azul de gas encendido por la galería.","flavor":"El gas no huele. El aviso es la luz."},
    "m-firedamp-cloud": {"name":"Bolsa de Gas","description":"Una bolsa invisible se rompe y quema los pulmones de quien esté en el área por 2 turnos.","flavor":"Los mineros llevaban pájaros. Tú llevaste héroes."},
    "m-cave-bite": {"name":"Bocanada","description":"La galería se cierra sobre los dientes de piedra de Bocarra.","flavor":"Creíste que era un túnel."},
    "m-cave-roar": {"name":"Rugido de Galería","description":"El rugido recorre la cruz de galerías y obliga a todos a mirarla por 2 turnos.","flavor":"Una bocarra que exige público."},
    "m-crystal-chant": {"name":"Canto de Cristal","description":"El cristal resuena en la frecuencia de la piedra viva y recompone al aliado.","flavor":"La mina canta de vuelta a quien cava bien."},
    "m-crystal-facet": {"name":"Faceta Espejada","description":"Una cáscara de cuarzo cubre al aliado: 22 de escudo y 20% del daño recibido vuelve a quien golpeó.","flavor":"Golpearlo es golpearte a ti mismo, con retraso."},
    "m-worm-drag": {"name":"Arrastre de Derrumbe","description":"El suelo se desmorona en embudo y el objetivo se desliza 3 casillas hasta la boca del gusano, atrapado en la arena.","flavor":"El piso es una opinión. Él discrepa."},
    "m-worm-spit": {"name":"Escupitajo de Grava","description":"Una ráfaga de grava triturada, caliente por la fricción.","flavor":"Mastica la mina y devuelve la parte inútil."},
    "m-tumbler-roll": {"name":"Rodada","description":"El rodillo de mineral toma impulso hasta 4 casillas y atropella lo que haya al final del riel.","flavor":"Toda la mina es una cuesta, si eres redondo."},
    "m-ore-chip-hit": {"name":"Astillazo","description":"Una astilla de mineral se lanza contra la espinilla del objetivo.","flavor":"La revancha del rodillo."},
    "m-bat-screech": {"name":"Malacate de Pozo","description":"Un chillido tan agudo que empuja el aire, y al objetivo con él.","flavor":"Él ve con eso. Tú solo lo sientes."},
    "m-bat-swoop": {"name":"Vuelo Rasante","description":"El murciélago cruza el pozo en diagonal y pasa rozando con las garras.","flavor":"En el temblor pierde 5 PV por turno. Aun así insiste."},
    "m-seep-drip": {"name":"Goteo Ácido","description":"El escurrimiento lanza agua de mina, mineral, vieja y corrosiva, que sigue comiendo por 2 turnos.","flavor":"Mil años filtrando veneno de la roca."},
    "m-seep-solvent": {"name":"Solvente","description":"Un chorro disuelve el escudo del objetivo como si fuera sal.","flavor":"Nada aquí abajo queda protegido para siempre."},
    "m-deep-knock": {"name":"El Golpeteo","description":"Batepedra golpea el suelo una vez y el anillo a 2 casillas a su alrededor se rompe: daño y pies atrapados por 1 turno.","flavor":"Los mineros contaban los golpes. Quien llegaba a tres no volvía."},
    "m-rockfall": {"name":"Derrumbe","description":"Señala el techo y el techo obedece: piedra en área, y lo que sobra sale lanzado 2 casillas.","flavor":"La mina se derrumba con puntería."},
    "m-vein-call": {"name":"Llamar la Veta","description":"Batepedra arranca un puñado de la veta y el puñado echa a andar.","flavor":"El mineral también es gente, aquí abajo."},
    "m-quake-stance": {"name":"Postura de Temblor","description":"Se sienta sobre su propio peso y toda la mina tiembla con él: vuelve el temblor, 40 de escudo y 25% del daño devuelto.","flavor":"El clima es su arma. Sacarlo del temblor es la mitad de la pelea."},
    "m-cinder-lash": {"name":"Latigazo de Brasa","description":"El heraldo chasquea un látigo de brasa que atraviesa la sala partida.","flavor":"Un cuarto del Corazón aún arde."},
    "m-cinder-brand": {"name":"Sembrar Brasa","description":"El heraldo entierra una brasa viva en la casilla: quien la pise en los próximos 3 turnos despierta la trampa.","flavor":"El suelo de esta sala tiene memoria y rencor."},
    "m-cinder-trap": {"name":"Brasa Despierta","description":"La brasa enterrada estalla bajo el pie y escupe fuego en un círculo de 1 casilla. (Trampa: se dispara al ser pisada, no se conjura.)","flavor":"Encontraste el lugar donde plantó."},
    "m-tide-hymn": {"name":"Himno de la Marea","description":"La marea lava al aliado: curación profunda y se lleva veneno, raíces y marcas.","flavor":"El agua no perdona: solo deshace."},
    "m-tide-drag": {"name":"Resaca","description":"La resaca arrastra 2 casillas todo lo que esté en un radio de 2, de vuelta al centro de la sala partida.","flavor":"Nadie elige dónde lo deja la marea."},
    "m-stone-fist": {"name":"Puño de Cimiento","description":"Un puño de cimiento baja con el peso de todo lo que sostiene.","flavor":"Sostiene el techo. Te lo recuerda."},
    "m-stone-bulwark": {"name":"Baluarte","description":"El heraldo planta los pies y se vuelve pared: 35 de escudo y provocación por 2 turnos.","flavor":"La única puerta es él."},
    "m-gale-step": {"name":"Paso de Vendaval","description":"El heraldo atraviesa 5 casillas como corriente de aire y materializa el corte al llegar.","flavor":"Ya estaba allí cuando decidiste retroceder."},
    "m-gale-cut": {"name":"Corte de Corriente","description":"Una hoja de aire comprimido corta y devuelve al objetivo 2 casillas.","flavor":"La sala partida tiene muchos bordes."},
    "m-null-hush": {"name":"Silencio Celador","description":"El celador apaga la protección del objetivo con un gesto de quien cierra una ventana, y cobra el paso.","flavor":"No odia a nadie. Solo ordena."},
    "m-null-mend": {"name":"Remiendo Celador","description":"Limpia al aliado de todo lo que se pegó y deja un remiendo que cierra solo por 2 turnos.","flavor":"Cuidar es quitar lo que no pertenece."},
    "m-mirror-cut": {"name":"Corte Espejado","description":"El gemelo repite tu último golpe, con la mano cambiada.","flavor":"Lo aprendió viéndote."},
    "m-mirror-guard": {"name":"Guardia de Espejo","description":"20 de escudo y 30% del daño recibido vuelve al agresor por 2 turnos.","flavor":"Lastímalo rápido o lastímate despacio."},
    "m-sliver-shard": {"name":"Esquirla","description":"Una esquirla del gemelo se lanza sola.","flavor":"Todo espejo roto sigue mirando."},
    "m-turn-rain": {"name":"Girar a la Lluvia","description":"La mota inclina la sala hacia el agua: empieza a llover, y aprovecha para mojar a quien estaba seco.","flavor":"Cambia el clima por diversión. Nada más."},
    "m-turn-drought": {"name":"Girar a la Sequía","description":"La mota seca el aire de la sala en un parpadeo: sequía, y un lengüetazo de calor al objetivo.","flavor":"Quien eligió Agua acaba de empeorar su vida."},
    "m-turn-gale": {"name":"Girar al Vendaval","description":"La mota abre las grietas del Corazón y el vendaval entra rasgando.","flavor":"Tres climas, una criatura, ninguna vergüenza."},
    "m-heartroot-lash": {"name":"Latigazo de Raíz","description":"La raíz del corazón azota y entierra la punta en el pie del objetivo: atrapado por 1 turno.","flavor":"Aún intenta sujetar el Corazón entero."},
    "m-heartroot-grasp": {"name":"Agarrar","description":"La raíz se enrolla en el tobillo y recoge 2 casillas.","flavor":"Guarda todo lo que logra atraer."},
    "m-season-ember": {"name":"Estación de Brasa","description":"El cuarto de brasa del Corazón late: la sala entera se seca y un círculo de 1 casilla se incendia.","flavor":"Una de las cuatro estaciones que carga. Nunca la misma dos veces seguidas."},
    "m-season-tide": {"name":"Estación de Marea","description":"El cuarto de agua late: empieza a llover dentro de la sala y el área se inunda con fuerza de rompiente.","flavor":"Si elegiste Fuego, este es el turno de retroceder."},
    "m-season-gale": {"name":"Estación de Vendaval","description":"El cuarto de aire late: vendaval en la sala y una hoja recta que lanza 3 casillas.","flavor":"La grieta del Corazón es una boca que sopla."},
    "m-season-quake": {"name":"Estación de Temblor","description":"El cuarto de piedra late: la mina del mundo entero tiembla y el anillo a 2 casillas se rompe y atrapa.","flavor":"La Lousa baja un palmo más con cada golpe así."},
    "m-shard-storm": {"name":"Tormenta de Esquirlas","description":"Esquirlas del propio Corazón saltan de enemigo en enemigo, hasta 3 saltos, perdiendo fuerza en cada uno.","flavor":"Se despedaza un poco cada vez. No parece importarle."},
    "m-mend-rift": {"name":"Zurcir la Grieta","description":"El Corazón tira de sus propios bordes y se cose: curación profunda y 40 de escudo.","flavor":"Mil años agrietándose y aún lo intenta."},
    "m-splinter-call": {"name":"Llamar Esquirlas","description":"Una esquirla se desprende del Corazón y cae de pie, ya con rabia.","flavor":"Cada esquirla recuerda haber sido entera."},
    "m-sum-familiar-bite": {"name":"Mordida del Familiar","description":"El familiar muerde con la convicción de quien no tiene nombre que cuidar.","flavor":"El nombre es compromiso. Él solo tiene dientes."},
    "m-sum-hound-bite": {"name":"Mordida Caliente","description":"El perro de brasa muerde y deja la marca del hierro al rojo.","flavor":"Mueve la cola. La cola enciende el suelo."},
    "m-sum-colossus-smash": {"name":"Mazo de Magma","description":"El coloso baja el brazo fundido como quien cierra un portón.","flavor":"Nadie lo invitaba desde la Lousa."},
    "m-sum-colossus-eruption": {"name":"Erupción","description":"El suelo se abre en un círculo de 1 casilla y escupe magma que sigue quemando.","flavor":"Su calor es lo que cambia el clima de la sala."},
    "m-sum-nymph-mend": {"name":"Mano de Marea","description":"La ninfa toca la herida del aliado y el agua decide cerrarla.","flavor":"Nunca habla. Solo mira a quien sangra y lo resuelve."},
    "m-sum-nymph-veil": {"name":"Velo de Agua","description":"Una película de agua quieta envuelve al aliado: 13 de escudo por 2 turnos.","flavor":"El agua quieta aguanta más que el agua brava."},
    "m-sum-sentinel-slam": {"name":"Golpe de Centinela","description":"El centinela golpea una vez, con todo el peso, sin moverse.","flavor":"Se queda donde lo pusieron."},
    "m-sum-sentinel-guard": {"name":"Apostarse","description":"El centinela clava los pies y llama a todo el corredor hacia sí: 18 de escudo y provocación.","flavor":"El tapón de corredor del invocador."},
    "m-sum-golem-fist": {"name":"Puño de la Montaña","description":"Un puño del tamaño de una puerta baja con la paciencia de una ladera.","flavor":"Solo preguntó si la montaña quería dar unos pasos."},
    "m-sum-golem-quake": {"name":"Paso de Montaña","description":"Un solo paso, y la cruz alrededor se parte: daño en área y pies atrapados por 1 turno.","flavor":"La montaña no corre. La montaña llega."},
    "m-sum-drowned-drag": {"name":"Brazada Honda","description":"El brazo pesado alcanza lejos y trae al objetivo 2 casillas más cerca.","flavor":"No atrae para matar. Atrae para no quedarse solo."},
    "m-sum-drowned-weight": {"name":"Peso de Agua","description":"Descarga su propio cuerpo sobre quien está pegado: duele y lo sujeta al suelo por un turno.","flavor":"Ahogar es cuestión de paciencia."},
    "m-sum-eye-gale": {"name":"Ventolera Corta","description":"Abre los brazos y todo lo que esté alrededor retrocede 2 casillas, magullado.","flavor":"No expulsa por rabia. Expulsa por costumbre."},
    "m-sum-eye-calm": {"name":"Seso Quieto","description":"Dentro de la espiral el viento no golpea: quien esté cerca gana 34 de escudo por 2 turnos.","flavor":"En medio de la tormenta hay un lugar quieto."},
    "m-sum-falcon-strike": {"name":"Picotazo de Tormenta","description":"El pico golpea con el viento y devuelve al objetivo 2 casillas.","flavor":"No hay cielo para que vuele. Vuela igual, de rabia."},
    "m-sum-falcon-dive": {"name":"Zambullida","description":"El halcón cierra las alas, atraviesa hasta 5 casillas y abre las garras al final.","flavor":"Llega antes que todos, incluso que el plan."},
    "m-colosso-punho-lava": {"name":"Puño de Lava","description":"El coloso baja el puño de roca agrietada; la lava de las grietas salpica a quien lo recibe.","flavor":"Cada puñetazo suyo deja el suelo más caliente que antes."},
    "m-colosso-erupcao": {"name":"Erupción","description":"Las grietas del cuerpo se abren de golpe y escupen lava en toda casilla pegada a él.","flavor":"Estar cerca es la única forma de golpearlo. Él lo sabe."},
    "m-colosso-brasa-chao": {"name":"Suelo en Brasa","description":"La casilla por donde pasó el Coloso de Brasa aún arde: quema a quien la pise. (Rastro: nace de su paso, no se conjura.)","flavor":"No camina. Derrite el camino."},
    "m-colosso-onda": {"name":"Ola Rota","description":"Un brazo de coral y medusa se quiebra sobre el objetivo como ola en la piedra, y lo empuja 1 casilla.","flavor":"El mar enterrado aún recuerda las mareas."},
    "m-colosso-tromba": {"name":"Tromba de Agua","description":"El coloso escupe una columna de agua que barre 3 casillas en línea.","flavor":"Todo lo que se traga vuelve. Con fuerza."},
    "m-colosso-esmaga": {"name":"Aplastar","description":"Un puño del tamaño de un hombre cae sobre el objetivo.","flavor":"La piedra no tiene prisa. La piedra tiene peso."},
    "m-colosso-tremor": {"name":"Temblor de Coraza","description":"El coloso patea el suelo: el suelo se parte en cruz en el objetivo, hiriendo y atrapando por 1 turno.","flavor":"El suelo del Pozo obedece a quien pesa más."},
    "m-colosso-rajada": {"name":"Ráfaga Atrapada","description":"Una de las corrientes de viento se escapa del cuerpo y golpea al objetivo, que vuela 2 casillas.","flavor":"El viento atrapado quiere salir. Sale sobre alguien."},
    "m-colosso-ciclone": {"name":"Ciclón Corto","description":"Las corrientes giran: un anillo de viento a 2 casillas hiere y atrae 1 casilla hacia él.","flavor":"Quien huyó de él vuelve, de un modo u otro."},
    "m-vigia-olhar": {"name":"Mirada de Brasa","description":"El ojo único en la cera se enciende y traza una línea de brasa hasta el objetivo, de lejos y en la oscuridad, donde solo él ve.","flavor":"No lo ves. Él no necesita que lo veas."},
    "m-vigia-pavio": {"name":"Mecha Encendida","description":"Un hilo de cera hirviendo se pega al objetivo y sigue quemando por 2 turnos.","flavor":"La vela se apagó hace mil años. La cera, no."},
    "m-mariposa-roce": {"name":"Roce de Ceniza","description":"Las alas rozan al objetivo y dejan un trazo de ceniza caliente.","flavor":"No ataca la luz. Ataca a quien está en ella."},
    "m-mariposa-po": {"name":"Polvo de Ala","description":"Una nube de polvo de ala ciega y pesa: hiere y quita 14 de esquiva por 2 turnos.","flavor":"Quien estornuda no esquiva."},
    "m-caramujo-bater": {"name":"Golpe de Compuerta","description":"La concha de bronce se cierra sobre el objetivo como una compuerta y lo empuja 1 casilla.","flavor":"Del puente al agua hay un paso. Él lo da por ti."},
    "m-caramujo-fechar": {"name":"Cerrar la Compuerta","description":"El caracol se recoge tras la compuerta remachada: 40 de escudo por 2 turnos.","flavor":"Cerrada, sostuvo la galería entera por mil años."},
    "m-garca-arpao": {"name":"Pico-Arpón","description":"El cuello se estira de golpe y el pico barbado golpea al objetivo de lejos.","flavor":"Pesca quieta. Tú eres lo que se mueve."},
    "m-garca-fisga": {"name":"Garfiada","description":"El arpón se clava y vuelve: hiere y atrae al objetivo 2 casillas hacia ella, hacia el agua.","flavor":"Lo que ella engancha, la corriente lo termina."},
    "m-pilarete-soco": {"name":"Puñetazo de Tambor","description":"Un brazo de tambores de piedra apilados baja entero sobre el objetivo.","flavor":"La columna no tiene prisa. La columna tiene peso."},
    "m-pilarete-tambor": {"name":"Redoble de Tambor","description":"El Pilarete suelta un tambor de su propio brazo y lo rueda en línea recta: golpea a quien esté delante, hasta 4 casillas. Un pilar en pie en el camino lo detiene.","flavor":"No va hasta ti. Manda un pedazo."},
    "m-pilarete-assentar": {"name":"Asentar","description":"El Pilarete se asienta en el suelo como un pilar que baja: hiere y atrapa por 1 turno a quien está pegado a él.","flavor":"El salón entero hace eso. Él aprendió mirando."},
    "m-toupeira-garra": {"name":"Garra de Pala","description":"Las garras de cavar abren lo que tengan delante.","flavor":"Ella cavó el santuario. Tú eres más blando que la piedra."},
    "m-toupeira-tunel": {"name":"Salir del Suelo","description":"El topo desaparece en el piso, atraviesa hasta 5 casillas en línea y sale a los pies del objetivo con las garras abiertas.","flavor":"Un pilar en pie la obliga a rodear. Un pilar bajo es puerta."},
    "m-catavento-sopro": {"name":"Soplo de Hélice","description":"El yelmo de paletas gira y el soplo golpea de lejos: hiere y empuja 1 casilla.","flavor":"En la terraza su viento llega una casilla más lejos. El tuyo de Aire también."},
    "m-catavento-leque": {"name":"Ráfaga en Abanico","description":"Las manos de pala se abren y la ráfaga sale en abanico: hiere y empuja 2 casillas a quien esté en ella.","flavor":"La pared detrás de ti es parte del golpe."},
    "m-arraia-rasante": {"name":"Rasante","description":"El ala ancha pasa rasante y corta.","flavor":"No se posa. Pasa."},
    "m-arraia-planar": {"name":"Planear en la Ráfaga","description":"La raya se acuesta en el viento, planea hasta 4 casillas y llega golpeando.","flavor":"La terraza lleva a quien sabe acostarse en ella."},
    "m-eco-pulso": {"name":"Pulso del Núcleo","description":"El núcleo en el pecho del Eco late una vez y el latido atraviesa la cámara hasta quien él eligió.","flavor":"El primer sonido del mundo enterrado. Aún resuena."},
    "m-eco-brasa": {"name":"Lava Primera","description":"Una de las grietas de lava del Eco se abre y escupe un círculo de 1 casilla en brasa.","flavor":"La lava del Cierre vino de aquí."},
    "m-eco-centelha": {"name":"Chispa Antigua","description":"Una chispa vieja como el fondo salta del pecho del Eco directo a un héroe.","flavor":"Aún caliente, después de todo."},
    "m-eco-mare": {"name":"Marea Primera","description":"El coral del Eco se parte y una línea de 4 casillas de agua oscura corre por el suelo.","flavor":"La Cisterna es solo lo que quedó de esta marea."},
    "m-eco-gota": {"name":"Gota de Coral","description":"Una esquirla de coral llena de agua estalla en el héroe que el Eco eligió.","flavor":"Afilado como la sal."},
    "m-eco-rocha": {"name":"Roca Primera","description":"Un puño de roca del Eco cae sobre una cruz de 1 casilla.","flavor":"El cimiento del mundo tiene dueño."},
    "m-eco-lasca": {"name":"Astilla de Cristal","description":"Un cristal del hombro del Eco se suelta y vuela recto hacia un héroe.","flavor":"Cada astilla suya es una mina entera."},
    "m-eco-vento": {"name":"Corriente Suelta","description":"Una de las cadenas que atan el viento al Eco se suelta y salta de héroe en héroe, 2 saltos.","flavor":"El viento atrapado quiere salir. Sale por ti."},
    "m-eco-corte": {"name":"Corte de Corriente","description":"Una hoja de viento corta al héroe y lo empuja una casilla lejos del Eco.","flavor":"No quiere a nadie cerca del núcleo."},
    "m-eco-menor-brasa": {"name":"Chispa Menor","description":"El Eco Menor de brasa lanza un pedazo de su propia lava.","flavor":"Repite al mayor, más bajo."},
    "m-eco-menor-mare": {"name":"Salpicadura Menor","description":"El Eco Menor de coral escupe agua salada al héroe más cercano.","flavor":"Una salpicadura de la marea de antes."},
    "m-eco-menor-rocha": {"name":"Golpe Menor","description":"El Eco Menor de roca golpea con todo el cuerpo a quien esté pegado.","flavor":"Poco, pero pesado."},
    "m-eco-menor-vento": {"name":"Ráfaga Menor","description":"El Eco Menor de viento sopla fuerte: corta y empuja una casilla.","flavor":"Un hilo del viento que el mayor retiene."}
  },
  "itemSpells": {
    "is-seed-bomb": {"name":"Bomba de Semillas","description":"Lanza un puñado de semillas de vaina reventona: se abren en el aire y brotan dentro de quien esté en el círculo.","flavor":"El invernadero sigue sembrando. Tú solo eliges dónde."},
    "is-thorn-ward": {"name":"Redoma de Espinas","description":"Escudo de emergencia: un seto de espinas se cierra alrededor del cuerpo y devuelve parte de lo que lo golpee.","flavor":"Crece demasiado rápido para ser educada."},
    "is-undertow": {"name":"Resaca","description":"Abre en el suelo una corriente corta que arrastra al objetivo tres casillas hacia ti.","flavor":"La cisterna nunca devolvió nada gratis, pero devuelve."},
    "is-tide-mend": {"name":"Marea Mansa","description":"Una ola baja pasa por el aliado, cierra lo que estaba abierto y se lleva veneno y raíces.","flavor":"El agua quieta hace mil años aún sabe subir cuando se lo piden."},
    "is-cinder-leap": {"name":"Salto de Brasa","description":"El cuerpo se vuelve chispa, atraviesa el aire y se rearma en la casilla elegida; el estallido de la llegada quema los alrededores.","flavor":"Llegar es fácil. Lo difícil es avisar."},
    "is-forge-brand": {"name":"Hierro de Marcar","description":"Graba en el enemigo la marca de la fragua: todo lo que lo golpee después duele más.","flavor":"El Cierre marca a su ganado. Ahora tú también."},
    "is-updraft": {"name":"Soplido","description":"Una columna de aire sube bajo el enemigo y lo lanza tres casillas atrás; en un andamio, eso suele zanjar la discusión.","flavor":"El viento de los Andamios no empuja: publica opinión."},
    "is-storm-chain": {"name":"Corriente de Tormenta","description":"Corriente elemental: el rayo salta de enemigo en enemigo hasta tres veces, perdiendo fuerza en cada salto.","flavor":"Cuenta los cuerpos sola. Siempre cuenta bien."},
    "is-quake-nail": {"name":"Clavo de Temblor","description":"Un clavo de mineral se clava en el suelo bajo el objetivo: queda dos turnos exactamente donde está.","flavor":"La mina clava todo lo que se mueve demasiado."},
    "is-ore-bulwark": {"name":"Puntal de Mineral","description":"Del suelo sube un puntal de mineral bruto frente al aliado: escudo grueso y nadie escapa de cerca de él.","flavor":"Apuntalaron el techo con eso por mil años. El techo sigue ahí."},
    "is-heart-call": {"name":"Llamado del Corazón","description":"La esquirla toca una nota que el Corazón Partido reconoce: todo lo hostil en un radio de tres casillas es arrastrado hacia ti.","flavor":"Llamar a todos a la vez es una decisión. Suerte."},
    "is-heart-whole": {"name":"Corazón Entero","description":"Con las cuatro piezas cerradas, el Corazón Partido vuelve a latir entero por un instante: el veneno sale, la herida cierra, la cáscara engrosa, el golpe vuelve por el mismo camino, y la sala entera se aquieta.","flavor":"Mil años partido. Un instante entero. Hazlo valer."},
    "is-heart-eclipse": {"name":"Eclipse","description":"La lente apaga el clima de la sala por un instante y lo que queda cae sobre el enemigo sin escudo y sin elemento en que apoyarse.","flavor":"Por un segundo, nadie tiene ventaja alguna. Usa el segundo."},
    "is-swarm-sting": {"name":"Picadura en Enjambre","description":"Abre la compuerta del panal y suelta tres avispas a la vez: saltan de enemigo en enemigo perdiendo fuerza en cada salto y dejan la picadura trabajando dos turnos.","flavor":"Vuelven solas. Cuentan bien a quien faltó."},
    "is-silt-grip": {"name":"Agarrón de Lodo","description":"El lodo del desagüe sube en pinza y se cierra alrededor de los pies de todos en el círculo: duele al apretar y no deja salir a nadie de donde estaba.","flavor":"El desagüe es propiedad privada. Te avisaron."},
    "is-quench-hiss": {"name":"Chirrido de Temple","description":"Vierte sobre el objetivo el agua del foso de temple: la nube de vapor quema por dentro y apaga cualquier capa mágica que haya encendido.","flavor":"Así se templó todo aquí. Hasta las personas."},
    "is-noose-drag": {"name":"Lazo de Polea","description":"Lanza un lazo de cuerda de obra y recoge: arrastra al objetivo tres casillas hacia ti y deja el nudo apretado en el tobillo un turno.","flavor":"Lo que llega a la plataforma no vuelve."},
    "is-firedamp-blast": {"name":"Estallido de Grisú","description":"Abre la malla de la lamparilla a propósito y deja que el gas de la galería encuentre la llama: toda la bolsa estalla dos casillas más allá y el soplo aleja a quien estaba cerca.","flavor":"La malla existe para que esto no pase. La abriste."},
    "is-gale-cut": {"name":"Corte del Heraldo","description":"El viento atrapado en el faro sale en una sola hoja y atraviesa toda la fila en línea recta, empujando dos pasos a cada cuerpo que cortó.","flavor":"Llega, corta y ya está en otro lugar. Copia."},
    "is-bone-toll": {"name":"Tañido de Huesos","description":"El candil da una nota grave que la Corte Ahogada reconoce: quien está a dos casillas recibe golpes y pasa dos turnos sin poder mirar a otra persona.","flavor":"Aún responden al pasar lista. Siempre responden."},
    "is-long-wick": {"name":"Mecha Larga","description":"Clava en el objetivo una mecha de mina encendida: la quemadura inicial es pequeña, pero la mecha sigue bajando por dentro de él durante tres turnos.","flavor":"Mecha larga es para quien tiene tiempo de irse caminando."},
    "is-cinder-wake": {"name":"Rastro de Brasa","description":"El incensario gira una vuelta entera y suelta un anillo de brasa a dos casillas del cuerpo: alcanza a quien se acercaba, y no a quien ya llegó.","flavor":"Quema el círculo de afuera. El de adentro es problema tuyo."},
    "is-cinco-selos": {"name":"Los Cinco Sellos","description":"Estampa en el suelo los cinco sellos de una vez: la marca quema a quienes estaban en el círculo y sigue quemando dos turnos — ningún elemento la apaga, porque es de todos.","flavor":"El Coleccionista no vende. Devuelve."}
  },
  "petSpells": {
    "pet-ember-breath": {"name":"Aliento de Brasa","description":"El dragoncito infla el pecho, cierra los ojos con fuerza y suelta un chorro corto de brasa que sigue quemando después.","flavor":"Cree que hizo mucho ruido. Y sí lo hizo."},
    "pet-vine-chomp": {"name":"Bocado","description":"La planta carnívora cierra la boca en el tobillo del enemigo y no suelta: quien fue mordido no se mueve de su lugar este turno.","flavor":"Mastica despacio. Lo está disfrutando."},
    "pet-gale-buffet": {"name":"Latigazo de Ala","description":"El águila se lanza en picada, bate las alas una vez a un palmo de la cara del enemigo y lo empuja dos casillas hacia atrás.","flavor":"Su viento tiene opinión sobre dónde deberías estar."},
    "pet-dew-mend": {"name":"Rociada","description":"La criaturita de agua se aprieta como una esponja y rocía agua limpia sobre el aliado más herido.","flavor":"Después queda más chiquita. Se llena sola otra vez."},
    "pet-dew-rinse": {"name":"Enjuague","description":"Se derrama entera sobre el aliado y se lleva el veneno y las raíces que lo sujetaban.","flavor":"No preguntes adónde va lo que ella lava."},
    "pet-guide-hum": {"name":"Zumbido-Guía","description":"La Pedrinha-Guia zumba en una nota que solo el aliado oye: sus golpes salen más certeros y más temprano.","flavor":"Siempre apunta al peligro. Ese es su defecto."},
    "pet-shard-ward": {"name":"Esquirla-Escudo","description":"El Caco Vivo se hace añicos a propósito y las esquirlas orbitan al aliado como una cúpula corta.","flavor":"Se rearma el turno siguiente. Quejándose."},
    "pet-shard-echo": {"name":"Eco Partido","description":"Suelta un eco del Corazón Partido que golpea al enemigo y deja una grieta luminosa por donde todo duele más.","flavor":"El sonido es el de una sala mucho más grande que esta."},
    "pet-selo-clarao": {"name":"Destello del Sello","description":"El bichito alza el sello que carga y lo vuelve contra el enemigo: el destello blanco empuja un paso y cobra el resto.","flavor":"No muerde. Ejecuta la deuda."}
  },
  "fusionSpells": {
    "fus-trap-arrow": {"name":"Clavo de Carcaj","description":"La trampa de caza se dispara de abajo hacia arriba y clava al suelo el pie de quien la pisó.","flavor":"Obra de un cuerpo que era dos."},
    "fus-trap-hex": {"name":"Sello Rúnico","description":"El sello dibujado en el suelo se enciende al ser pisado y sigue royendo después.","flavor":"Obra de un cuerpo que era dos."},
    "fus-trap-bloom": {"name":"Cercado Vivo","description":"Zarcillos cierran el cercado alrededor del tobillo del intruso.","flavor":"Obra de un cuerpo que era dos."},
    "fus-trap-venom": {"name":"Espina de Brea","description":"Una espina invisible dejada en la sombra: entra fácil y tarda en salir.","flavor":"Obra de un cuerpo que era dos."},
    "fus-turret-shot": {"name":"Plomo del Tótem","description":"El tótem dispara los dos cañones solo contra quien entre en su alcance.","flavor":"Obra de un cuerpo que era dos."},
    "fus-effigy-hex": {"name":"Plaga de la Efigie","description":"La efigie apunta su dedo de cera y marca al objetivo para la fusión.","flavor":"Obra de un cuerpo que era dos."},
    "fus-warden-mend": {"name":"Riego del Guardaflor","description":"El guardaflor derrama savia tibia sobre el aliado más herido.","flavor":"Obra de un cuerpo que era dos."},
    "fus-shade-cut": {"name":"Corte del Gemelo","description":"El gemelo de brea corta de lado y desaparece antes de la respuesta.","flavor":"Obra de un cuerpo que era dos."},
    "fus-idol-slam": {"name":"Puntal del Ídolo","description":"El ídolo-puntal derrumba su brazo de piedra y abre espacio.","flavor":"Obra de un cuerpo que era dos."}
  },
  "monsters": {
    "thorn-lasher": {"name":"Vergajo","description":"Un látigo vegetal enraizado en una maceta rota, cubierto de púas y flores muertas. No se mueve de su lugar: no lo necesita.","flavor":"Torreta con pétalos."},
    "pollen-puff": {"name":"Sapo de Polen","description":"Una bola de polen amarillo con patitas de ramita y una sonrisa cosida. Camina hacia ti balanceándose. Eso debería ser una advertencia.","flavor":"Mátalo de lejos. Por favor, mátalo de lejos."},
    "burr-mother": {"name":"Abrojo-Madre","description":"Un ovillo de púas del tamaño de un perro, con decenas de ojitos negros entre las espinas. Al morir se deshace en dos ovillos menores e igual de rencorosos.","flavor":"Un cuerpo, tres problemas de posicionamiento."},
    "lantern-wasp": {"name":"Avispa-Brillo","description":"Una avispa del tamaño de un gato cuyo abdomen es una linterna de vidrio con una luz atrapada dentro. Rápida, brillante, venenosa: llega primero y se va antes de la respuesta.","flavor":"La luz que carga alguna vez fue de alguien."},
    "sap-shaman": {"name":"Saviero","description":"Un tocón de árbol jorobado con un rostro tallado a navaja y un caldero de savia burbujeante en el regazo. Riega a los aliados como quien cuida un jardín, y el jardín muerde.","flavor":"Bajo la lluvia canta. Mátalo antes del estribillo."},
    "dew-strider": {"name":"Araña de Rocío","description":"Una araña de patas finísimas que camina sobre el agua acumulada en las hojas sin hundirse un milímetro. Teje con rocío: las telas brillan, pesan y se endurecen.","flavor":"Pesa menos que la gota que pisa."},
    "sprout-feral": {"name":"Brotecito Voraz","description":"Un retoño recién germinado que es solo hojas, prisa y dientes. La Jardinera los planta; ellos hacen el resto.","flavor":"Crece rápido porque no piensa durar."},
    "burrlet": {"name":"Abrojito","description":"La mitad del rencor, el doble de velocidad. Se pega y no suelta.","flavor":"Encontrarás uno en el bolsillo semanas después."},
    "boss-gardener": {"name":"La Jardinera Viuda","description":"La guardiana del Invernadero: una silueta de tres metros hecha de celosía, guantes de cuero y velo de viuda, con una tijera de poda oxidada en lugar de manos. Todavía cuida el jardín. Tú eres la maleza.","flavor":"GIMMICK — LA PODA: la liana te atrae hacia el quiosco, la tijera recorta, la siembra repone la maleza. La Corona de Espinas castiga el anillo a 2 casillas: el lugar más seguro del mundo es pegado a ella."},
    "drowned-porter": {"name":"Ahogadizo","description":"Un cargador de la cisterna que nunca soltó su farol. Piel gris verdosa, hinchada de agua, algas en lugar de cabello. Muerde para beber el calor que perdió.","flavor":"Pelear con él es alimentarlo."},
    "moray-piper": {"name":"Morena Flauta","description":"Una anguila de dos metros cuyo cráneo perforado silba cuando respira. Se alza del agua como un signo de interrogación, escupe chorros en línea recta y pesca presas con la lengua-arpón.","flavor":"Toca una sola nota, y es sobre ti."},
    "lantern-jelly": {"name":"Medusa-Brillo","description":"Una medusa del tamaño de una araña de luces, flotando a un palmo del suelo, con tentáculos como flecos de cristal. Su luz cura a los ahogados: apágala primero.","flavor":"Convierte ahogadizos en esponjas."},
    "brine-golem": {"name":"Salmuerón","description":"Un coloso de sal cristalizada en capas, con un corazón de agua oscura visible en el pecho. Lento como marea baja, imparable como marea alta. Cuanto más se rompe, más afilado queda.","flavor":"Ignorarlo es un cronómetro."},
    "fat-drop": {"name":"Gotón","description":"Una gota de agua del tamaño de un barril, con un rostro soñoliento flotando dentro. Revéntala y se vuelve dos gotas menores y mucho más despiertas.","flavor":"Cada gota nueva tapa un hueco más."},
    "droplet": {"name":"Gotita","description":"Pequeña, redonda, indignada.","flavor":"Tiene opiniones firmes sobre tu tobillo."},
    "sump-crab": {"name":"Cangrejo de Sumidero","description":"Un cangrejo del tamaño de una mesa, con caparazón de piedra incrustado de sal y una pinza desproporcionada que arrastra por el suelo. Vive en el desagüe por donde se vacía la cisterna, y lo considera propiedad privada.","flavor":"Imposible de empujar. Ya eligió su lugar."},
    "mist-warbler": {"name":"Murmullo de Niebla","description":"Un pájaro sin plumas, hecho del vapor que sube del agua quieta, con un pico largo por donde silba la cisterna. Canta para los ahogados y sopla a los vivos hacia los canales.","flavor":"Su eco llega antes que ella."},
    "boss-baroness": {"name":"Baronesa Salmoura","description":"La dueña de la cisterna: un vestido de baile del siglo pasado relleno de agua oscura y viva, con un collar de perlas flotando donde debería haber cuello. Recibe visitas atrayéndolas y tragándose la sala entera.","flavor":"GIMMICK — EL BAILE: Marea Hambrienta atrae la sala entera hacia ella; el turno siguiente, el Trago Amargo devora a quien quedó cerca. Dispersarse, ser atraído, salir antes del trago."},
    "ember-imp": {"name":"Tizón","description":"Un carbón en brasa con brazos finos y una sonrisa rajada de luz anaranjada. Corre hacia ti riendo. La risa es la mecha.","flavor":"Dónde muere importa más que cuándo."},
    "walking-anvil": {"name":"Yunque Andante","description":"Un yunque centenario que echó patas achaparradas y un rencor proporcional a los martillazos que recibió. Imposible de empujar; pésima idea dejarlo acercarse.","flavor":"Lenta como culpa antigua."},
    "ash-wraith": {"name":"Ceniciento","description":"El contorno de un herrero antiguo dibujado en hollín suspendido, con dos puntos de brasa en lugar de ojos. Lanza flechas de ceniza y se deshace en el aire cuando lo amenazan.","flavor":"Desaparece en el vendaval y vuelve en tu nuca."},
    "slag-mound": {"name":"Montón de Escoria","description":"Un montón de desecho de fragua que aprendió a arrastrarse, dejando un rastro vitrificado. Rómpelo y se desmorona en dos escoritas incandescentes, que explotan.","flavor":"Lo peor para matar en un espacio estrecho."},
    "faceless-smith": {"name":"Herrero sin Rostro","description":"Un delantal de cuero y dos brazos musculosos colgados de la nada: donde debería haber un cuerpo, solo calor temblando. Templa a los aliados como hojas y los cubre de planchas ardientes.","flavor":"El apoyo que convierte a un lacayo en problema."},
    "quench-hound": {"name":"Perro de Temple","description":"Un perro de vapor condensado que nació en el foso donde se sumergían las hojas aún rojas. El pelo gotea, la mordida chirría, y donde pasa la brasa se apaga, incluso la de los dueños de casa.","flavor":"La única agua del Cierre, y muerde."},
    "chain-hauler": {"name":"Tira-Cadenas","description":"Una grúa de fragua que desarrolló voluntad: un carrete de hierro colgado del riel del techo, con tres cadenas que lanza como anzuelos. No persigue a nadie: trae a todos hasta él.","flavor":"Anclado al riel: empujar no resuelve."},
    "spark-whelp": {"name":"Chispa","description":"Una chispa con patas y opinión. Vive poco, acaba en grande.","flavor":"Magno las fabrica sin mirar."},
    "slag-bit": {"name":"Escorita","description":"Un trozo de escoria aún rojo, arrastrándose con propósito.","flavor":"Acto dos de tres."},
    "boss-heartforge": {"name":"Magno, el Encendedor","description":"El corazón del último Cierre en forma de titán: un horno de leña de cuatro metros con parrilla en el pecho, martillo-chimenea al hombro y la primera llama del mundo ardiendo dentro. No guarda el portón. Es el portón.","flavor":"GIMMICK — LA PIEZA MARCADA: te marca con la brasa (hasta 5 acumulaciones), te sopla lejos con la fragua y cobra todo de una vez en el Veredicto del Yunque. Limpia la marca o muere por el total."},
    "plank-shrike": {"name":"Alcaudón de Tabla","description":"Un pájaro ceniciento de pico curvo que empala lo que caza en los clavos expuestos de las tablas. Vive en los vanos, baja en caída libre y desaparece antes de que gires la cabeza.","flavor":"Su despensa es el pasamanos."},
    "gust-gremlin": {"name":"Gremlin de Ráfaga","description":"Un bichito de orejas enormes que usa sus propias orejas como velas. No golpea para matar: golpea para ver caer a la persona. Tiene un sentido del humor documentadamente malo.","flavor":"Cuenta las caídas. En voz alta."},
    "rope-hanger": {"name":"Ahorca-Soga","description":"Un ovillo de cuerdas de obra atado en un nudo que nadie logra deshacer, colgado de la polea maestra. Nunca baja. Lanza lazos y recoge lo que atrapó como quien jala material.","flavor":"Atado a la polea: empujón no mueve nudo."},
    "kite-serpent": {"name":"Sierpe-Pipa","description":"Una serpiente chata y larga hecha de papel encerado y listones, con una cola de cintas revestida de vidrio molido. Sube en las corrientes de aire y baja trazando rayas.","flavor":"Una cometa que aprendió a tirar de su propio hilo."},
    "ballast-golem": {"name":"Gólem de Lastre","description":"Una armazón de vigas llena de sacos de grava, hecha para sostener el andamio en su lugar cuando el pozo sopla. Aguantó mil años. Ahora camina, despacio y siempre contra el viento.","flavor":"El vendaval le quita 5 PV por turno. No tengas prisa con él."},
    "whistle-choir": {"name":"Coro-Silbido","description":"Un haz de tubos de respiradero atado con alambre, flotando de lado. Cada tubo silba una nota; juntos remiendan a los compañeros y les limpian todo lo que se pega.","flavor":"Apaga la música antes de discutir con la banda."},
    "mote-swarm": {"name":"Enjambre de Motas","description":"Una nube compacta de bichitos de polvo luminoso que se mueve como un solo cuerpo. Golpea lo bastante fuerte y deja de ser un cuerpo: se vuelve dos.","flavor":"No matas una nube. La divides."},
    "mote-bit": {"name":"Motita","description":"Mitad de una nube, con el doble de prisa. Cuando se deshace, el polvo arde un instante.","flavor":"El polvo también explota. Pregúntale a cualquier minero."},
    "nail-sprite": {"name":"Clavín","description":"Un clavo de quince centímetros con dos ojitos y mucha convicción. Cambota los clava en la armazón y salen caminando.","flavor":"Nace torcido, entra recto."},
    "boss-windwright": {"name":"Cambota, el Maestro de Obras","description":"El capataz que jamás entregó la obra: un esqueleto de vigas y jarcia con una polea en lugar de cabeza y una plomada eterna colgando del brazo. Construye el andamio mientras pelea encima de él, y derriba el ala entera si así resuelve más rápido.","flavor":"GIMMICK — LA OBRA CONTINÚA: los remaches te marcan (hasta 5 acumulaciones), el Viento de Proa devuelve el vendaval cuando el clima se enfría, y Derrumbar el Ala manda a quien esté marcado 3 casillas hacia el vacío. No necesita matarte: necesita empujarte."},
    "pick-revenant": {"name":"Espanto de Pico","description":"El turno de noche nunca subió. Quedó el gesto: un minero de polvo compactado que aún golpea la misma pared, al mismo ritmo, desde hace mil años. Te golpea con la misma técnica, buscando dónde se agrieta.","flavor":"Marca primero. Cobra después."},
    "firedamp-wisp": {"name":"Hachón de Grisú","description":"Una llama azul y silenciosa flotando a la altura del pecho, del tamaño de una cabeza. Es el gas de la mina que cobró voluntad. No persigue: espera a que entres en la galería equivocada.","flavor":"Mátalo de lejos. Luego acuérdate de eso otra vez."},
    "cave-jaw": {"name":"Bocarra","description":"Un tramo de galería convertido en bicho: diez metros de túnel con dientes de estalactita y un gusto adquirido por la carne con casco. Se queda quieta hasta que crees que es camino.","flavor":"El tanque de la mina. Y también la puerta."},
    "crystal-chanter": {"name":"Cantor de Cristal","description":"Un racimo de cuarzo del tamaño de un hombre, crecido dentro de un casco abandonado. Vibra en una nota baja y constante que cose la piedra de los compañeros de vuelta.","flavor":"Golpearlo es golpearte a ti mismo, con retraso."},
    "sinkhole-worm": {"name":"Gusano de Derrumbe","description":"Una boca circular de anillos que vive bajo el piso suelto y solo muestra el embudo. No camina: reorganiza el suelo hasta que llegues por gravedad.","flavor":"Anclado en la roca madre: nada lo empuja."},
    "ore-tumbler": {"name":"Rodillo de Mineral","description":"Una bola de mineral bruto del tamaño de una vagoneta, lisa de tanto rodar por los rieles. Toma impulso en línea recta y no tiene ningún plan para después.","flavor":"Rómpelo y se vuelve dos pendientes."},
    "ore-chip": {"name":"Astilla de Veta","description":"Un trozo de mineral con una veta de metal brillando en el medio, rodando con propósito.","flavor":"Pequeño, denso y sin freno."},
    "shaft-bat": {"name":"Murciélago de Pozo","description":"Alas de cuero fino estiradas sobre huesos demasiado largos, con un chillido que hace que el polvo dibuje la forma del túnel. Vive en el pozo vertical y baja en espiral.","flavor":"El único aquí al que el temblor perjudica. Aún no lo entendió."},
    "damp-seeper": {"name":"Escurrimiento","description":"Un charco vertical que escurre por la pared contra la gravedad, cargado de mineral disuelto. Disuelve escudos como disolvió la roca que atravesó.","flavor":"El agua de mina no sacia la sed de nadie."},
    "boss-deepknock": {"name":"Batepedra, el que Golpea Abajo","description":"Lo que los mineros oían golpear al otro lado de la pared y fingían que era eco. Es más grande que la galería en que está: un torso de roca madre con dos puños de estéril y ningún rostro donde buscar intención. Golpea. El mundo responde.","flavor":"GIMMICK — LOS TRES GOLPES: El Golpeteo castiga el anillo a 2 casillas (pegado a él es seguro), el Derrumbe castiga a quien se aleja, y la Postura de Temblor devuelve el clima que lo cura. O lo sacas del temblor, o aprendes a pelear encima de él."},
    "cinder-herald": {"name":"Heraldo de Brasa","description":"Uno de los cuatro pedazos del Corazón que ganaron cuerpo. Este es una armadura vacía con una rendija encendida en el pecho, que siembra brasas en el suelo como quien prepara la casa para las visitas.","flavor":"No persigue. Prepara el terreno."},
    "tide-herald": {"name":"Heraldo de Marea","description":"La misma armadura, llena de agua oscura en movimiento. Cura a sus hermanos y reorganiza el campo con resacas cortas y certeras.","flavor":"Mientras ella viva, los otros tres no mueren bien."},
    "stone-herald": {"name":"Heraldo de Cimiento","description":"La armadura rellena de cimiento: piedra, cal y una terquedad de mil años. Se queda entre tú y el resto de la sala y lo considera un trabajo honesto.","flavor":"Provoca, aguanta y no se mueve de su lugar."},
    "gale-herald": {"name":"Heraldo de Vendaval","description":"La armadura vacía de verdad: solo el viento dentro la mantiene en pie, y el viento tiene prisa. Llega, corta y ya está en otro lugar.","flavor":"Difícil de trabar, peor de acertar."},
    "null-warden": {"name":"Celador Nulo","description":"El funcionario que quedó: una silueta grisácea de delantal, sin ningún elemento, que apaga protecciones ajenas y remienda las de sus hermanos. Ningún clima lo ayuda; ningún clima lo estorba.","flavor":"La respuesta del Corazón a quien se escondió tras escudos."},
    "mirror-twin": {"name":"Gemelo-Espejo","description":"Un trozo de espejo del tamaño de una persona que camina de lado y muestra, con un turno de retraso, tu propia silueta golpeándote. Romperlo solo crea más superficies reflectantes.","flavor":"Golpear fuerte es la peor idea disponible."},
    "mirror-sliver": {"name":"Esquirla-Espejo","description":"Un trozo menor, más afilado, con la mitad de tu rostro aún atrapada en la superficie.","flavor":"Al hacerse añicos, corta a quien está cerca."},
    "weather-mote": {"name":"Mota del Tiempo","description":"Una bolita de aire comprimido del tamaño de un puño, girando despacio, con un pedacito de cielo viejo atrapado dentro. Es lo que quedó del clima del mundo antiguo, y juega con eso.","flavor":"GIMMICK: cambia solo el clima de la sala. Tu elección elemental se vuelve sorteo."},
    "heartroot": {"name":"Raíz del Corazón","description":"Una raíz gruesa que salió de la pared y cruzó el salón para abrazar el Corazón y mantenerlo pegado. Fracasó. Sigue intentándolo, y agarra cualquier cosa que pase cerca.","flavor":"Enraizada de verdad: no empujes, corta."},
    "boss-riftheart": {"name":"El Corazón Partido","description":"El último Corazón del mundo enterrado, rajado en cuatro cuartos que aún laten desacompasados: uno de brasa, uno de agua, uno de piedra, uno de aire. Cada latido lanza la sala entera a un clima distinto. No guarda el Cierre: es lo que quedó del cielo, y está muriendo a gritos.","flavor":"GIMMICK — LAS CUATRO ESTACIONES: cada turno golpea un cuarto distinto y CAMBIA EL CLIMA junto con el golpe. El elemento que te curaba pasa a matarte de 5 en 5 PV. Vencer es jugar con el clima del enemigo, y zurcir su grieta antes de que él la zurza."},
    "sporeling": {"name":"Espolín","description":"Un hongo bebé con ojos demasiado grandes y lealtad aún mayor. Muerde, envenena y, al caer, estalla en una nube de esporas vengativa.","flavor":"Cuerpo, daño retardado y negación de casilla en un solo paquete."},
    "sum-familiar": {"name":"Familiar","description":"Un bicho pequeño y sin nombre que el invocador llama desde el primer día: cuatro patas, dientes torcidos y una lealtad que nadie pidió. Un cuerpo más para morder, aguantar y negar el paso.","flavor":"Nunca dice el nombre de la bestia. Dice que el nombre es compromiso."},
    "sum-ember-hound": {"name":"Perro de Brasa","description":"Un perro de carbón encendido, flaco y veloz, con una costura de fuego corriendo del hocico a la cola. Muerde caliente y, cuando cae, devuelve la última brasa a quien esté cerca.","flavor":"Mueve la cola. La cola enciende el suelo."},
    "sum-magma-colossus": {"name":"Coloso de Magma","description":"Cuatro metros de roca derretida atrapada en una forma que recuerda vagamente un cuerpo. Camina despacio porque cada paso abre una fisura, y el calor que emana seca la sala entera.","flavor":"El Corazón del Cierre de Brasa tiene un hermano mayor. (Invocación de nivel 30.)"},
    "sum-tide-nymph": {"name":"Ninfa de la Marea","description":"Una silueta de agua limpia, del tamaño de un niño, que flota a un palmo del suelo y va directo hacia quien está sangrando. Nunca ataca; no fue llamada para eso.","flavor":"Nunca habla. Solo mira a quien sangra y lo resuelve."},
    "sum-stone-sentinel": {"name":"Centinela de Piedra","description":"Un bloque de roca vertical con dos surcos por ojos, plantado donde el invocador mande. Lento, duro y terco: existe para que un corredor deje de ser corredor.","flavor":"Se queda donde lo pusieron. Es lo más confiable del mundo enterrado."},
    "sum-mountain-golem": {"name":"Gólem de la Montaña","description":"Una ladera entera que aceptó levantarse y dar unos pasos. Tiene árboles muertos en la espalda y una vena de agua corriendo por el hombro. Nada en el mundo enterrado es más duro que él.","flavor":"No invocó la montaña. Solo le preguntó si se animaba. (Invocación de nivel 30.)"},
    "sum-drowned-cistern": {"name":"Ahogado de la Cisterna","description":"Un cuerpo alto y empapado, de hombros caídos, hecho de agua oscura que no escurre. Donde debería haber rostro hay un vacío, y dentro del tronco se adivinan otros: manos, hombros, medio rostro presionados contra la superficie desde dentro. Nadie logró contar cuántos son.","flavor":"La cisterna devuelve lo que tragó. Nunca de a uno."},
    "sum-storm-eye": {"name":"Ojo de la Tormenta","description":"Una figura de pie, con los brazos abiertos, envuelta en una espiral de viento que sube del suelo y se ensancha sobre la cabeza. El rostro es sereno y mira hacia abajo. Los pies quedan donde los pusieron: no camina, y todo lo que se acerca vuelve.","flavor":"En medio de la tempestad hay un lugar quieto. Ahí vive él."},
    "sum-storm-falcon": {"name":"Halcón de la Tormenta","description":"Un halcón de plumas grises con un relámpago viejo atrapado entre ellas. Vuela en círculos cerrados sobre la batalla y baja cuando decide, no cuando le ordenan.","flavor":"No hay cielo para que vuele. Vuela igual, de rabia."},
    "colosso_fogo": {"name":"Coloso de Brasa","description":"Una montaña de roca volcánica que camina erguida, agrietada de arriba abajo; por las grietas corre lava viva. Cada paso deja la casilla en brasa tras él, y quien pisa ahí se quema.","flavor":"Los pisos del Pozo guardan el calor por donde él pasó."},
    "colosso_agua": {"name":"Coloso de la Marea","description":"Un cuerpo de coral y medusa, mayor que dos hombres, que gotea sin secarse nunca. Donde se detiene nace un charco, y quieto dentro de él se rehace.","flavor":"Sácalo del agua y es solo piedra mojada."},
    "colosso_terra": {"name":"Coloso de Roca","description":"Un gigante de piedra vestido con una coraza de losas. Mientras la coraza aguanta, ningún golpe entra entero; el viento la arranca más rápido que cualquier hoja.","flavor":"Primero la coraza. Después, el resto."},
    "colosso_ar": {"name":"Coloso de la Ventolera","description":"Una silueta alta envuelta en cadenas de hierro, y en cada cadena un viento atrapado que aúlla. Camina más que los otros colosos, y quien lo golpea de cerca sale soplado lejos.","flavor":"Acercarse a él cuesta el doble: ir y volver."},
    "el_fogo_1": {"name":"Vigía de Mecha","description":"Una silueta alta y flaca de túnica harapienta. La cabeza es un cabo de vela derretida con un solo ojo en la cera, y el pabilo está apagado hace mil años. Ve en la oscuridad de la Cámara Apagada y dispara de lejos a quien no lo ve.","flavor":"GIMMICK: te ve en la oscuridad; tú solo lo ves a 2 casillas, o a la luz de un brasero."},
    "el_fogo_2": {"name":"Mariposa de Ceniza","description":"Una mariposa del tamaño de un niño, de cuerpo peludo color ceniza y alas en lugar de brazos. Gira alrededor de los braseros y se lanza sobre quien la luz delata. Rápida, frágil y difícil de sujetar.","flavor":"En la oscuridad ve tanto como tú: 2 casillas."},
    "el_agua_1": {"name":"Caracol-Compuerta","description":"Un caracol de pie, pesado, con la concha hecha de una compuerta de bronce remachada. Se planta en el puente y golpea a quien intenta pasar al agua. El agua no lo retrasa.","flavor":"El puente está seco. Con él encima, es suyo."},
    "el_agua_2": {"name":"Garza de Galería","description":"Una garza pescadora de pie como persona, de patas largas y pico de arpón. Camina en el agua baja como en suelo seco y arponea de lejos a quien el agua dejó lento, o lo atrae hacia ella.","flavor":"La casilla inundada cuesta 2 PP para ti y 1 para la dueña de la casilla."},
    "el_terra_1": {"name":"Pilarete","description":"Un trozo de pilar vivo que se levantó y se fue caminando: tronco de columna acanalada, cabeza de capitel con un rostro antiguo, brazos de tambores apilados. Pesado y plantado: nada lo empuja.","flavor":"Es el salón en miniatura: sube, baja y no se mueve del lugar."},
    "el_terra_2": {"name":"Topo Centinela","description":"Un topo rechoncho de casco de piedra, con garras de pala más grandes que la cabeza. Se hunde en el piso y sale del suelo a los pies de quien creía estar lejos.","flavor":"Embiste en línea recta: el pilar que sube en el camino es tu escudo."},
    "el_ar_1": {"name":"Veleta","description":"Un autómata alto y delgado de láminas de bronce remachadas, con un yelmo de paletas en lugar de cabeza y manos de pala. Sopla de lejos y empuja como empuja la ráfaga de la terraza.","flavor":"En la Terraza de la Ventolera su soplo alcanza una casilla más. Tu hechizo de Aire también."},
    "el_ar_2": {"name":"Raya de Ráfaga","description":"Una raya de pie: el cuerpo plano en rombo, las alas anchas en lugar de brazos, la cola caída a la espalda como capa. Planea en el viento de la terraza y llega antes del aviso.","flavor":"La ráfaga la empuja como te empuja a ti. Solo que a ella le gusta más."}
  },
  "ecoMonstros": {
    "eco_primordial": {"name":"El Eco Primordial","description":"La primera voz del mundo enterrado. Un coloso armado con pedazos de las seis mazmorras —cristal, coral, roca, lava y viento atrapado en cadenas— y un núcleo que late en el pecho. No camina: el mundo gira a su alrededor.","flavor":"Cada 25% de vida perdida, un elemento nuevo; cada golpe grande, avisado en el suelo una ronda antes."},
    "eco_menor_fogo": {"name":"Eco Menor de Brasa","description":"Un trozo de lava que se soltó del Eco y echó patas. Se queda lejos y dispara lo suyo.","flavor":"Llamado en el cambio de fase del Eco Primordial."},
    "eco_menor_agua": {"name":"Eco Menor de Coral","description":"Una rama de coral del Eco, llena de agua que no escurre. Salpica a quien se acerca.","flavor":"Llamado en el cambio de fase del Eco Primordial."},
    "eco_menor_terra": {"name":"Eco Menor de Roca","description":"Un bloque del hombro del Eco que cayó y se levantó. Lento, pesado, y no se quita del medio.","flavor":"Llamado en el cambio de fase del Eco Primordial."},
    "eco_menor_ar": {"name":"Eco Menor de Viento","description":"Un hilo del viento atrapado en las cadenas del Eco, suelto por un instante. Rápido y difícil de apresar.","flavor":"Llamado en el cambio de fase del Eco Primordial."}
  },
  "fusionSummons": {
    "fus-arrow-turret": {"name":"Tótem-Espoleta","description":"Un tótem de caza con un ojo despierto y dos cañones que salen de la boca: gira despacio, apunta siempre y no camina."},
    "fus-hex-effigy": {"name":"Efigie Rúnica","description":"Muñeco de cera y tiza con runas escritas al revés. Señala con el dedo y el objetivo siente el dedo."},
    "fus-bloom-warden": {"name":"Guardaflor","description":"Un capullo de flor del tamaño de un perro, con pétalos en forma de mano ahuecada. Riega a quien sangra."},
    "fus-shade-twin": {"name":"Gemelo de Brea","description":"La sombra de la fusión despegada del suelo, con media hoja y ningún rostro. Camina medio paso por delante del original."},
    "fus-bulwark-idol": {"name":"Ídolo-Puntal","description":"Medio pilar tallado con el rostro de las dos clases fusionadas. Se queda en el camino: ese es todo su trabajo."},
    "fus-wall-watcher": {"name":"Muro-Vigía","description":"Un trozo de muralla en pie, con una grieta vertical de donde dos ojos observan. Cerrado es pared; abierto, es dueño del paso."}
  },
  "dungeons": {
    "greenhouse": {"name":"El Invernadero Soterrado","description":"El invernadero real del mundo antiguo, sellado con el jardín aún vivo adentro. Siglos en la oscuridad enseñaron a las plantas a cazar; luciérnagas presas en cúpulas hacen de sol. El agua que la Gran Lousa atrapó allá arriba gotea por las grietas del vidrio toda la noche, y al jardín le encanta."},
    "greenhouse/rooms/0": {"name":"El Vestíbulo de las Hiedras"},
    "greenhouse/rooms/1": {"name":"Los Arriates Hundidos"},
    "greenhouse/rooms/2": {"name":"El Quiosco de la Viuda"},
    "cistern": {"name":"La Cisterna de los Ahogados","description":"El reservorio que calmó la sed del mundo antiguo, y después se bebió a sus dueños. La Corte Ahogada aún da bailes en el agua quieta: perlas en el lodo, faroles sumergidos todavía encendidos, candelabros de medusas. Todo refleja, y el reflejo a veces se mueve primero."},
    "cistern/rooms/0": {"name":"La Galería de las Goteras"},
    "cistern/rooms/1": {"name":"El Salón de las Columnas de Sal"},
    "cistern/rooms/2": {"name":"El Trono de la Salmuera"},
    "emberlock": {"name":"El Cierre de Brasa","description":"El último Cierre, forjado alrededor de la primera llama del mundo. Corredores de yunques fríos, cadenas colgadas del techo, luz que viene de abajo, de las rejillas del piso. El calor sube y se queda: aquí la sequía no es clima, es arquitectura. El mayor portón jamás construido despertó celoso de su propio fuego."},
    "emberlock/rooms/0": {"name":"El Corredor de Brasas"},
    "emberlock/rooms/1": {"name":"La Nave de los Mazos"},
    "emberlock/rooms/2": {"name":"La Cámara del Corazón"},
    "windscaffold": {"name":"Los Andamios del Viento","description":"El pozo de mantenimiento que los constructores nunca terminaron: quince pisos de andamio atado con cuerda, colgados sobre un vacío que nadie midió. Los respiraderos del mundo enterrado desembocan todos aquí, y el viento sube por el pozo toda la noche haciendo cantar las tablas. Caer no es derrota táctica. Es que el suelo de la sala no exista."},
    "windscaffold/rooms/0": {"name":"La Pasarela de las Grúas"},
    "windscaffold/rooms/1": {"name":"El Pozo de Servicio"},
    "windscaffold/rooms/2": {"name":"El Puente del Maestro de Obras"},
    "quakemine": {"name":"La Mina Trémula","description":"La mina que cavaba hacia arriba, intentando perforar la Gran Lousa por debajo. Se detuvo cuando el turno de la noche no subió. Desde entonces la roca golpea sola, de tanto en tanto, y el polvo baja en cortinas: es la Lousa acomodándose un palmo más. Los mineros siguen trabajando. Nadie tuvo valor de decirles que el turno terminó."},
    "quakemine/rooms/0": {"name":"La Galería del Turno de Noche"},
    "quakemine/rooms/1": {"name":"El Respiradero"},
    "quakemine/rooms/2": {"name":"La Faz de Batepedra"},
    "brokenheart": {"name":"El Corazón Partido","description":"El Corazón que sostenía el mundo entero, y no solo un Cierre. Se partió en cuatro cuartos que laten fuera de compás —uno de brasa, uno de agua, uno de piedra, uno de aire— y cada latido lanza la sala a un clima distinto. Aquí no existe elemento seguro: lo que te curaba hace tres rondas te está matando ahora. Es el fin del Descenso, y la Lousa está escuchando."},
    "brokenheart/rooms/0": {"name":"El Atrio de las Cuatro Estaciones"},
    "brokenheart/rooms/1": {"name":"La Sala de los Espejos"},
    "brokenheart/rooms/2": {"name":"El Corazón Partido"}
  },
  "especiais": {
    "elementsanctum": {"name":"El Santuario de los Elementos","description":"Antes de que el mundo fuera enterrado, los cuatro elementos se enseñaban aquí, cada uno en su sala: la cámara donde solo la brasa ve, la galería que la marea llena y vacía, el salón de los pilares que caminan y la terraza donde el viento no para. El santuario sigue dando la misma clase, ahora a quien desciende, y sin preguntar si la persona quiere aprender."},
    "elementsanctum/rooms/0": {"name":"La Cámara Apagada"},
    "elementsanctum/rooms/1": {"name":"La Galería Anegada"},
    "elementsanctum/rooms/2": {"name":"El Salón de los Pilares Vivos"},
    "elementsanctum/rooms/3": {"name":"La Terraza de la Ventolera"},
    "elementsanctum/rooms/4": {"name":"El Altar de los Cuatro"}
  },
  "arenas": {
    "praca": {"name":"La Plaza"},
    "praca/rooms/0": {"name":"La Plaza del Árbol-Mundo"},
    "sede": {"name":"El Salón de la Sede"},
    "sede/rooms/0": {"name":"La Arena del Trono"},
    "camara_eco": {"name":"La Cámara del Eco"},
    "camara_eco/rooms/0": {"name":"La Cámara del Eco"}
  },
  "tileEvents": {
    "ev-might": {"name":"Aliento de Bravura","description":"Una chispa de coraje antiguo atrapada en el piso: +25 de poder por 2 turnos.","flavor":"Alguien murió valiente justo aquí. Quedó un poco."},
    "ev-haste": {"name":"Corriente de Paso","description":"Un soplo de los respiraderos empuja por la espalda: +1 PP por 2 turnos.","flavor":"El mundo enterrado aún respira, a veces a tu favor."},
    "ev-focus": {"name":"Segundo de Claridad","description":"El tiempo abre una rendija: +1 PA en este turno.","flavor":"Raro, corto y caro. Úsalo ya."},
    "ev-guard": {"name":"Restos de Redoma","description":"Un fragmento de protección antigua se cierra alrededor de quien pisa: 25 de escudo.","flavor":"Protegió a alguien por mil años. Ahora te toca a ti."},
    "ev-slip": {"name":"Piso Resbaladizo","description":"Musgo, sal o aserrín: te escurres de cualquier traba. +15 de esquiva por 2 turnos.","flavor":"Resbalar en el momento justo es toda una escuela."},
    "ev-mystery": {"name":"Sorpresa","description":"Nadie sabe qué guardó el mundo enterrado en esta casilla. Pisa y descubre: puede ser regalo, puede ser cuenta vieja.","flavor":"La casa siempre cobra. A veces paga."},
    "ev-mystery/outcomes/0": {"text":"Un respiro del mundo antiguo te llena el pecho. ¡Curación profunda!"},
    "ev-mystery/outcomes/1": {"text":"La casilla cede y algo debajo muerde. Mucho."},
    "ev-mystery/outcomes/2": {"text":"El tiempo abre una rendija: una acción más en este turno."},
    "ev-mystery/outcomes/3": {"text":"Una bolsa de aire podrido estalla en la cara. Esto va a arder un rato."},
    "ev-mystery/outcomes/4": {"text":"Un recuerdo de fuerza ajena sube por las piernas: ¡+40 de poder!"},
    "ev-mystery/outcomes/5": {"text":"Raíces viejas se cierran en los tobillos y no piden permiso."},
    "ev-mystery/outcomes/6": {"text":"Una cúpula olvidada despierta entera: escudo y regeneración."},
    "ev-portal": {"name":"Boca de Respiradero","description":"Una boca de respiradero succiona a quien pisa y lo escupe en otro punto del mapa.","flavor":"Los Alientos lo usaban como escalera. Tú lo usarás para huir."},
    "ev-drain": {"name":"Sanguijuela del Piso","description":"El piso tiene hambre: muerde el tobillo y sigue bebiendo por 2 turnos.","flavor":"Mil años sin visitas dejan así a cualquier suelo."},
    "ev-fountain": {"name":"Fuente Terca","description":"Un manantial que nunca supo que el mundo se acabó. Se bebe de rodillas.","flavor":"Todavía está limpio. No preguntes por qué."}
  },
  "fusionIdentities": {
    "arqueiro+bruxo": {"name":"Artillería Arcana","line":"Magia de larguísimo alcance: marca todo el campo desde lejos y detona las marcas en área."},
    "arqueiro+curandeiro": {"name":"Arco Votivo","line":"Flechas que atraviesan la fila en línea recta y devuelven al cuerpo fusionado cada gota que quitan."},
    "arqueiro+espadachim": {"name":"Cazador de Sombras","line":"Dispara desde la negrura, salta sobre el objetivo marcado y ejecuta: invisibilidad + reposicionamiento + marcas."},
    "arqueiro+invocador": {"name":"Torreta Viva","line":"Planta tótems tiradores y clavos-trampa; los disparos saltan entre los atrapados."},
    "arqueiro+sumo": {"name":"Balista de Carne","line":"Asedio: proyectiles pesados que empujan, garfios que atraen y un ancla que nadie mueve del lugar."},
    "bruxo+curandeiro": {"name":"Plaga Piadosa","line":"Transfusión: todo lo que quita al enemigo se vuelve vida propia; bendición de un lado, podredumbre del otro."},
    "bruxo+espadachim": {"name":"Hoja Rúnica","line":"Parpadea por el campo dejando explosiones en las salidas y llegadas, con veneno arcano en la hoja."},
    "bruxo+invocador": {"name":"Aquelarre de Trampas","line":"Ritual: sellos encendidos bajo los pies del enemigo, círculos dejados de emboscada, efigies que maldicen y el clima volteado a la fuerza."},
    "bruxo+sumo": {"name":"Coloso Arcano","line":"La magia no se lanza, se irradia: todo alrededor del cuerpo recibe golpes, queda trabado y devuelve el golpe."},
    "curandeiro+espadachim": {"name":"Bisturí Danzante","line":"Cortes rápidos con robo de vida, curación de emergencia entre un paso y otro, y desaparece en medio del turno."},
    "curandeiro+invocador": {"name":"Jardín Sagrado","line":"Planta la semilla DENTRO del enemigo y el jardín cobra después: espinar alrededor, cercado de emboscada y guardianes que curan lo que quedó."},
    "curandeiro+sumo": {"name":"Baluarte Compasivo","line":"Muralla que se cura golpeando: arrastra al enemigo a su alcance, bebe lo que arranca y reparte el excedente con quien sangra."},
    "espadachim+invocador": {"name":"Sombra Multiplicada","line":"La propia sombra corta primero; luego vienen las espinas ocultas y los gemelos de brea: veneno de tres lugares a la vez."},
    "espadachim+sumo": {"name":"Embestida Titánica","line":"Peso en movimiento: embiste de lejos, agarra, gira y arroja, y el suelo queda marcado."},
    "invocador+sumo": {"name":"Fortaleza Viva","line":"Tanque que invoca: el clamor lastima y provoca a toda la sala, los ídolos-puntal caen golpeando y el resto del grupo va cubierto de escudo."},
    "arqueiro+minotauro": {"name":"La Aspillera","line":"Dispara y sigue cubierto. El muro no es obstáculo para quien lo levantó: es la ventana por donde apunta."},
    "bruxo+minotauro": {"name":"El Cráter","line":"La explosión deja borde. Lo que sobra del área se vuelve pared."},
    "curandeiro+minotauro": {"name":"El Refugio","line":"El muro cura a quien se arrima. Guardar y cuidar se vuelven lo mismo, y esta es la dupla más defensiva del juego."},
    "espadachim+minotauro": {"name":"La Emboscada","line":"Desaparece y deja un muro donde estaba. El enemigo golpea la piedra buscando lo que ya no está."},
    "invocador+minotauro": {"name":"El Muro Vivo","line":"La piedra tiene a alguien adentro. Bloquea Y ataca."},
    "minotauro+sumo": {"name":"El Portón","line":"Los dos en el mismo lugar, y nadie sale. La dupla que decide dónde ocurre la lucha."}
  },
  "fusionBlends": {
    "agua+agua": {"affix":"Abisal","description":"Dos aguas sumadas se vuelven profundidad: toda la sala queda pesada, oscura y mojada. Elemento puro, daño puro."},
    "agua+ar": {"affix":"de Sal","description":"El vendaval chupa el agua hacia sí: cada golpe llega empapado de sal y empuja a quien lo recibe un paso más atrás."},
    "agua+fogo": {"affix":"Escaldante","description":"Rivales fusionados no se anulan: se vuelven vapor a presión. Quema al instante y sigue quemando después."},
    "agua+neutro": {"affix":"de Cieno","description":"La mitad del cuerpo aún no eligió elemento: el agua lleva el golpe sin color, y el lodo que sobra deshace escudos."},
    "agua+terra": {"affix":"Palustre","description":"Agua y tierra dan lodo: pesa en los pies de quien lo recibe y pega al enemigo al suelo por un instante."},
    "ar+ar": {"affix":"de Ciclón","description":"Dos aires sumados no soplan: giran. El vendaval pasa a ser la regla de la sala."},
    "ar+fogo": {"affix":"de Incendio","description":"Fuego con viento debajo se vuelve soplo de fragua: la llamarada alarga el alcance y el estallido lanza al objetivo lejos."},
    "ar+neutro": {"affix":"Veloz","description":"Sin elemento definido del otro lado, sobra prisa: el golpe es leve, pero llega antes y desordena la formación."},
    "ar+terra": {"affix":"de Arena","description":"Rivales fusionados se vuelven tormenta de arena: el grano entra en la herida y hace doler todo lo que venga después."},
    "fogo+fogo": {"affix":"Infernal","description":"Dos llamas sumadas no se dividen: se vuelven una sola, mayor, y secan el aire de toda la sala."},
    "fogo+neutro": {"affix":"Candente","description":"Una mitad arde, la otra todavía es pura fuerza bruta: el golpe sale sin color, pero sale caliente y sin ahorro."},
    "fogo+terra": {"affix":"de Volcán","description":"Piedra derretida: golpea como roca y sigue cocinando bajo la armadura."},
    "neutro+neutro": {"affix":"Feral","description":"Ninguno de los dos eligió elemento todavía: la fusión sale cruda, solo las dos clases, sin color, y el clima se aquieta alrededor."},
    "neutro+terra": {"affix":"Brutal","description":"Mitad piedra, mitad nada: lo que falta de elemento sobra de peso. Quien lo recibe se queda donde está."},
    "terra+terra": {"affix":"de Tierra","description":"Dos tierras sumadas se vuelven falla geológica: el suelo trabaja junto con la fusión y no deja de temblar."},
    "ar+agua": {"affix":"de Sal","description":"El vendaval chupa el agua hacia sí: cada golpe llega empapado de sal y empuja a quien lo recibe un paso más atrás."},
    "fogo+agua": {"affix":"Escaldante","description":"Rivales fusionados no se anulan: se vuelven vapor a presión. Quema al instante y sigue quemando después."},
    "neutro+agua": {"affix":"de Cieno","description":"La mitad del cuerpo aún no eligió elemento: el agua lleva el golpe sin color, y el lodo que sobra deshace escudos."},
    "terra+agua": {"affix":"Palustre","description":"Agua y tierra dan lodo: pesa en los pies de quien lo recibe y pega al enemigo al suelo por un instante."},
    "fogo+ar": {"affix":"de Incendio","description":"Fuego con viento debajo se vuelve soplo de fragua: la llamarada alarga el alcance y el estallido lanza al objetivo lejos."},
    "neutro+ar": {"affix":"Veloz","description":"Sin elemento definido del otro lado, sobra prisa: el golpe es leve, pero llega antes y desordena la formación."},
    "terra+ar": {"affix":"de Arena","description":"Rivales fusionados se vuelven tormenta de arena: el grano entra en la herida y hace doler todo lo que venga después."},
    "neutro+fogo": {"affix":"Candente","description":"Una mitad arde, la otra todavía es pura fuerza bruta: el golpe sale sin color, pero sale caliente y sin ahorro."},
    "terra+fogo": {"affix":"de Volcán","description":"Piedra derretida: golpea como roca y sigue cocinando bajo la armadura."},
    "terra+neutro": {"affix":"Brutal","description":"Mitad piedra, mitad nada: lo que falta de elemento sobra de peso. Quien lo recibe se queda donde está."}
  },
  "fusionForms": {
    "arqueiro+bruxo/0": {"formName":"Disparo","description":"El arco encantado dispara del otro lado de la sala y deja en el objetivo una señal que la magia sabrá encontrar después."},
    "arqueiro+bruxo/1": {"formName":"Sigilo","description":"La flecha estalla en el aire y pinta un sigilo en todos los que estaban demasiado cerca."},
    "arqueiro+bruxo/2": {"formName":"Virote","description":"Un virote encantado atraviesa toda la fila y deja la misma señal en cada uno que perforó."},
    "arqueiro+bruxo/3": {"formName":"Esquirla","description":"Una esquirla de vidrio encantado salta de enemigo en enemigo, perdiendo fuerza y ganando odio."},
    "arqueiro+bruxo/4": {"formName":"Estampido","description":"El aire se raja en abanico desde el objetivo y parte de las señales dejadas antes estalla junto."},
    "arqueiro+bruxo/5": {"formName":"Juicio","description":"La fusión cierra los dos ojos a la vez: cada señal dejada antes cobra la cuenta de una vez."},
    "arqueiro+bruxo/6": {"formName":"Cataclismo","description":"Todo el horizonte de la sala se vuelve objetivo: cae, detona todo lo que estaba marcado y ya marca de nuevo lo que sobró."},
    "arqueiro+curandeiro/0": {"formName":"Dardo","description":"Un dardo votivo en línea recta: lo que quita al enemigo vuelve caliente al cuerpo fusionado."},
    "arqueiro+curandeiro/1": {"formName":"Bálsamo","description":"La fusión lanza un frasco sellado con la punta del arco: el bálsamo se abre en el aliado y sigue trabajando."},
    "arqueiro+curandeiro/2": {"formName":"Rosario","description":"Una cuenta del rosario por enemigo en la fila: lo que cada una cobra vuelve goteando al cuerpo fusionado."},
    "arqueiro+curandeiro/3": {"formName":"Hilo","description":"Un hilo de luz tendido de punta a punta de la fila enemiga: cada cuerpo atravesado devuelve un trago de vida."},
    "arqueiro+curandeiro/4": {"formName":"Cirio","description":"Enciende un cirio en el suelo: la corona de luz quema a quien está en el borde y el calor vuelve como curación."},
    "arqueiro+curandeiro/5": {"formName":"Cáliz","description":"Se alza el cáliz en medio del grupo: cierra heridas, endurece la piel y lava lo que se pudría por dentro."},
    "arqueiro+curandeiro/6": {"formName":"Sacramento","description":"Una sola flecha, sacramentada, atraviesa toda la sala en línea: todo lo que perfora se vuelve vida del otro lado."},
    "arqueiro+espadachim/0": {"formName":"Lance","description":"La fusión cierra la distancia de un solo salto y llega junto antes de que el enemigo gire la cabeza."},
    "arqueiro+espadachim/1": {"formName":"Velo","description":"Las dos siluetas se pliegan una dentro de otra y desaparecen: nadie apunta a lo que no puede contar."},
    "arqueiro+espadachim/2": {"formName":"Retroceso","description":"Acierta y ya no está ahí: el cuerpo fusionado se desliza hacia atrás antes de que llegue la respuesta."},
    "arqueiro+espadachim/3": {"formName":"Tajo","description":"Corte a la altura de la guardia: abre al objetivo y deja la abertura abierta para el próximo disparo."},
    "arqueiro+espadachim/4": {"formName":"Rastro","description":"Olfatea el rastro del objetivo, marca dónde va a pisar y gana aliento para llegar antes."},
    "arqueiro+espadachim/5": {"formName":"Desgarro","description":"La hoja se lanza y vuelve rasgando de objetivo en objetivo, cobrando toda abertura que haya dejado antes."},
    "arqueiro+espadachim/6": {"formName":"Epílogo","description":"La cacería acaba en un párrafo: aparece pegado al objetivo, cobra todo lo que estaba marcado y desaparece de nuevo en el mismo movimiento."},
    "arqueiro+invocador/0": {"formName":"Pincho","description":"Una flecha gruesa como estaca clava al enemigo al suelo por el pie: sigue atacando, pero no sale de ahí."},
    "arqueiro+invocador/1": {"formName":"Nido","description":"La fusión clava el tótem en el suelo y sopla: el ojo se abre y los dos cañones buscan objetivo."},
    "arqueiro+invocador/2": {"formName":"Piquete","description":"Cuatro hileras de estacas suben en cruz del suelo y cierran las salidas de quien estaba en el medio."},
    "arqueiro+invocador/3": {"formName":"Clavo","description":"Un clavo de caza enterrado con la punta hacia arriba, esperando el paso en falso, y el martillazo que lo entierra ya esparce astillas en la vecindad."},
    "arqueiro+invocador/4": {"formName":"Foso","description":"Cava un foso erizado y silba: quien oye viene a mirar de cerca, y ve por dentro."},
    "arqueiro+invocador/5": {"formName":"Enjambre","description":"No es una flecha, es un enjambre: cae sobre el grupo y salta a quien intente alejarse."},
    "arqueiro+invocador/6": {"formName":"Arsenal","description":"La fusión vuelca un arsenal entero en una sola casilla: sube el tótem, se hunde un clavo en el suelo y el estallido de la entrega ya castiga la vecindad."},
    "arqueiro+sumo/0": {"formName":"Lanzamiento","description":"La fusión lanza lo que tenga en la mano con peso de sumo: el objetivo retrocede dos pasos junto con su idea."},
    "arqueiro+sumo/1": {"formName":"Garfio","description":"Flecha con cuerda: engancha al tirador escondido allá atrás y lo trae al alcance del cuerpo a cuerpo."},
    "arqueiro+sumo/2": {"formName":"Petardo","description":"Un petardo gordo sube en arco y baja donde nadie quería: el estallido aleja a todos un paso."},
    "arqueiro+sumo/3": {"formName":"Ariete","description":"Un tronco de asedio disparado en línea: barre la fila, empuja a todos juntos y deja los pies trabados donde pararon."},
    "arqueiro+sumo/4": {"formName":"Contrapeso","description":"La fusión echa el peso del cuerpo hacia adelante y planta los pies: quien está cerca recibe golpes y nadie más escapa."},
    "arqueiro+sumo/5": {"formName":"Bastión","description":"La fusión clava los pies, abre los brazos y se vuelve construcción: quien quiera pasar tendrá que dispararle primero."},
    "arqueiro+sumo/6": {"formName":"Trabuco","description":"El cuerpo entero se vuelve máquina de asedio y vuelca un bloque en el otro extremo de la sala: lo que no muere sale volando y cae atrapado."},
    "bruxo+curandeiro/0": {"formName":"Drenaje","description":"La mano abierta saca un hilo tibio de dentro del enemigo y se lo clava en el propio pecho."},
    "bruxo+curandeiro/1": {"formName":"Voto","description":"Una promesa dicha en dos voces: cierra el corte y deja al aliado difícil de herir por el mismo elemento."},
    "bruxo+curandeiro/2": {"formName":"Cilicio","description":"Aprieta el cilicio a distancia: lo que el objetivo pierde de sangre la fusión lo gana, y la herida sigue trabajando."},
    "bruxo+curandeiro/3": {"formName":"Estigma","description":"Un estigma abierto en la piel de todos alrededor del objetivo: come escudo primero, carne después, sin prisa."},
    "bruxo+curandeiro/4": {"formName":"Legado","description":"Cobra a todos los de alrededor de una vez y reparte lo que arrancó como si fuera herencia."},
    "bruxo+curandeiro/5": {"formName":"Ofertorio","description":"La fusión pasa la canasta: cada enemigo de la rueda aporta un poco de vida, y toda va al mismo lugar."},
    "bruxo+curandeiro/6": {"formName":"Anatema","description":"La excomunión en dos lenguas a la vez: arranca el escudo, envenena dos veces y engorda la fusión con lo que quitó."},
    "bruxo+espadachim/0": {"formName":"Corte","description":"La hoja tiene runas grabadas hasta el mango: el corte cierra, lo que escribió por dentro no."},
    "bruxo+espadachim/1": {"formName":"Salto","description":"Desaparece de un punto y reaparece en otro; el aire que cierra en el lugar de llegada quema a quien estaba cerca."},
    "bruxo+espadachim/2": {"formName":"Trazo","description":"Un trazo de runa cortando toda la fila, y la tinta que queda en la herida no deja de arder."},
    "bruxo+espadachim/3": {"formName":"Estilete","description":"Un estilete demasiado fino para verse, mojado en un hechizo sin antídoto conocido."},
    "bruxo+espadachim/4": {"formName":"Surco","description":"La hoja abre un surco en abanico en el suelo y el veneno corre por él hasta encontrar un pie descalzo."},
    "bruxo+espadachim/5": {"formName":"Manto","description":"El manto rúnico se cierra sobre las dos siluetas: desaparece del mapa y vuelve golpeando mucho más fuerte."},
    "bruxo+espadachim/6": {"formName":"Pesadilla","description":"Aparece en medio del grupo enemigo como cosa de pesadilla, desarma la rueda con veneno y desaparece antes de que despierten."},
    "bruxo+invocador/0": {"formName":"Sello","description":"El sello no se dibuja en el suelo: se dibuja BAJO el enemigo, y se enciende al instante. Quien firma ya no sale de donde firmó."},
    "bruxo+invocador/1": {"formName":"Círculo","description":"Un círculo de tiza y ceniza dejado cerrado en el suelo, esperando un pie descuidado para abrirse."},
    "bruxo+invocador/2": {"formName":"Explanada","description":"Traza una explanada cerrada en el suelo: quien está en la línea no sale hasta que acabe el ritual."},
    "bruxo+invocador/3": {"formName":"Coro","description":"La fusión modela una efigie de cera con sus dos caras; la primera nota del coro sale del muñeco y raja el aire alrededor."},
    "bruxo+invocador/4": {"formName":"Entierro","description":"Entierra la segunda trampa junto a la primera y escupe en la fosa: el suelo alrededor ya empieza a pudrirse."},
    "bruxo+invocador/5": {"formName":"Presagio","description":"El ritual calma el clima de la sala a la fuerza —nadie más tiene ventaja de clima— y la fusión se queda con toda la atención del aire."},
    "bruxo+invocador/6": {"formName":"Aquelarre","description":"El aquelarre completo en una casilla: efigie de pie, sello encendido debajo y una plaga abierta en rueda para inaugurar la fiesta."},
    "bruxo+sumo/0": {"formName":"Porrazo","description":"El brazo baja con peso de sumo y chasquea hechizo al contacto: el porrazo abre espacio a la fuerza."},
    "bruxo+sumo/1": {"formName":"Halo","description":"Un halo de energía se abre alrededor del cuerpo y pega al suelo los pies de quien estaba demasiado pegado."},
    "bruxo+sumo/2": {"formName":"Estruendo","description":"Cuatro ondas de choque salen del cuerpo en cruz y barren la sala hasta la pared, empujando lo que encuentran."},
    "bruxo+sumo/3": {"formName":"Espejo","description":"La piel se vuelve espejo encantado: parte de lo que la golpea vuelve por el mismo camino, con intereses."},
    "bruxo+sumo/4": {"formName":"Bramido","description":"Un bramido en abanico que arranca la coraza mágica de todos los que alcanzó de frente."},
    "bruxo+sumo/5": {"formName":"Cerco","description":"El coloso inspira y la sala viene con él: todos son atraídos hacia él, sin escudo y ya recibiendo golpes."},
    "bruxo+sumo/6": {"formName":"Coloso","description":"La fusión deja de conjurar y simplemente OCURRE: tres casillas de radio de puro impacto arcano, sin escudo y sin salida."},
    "curandeiro+espadachim/0": {"formName":"Verdugón","description":"Un tajo superficial y exacto, como abre quien también sabe coser. Barato: se puede repetir."},
    "curandeiro+espadachim/1": {"formName":"Pulso","description":"Dos dedos en la muñeca del aliado: descubre qué anda mal y lo arranca en el mismo movimiento."},
    "curandeiro+espadachim/2": {"formName":"Jirón","description":"Corta, cose su propio corte y ya va un paso adelante de la sangre que cayó."},
    "curandeiro+espadachim/3": {"formName":"Bisturí","description":"Corte quirúrgico entre dos costillas: quita vida, entrega veneno y devuelve salud a quien cortó."},
    "curandeiro+espadachim/4": {"formName":"Compás","description":"Cierra el compás sobre el objetivo y abre dos veces: los dos elementos cobran en la misma vuelta."},
    "curandeiro+espadachim/5": {"formName":"Aliento","description":"La fusión respira hondo una sola vez y gana un turno entero de ventaja, y desaparece mientras lo hace."},
    "curandeiro+espadachim/6": {"formName":"Carrusel","description":"Entra girando en medio del grupo, abre a todos en rueda, bebe lo que abrió y sale por el otro lado sin ser vista."},
    "curandeiro+invocador/0": {"formName":"Brote","description":"La semilla no se planta en el suelo: se planta en el enemigo. Brota por dentro y sigue creciendo después del golpe."},
    "curandeiro+invocador/1": {"formName":"Rocío","description":"Cae un rocío tibio sobre el grupo: cura poco de una vez y mucho con el tiempo."},
    "curandeiro+invocador/2": {"formName":"Vivero","description":"Cuatro arriates brotan en cruz a la vez, y lo que crece en ellos no es para comer."},
    "curandeiro+invocador/3": {"formName":"Cercado","description":"El cercado de zarcillos irrumpe del suelo para emboscar, y la irrupción ya alcanza a quien estaba demasiado cerca de la tierra removida."},
    "curandeiro+invocador/4": {"formName":"Injerto","description":"Un injerto vivo prendido en la herida del aliado: cierra el boquete y aún crea corteza encima."},
    "curandeiro+invocador/5": {"formName":"Espinar","description":"El jardín entero se cierra en espinar alrededor de la fusión: dos casillas de radio de zarza viva que perfora, envenena y sujeta por el tobillo."},
    "curandeiro+invocador/6": {"formName":"Huerto","description":"No es un hechizo, es una estación: el huerto se abre sobre el grupo, cura, blinda, sigue curando y aún deja un guardia plantado."},
    "curandeiro+sumo/0": {"formName":"Mampara","description":"El mismo brazo que ampara al aliado baja como mampara sobre el enemigo: lo que arranca vuelve en aliento al cuerpo fusionado."},
    "curandeiro+sumo/1": {"formName":"Llamado","description":"La muralla llama por el nombre y el enemigo obedece: es arrastrado dos casillas hasta su alcance y paga el viaje en vida."},
    "curandeiro+sumo/2": {"formName":"Puntal","description":"Apoya el hombro en el aliado y se vuelve su puntal: mientras la fusión aguante, él no cae."},
    "curandeiro+sumo/3": {"formName":"Muro","description":"El muro avanza un palmo y todos alrededor descubren que estaban demasiado cerca."},
    "curandeiro+sumo/4": {"formName":"Redil","description":"Cierra el redil: todos los que andaban sueltos en el borde entran, recibiendo golpes en el camino."},
    "curandeiro+sumo/5": {"formName":"Juramento","description":"El juramento es simple: hoy nadie pasa. Provoca a toda la sala, viste escudo grueso y devuelve parte de cada golpe."},
    "curandeiro+sumo/6": {"formName":"Sagrario","description":"La fusión abre los brazos y todo el grupo cabe adentro: curación profunda, escudo grueso, limpieza y cuero contra el elemento que más duele."},
    "espadachim+invocador/0": {"formName":"Silueta","description":"La sombra de la fusión se despega del suelo, pasa cortando al lado del enemigo y vuelve antes de que alguien cuente cuántos cuerpos había."},
    "espadachim+invocador/1": {"formName":"Espina","description":"Una espina fina dejada donde no llega la luz, con veneno guardado en la punta."},
    "espadachim+invocador/2": {"formName":"Aguijón","description":"El aguijón entra rápido y sale más rápido aún; lo que dejó adentro es lo que tarda."},
    "espadachim+invocador/3": {"formName":"Golpe","description":"El golpe verdadero viene de donde nadie contó cuerpo, y deja veneno para recordarlo."},
    "espadachim+invocador/4": {"formName":"Espectro","description":"Ataca con la cara del espectro y desaparece con él: quien queda no sabe de dónde vino ni adónde fue."},
    "espadachim+invocador/5": {"formName":"Brea","description":"La fusión se borra a sí misma y enciende un gemelo en su lugar: ahora el enemigo debe adivinar cuál de los dos va a doler."},
    "espadachim+invocador/6": {"formName":"Cortejo","description":"El cortejo llega junto: gemelo al frente, veneno por los lados y una espina dejada en el suelo para el camino de vuelta."},
    "espadachim+sumo/0": {"formName":"Encontronazo","description":"La fusión simplemente llega: cruza la distancia corriendo y el hombro aparece antes que el resto."},
    "espadachim+sumo/1": {"formName":"Agarrón","description":"Agarra por la ropa, acerca y clava los pies del infeliz en el suelo: ahora la charla es aquí."},
    "espadachim+sumo/2": {"formName":"Sacudón","description":"Cruza la sala de un sacudón y entrega todo el hombro al llegar."},
    "espadachim+sumo/3": {"formName":"Arranque","description":"Levanta al enemigo por el torso y lo lanza tres casillas, de preferencia contra la esquina de algo."},
    "espadachim+sumo/4": {"formName":"Rebote","description":"Usa al enemigo como proyectil: vuela, golpea a los demás y el daño se reparte por el camino."},
    "espadachim+sumo/5": {"formName":"Remolino","description":"La fusión gira una sola vez con los brazos abiertos y todo el corro sale volando con ella."},
    "espadachim+sumo/6": {"formName":"Impacto","description":"Seis casillas de carrera y una tonelada de llegada: el suelo se hunde, el objetivo se apaga y el vecindario queda atrapado entre los escombros."},
    "invocador+sumo/0": {"formName":"Clamor","description":"Dos gargantas gritando lo mismo a un palmo de la cara de todos: el clamor lastima a los de alrededor y obliga a toda la sala a encarar la fusión."},
    "invocador+sumo/1": {"formName":"Guardián","description":"La fusión arranca un trozo de su propia coraza y lo clava en el suelo: se vuelve ídolo, y el clavazo abre el suelo de quien estaba al lado."},
    "invocador+sumo/2": {"formName":"Estandarte","description":"Clava el estandarte de la fusión: quien pelea a la sombra de la tela golpea más fuerte y recibe menos."},
    "invocador+sumo/3": {"formName":"Baluarte","description":"Levanta un baluarte alrededor del aliado: corteza gruesa y cuero contra el elemento que más duele."},
    "invocador+sumo/4": {"formName":"Pilar","description":"Un pilar baja del techo y raja el suelo en cruz; los pies de quien estaba en la grieta quedan presos en ella."},
    "invocador+sumo/5": {"formName":"Anillo","description":"La fortaleza cierra el anillo: atrae a todos dentro del alcance y clava los pies donde cayeron."},
    "invocador+sumo/6": {"formName":"Cimiento","description":"La fusión se vuelve cimiento de obra: un ídolo nuevo en pie al lado, la sala entera obligada a golpearlo y cada golpe volviendo a la mitad."},
    "arqueiro+minotauro/0": {"formName":"Postigo","description":"Un tiro por la rendija: marca al objetivo y vuelve tras la piedra antes de que vea de dónde vino."},
    "arqueiro+minotauro/1": {"formName":"Parapeto","description":"Levanta la piedra al frente y se apoya en ella: sube empujando a quien estaba pegado, aguanta lo que venga y el escudo aguanta el resto."},
    "arqueiro+minotauro/2": {"formName":"Ristra","description":"La flecha atraviesa toda la línea y deja la misma marca en cada uno que estaba en ella."},
    "arqueiro+minotauro/3": {"formName":"Almena","description":"Cierra una cruz de piedra alrededor del punto elegido y apunta desde allí arriba, con calma."},
    "arqueiro+minotauro/4": {"formName":"Réplica","description":"Detona de lejos todo lo marcado, y la piedra alrededor devuelve el estallido hacia adentro."},
    "arqueiro+minotauro/5": {"formName":"Bastión","description":"Un anillo de piedra a distancia, y tú en el medio: nadie llega, y cada tiro tuyo sale más hondo."},
    "arqueiro+minotauro/6": {"formName":"Asedio","description":"Cierra el anillo a su alrededor, detona cada marca de una vez y marca de nuevo lo que quedó en pie."},
    "bruxo+minotauro/0": {"formName":"Rompiente","description":"Revienta el suelo en radio corto y empuja hacia afuera a quien estaba demasiado cerca."},
    "bruxo+minotauro/1": {"formName":"Borde","description":"La explosión no abre un hueco: levanta el borde. Un anillo de piedra donde antes había camino."},
    "bruxo+minotauro/2": {"formName":"Fragua","description":"Un radio entero de calor que queda en el suelo quemando a quien insista en pasar."},
    "bruxo+minotauro/3": {"formName":"Cúpula","description":"Cierra la piedra en un anillo amplio a tu alrededor y te guardas dentro para conjurar en paz."},
    "bruxo+minotauro/4": {"formName":"Derrumbe","description":"La piedra cae en cruz: 0 PP a quien estaba debajo, y polvo en lugar del camino."},
    "bruxo+minotauro/5": {"formName":"Anfiteatro","description":"Levanta la grada a su alrededor y derrumba el techo adentro: presos, y sin público."},
    "bruxo+minotauro/6": {"formName":"Volcán","description":"Abre la boca del volcán en radio 3, empuja todo lejos y cierra el borde con su propia lava fría."},
    "curandeiro+minotauro/0": {"formName":"Amparo","description":"Golpea con el escudo a quien se acercó y usa el mismo gesto para cerrar la herida de quien estaba atrás."},
    "curandeiro+minotauro/1": {"formName":"Porche","description":"La piedra sube empujando a quien estaba en el camino, y la sombra debajo recupera a quien llegue primero."},
    "curandeiro+minotauro/2": {"formName":"Botica","description":"El destello quema a quien no debía estar ahí y cura a quien sí, en el mismo radio."},
    "curandeiro+minotauro/3": {"formName":"Claustro","description":"Cierra el claustro a tu alrededor: piedra por fuera, curación por dentro, tres turnos de silencio."},
    "curandeiro+minotauro/4": {"formName":"Enfermería","description":"Tres piedras suben en línea: hiere a quien estaba en ella y devuelve aliento a quien estaba atrás."},
    "curandeiro+minotauro/5": {"formName":"Hospicio","description":"La ola sale desde dentro del refugio: lastima a quien cercaba y cura y escuda a quien estaba adentro."},
    "curandeiro+minotauro/6": {"formName":"Santuario","description":"El santuario se cierra: cuatro turnos de piedra, curación plena, escudo, regeneración y nada más entra."},
    "espadachim+minotauro/0": {"formName":"Finta","description":"Corta y retrocede un paso, dejando al otro golpeando el vacío."},
    "espadachim+minotauro/1": {"formName":"Cambio","description":"Sale de donde estaba y deja una piedra ocupando su lugar. Quien venía, llega tarde."},
    "espadachim+minotauro/2": {"formName":"Callejón","description":"Cierra el corredor con tres piedras, aplasta a quien estaba en él y desaparece tras ellas."},
    "espadachim+minotauro/3": {"formName":"Puñalada","description":"El golpe que solo logra dar quien estaba escondido: hondo, y el objetivo no se mueve de su sitio."},
    "espadachim+minotauro/4": {"formName":"Ratonera","description":"Cierra el anillo alrededor del objetivo y corta mientras busca la salida."},
    "espadachim+minotauro/5": {"formName":"Umbral","description":"Desaparece por dos turnos, con la piedra cuidando la espalda y la hoja pesando más."},
    "espadachim+minotauro/6": {"formName":"Dédalo","description":"Alza la cruz de piedra, desaparece dentro de ella y sale desde dentro del enemigo. Él nunca vio por dónde."},
    "invocador+minotauro/0": {"formName":"Centinela","description":"Clava el ídolo donde el camino necesita dueño, y el clavazo abre el suelo de quien estaba al lado."},
    "invocador+minotauro/1": {"formName":"Garita","description":"La piedra sube rajando el suelo y deja la trampa armada al pie: quien dé la vuelta pisa lo que quedó escondido."},
    "invocador+minotauro/2": {"formName":"Vigía","description":"El ídolo sube del suelo ya escudado, y el sacudón de la subida derriba a quien estaba encima."},
    "invocador+minotauro/3": {"formName":"Empalizada","description":"Tres piedras suben en línea, lastiman a quien estaba en ella, y el rugido dice el resto: tienen que venir por aquí."},
    "invocador+minotauro/4": {"formName":"Seto","description":"La cerca crece en cruz y muerde: quien estaba dentro se queda, y sangra."},
    "invocador+minotauro/5": {"formName":"Guarnición","description":"Ídolo, muro y escudo de una vez, y el suelo se raja bajo quien estaba en el paso."},
    "invocador+minotauro/6": {"formName":"Fortaleza","description":"Cierra el anillo, clava el ídolo dentro y derriba la muralla sobre quien quedó fuera: la fortaleza tiene guarnición, muro y portón."},
    "minotauro+sumo/0": {"formName":"Choque","description":"Dos toneladas llegando al mismo tiempo: 0 PP a quien las recibió."},
    "minotauro+sumo/1": {"formName":"Tranca","description":"Atranca el paso con piedra y llama la pelea hacia sí: solo hay un camino, y él está de pie en él."},
    "minotauro+sumo/2": {"formName":"Soporte","description":"Cruza la línea empujando con el hombro y acerca a todos dos pasos."},
    "minotauro+sumo/3": {"formName":"Corral","description":"Cierra el corral a su alrededor, lastima a quien golpea la piedra y pega el suelo a sus pies por dos turnos."},
    "minotauro+sumo/4": {"formName":"Topetazo","description":"El abanico de cuernos lanza a todos hacia atrás y clava en el suelo a quien quedó en pie."},
    "minotauro+sumo/5": {"formName":"Reducto","description":"Planta los dos pies, llama a todos y devuelve parte de lo que reciba por tres turnos."},
    "minotauro+sumo/6": {"formName":"Cerrojo","description":"El anillo de piedra se cierra, el suelo se pega a los pies y el rugido dice el resto: de aquí nadie pasa."}
  },
  "pets": {
    "pet-emberling": {"name":"Brasinha","description":"Dragoncito del tamaño de un gato gordo, escamas color carbón encendido con los bordes anaranjados que pulsan al respirar. Alas demasiado cortas para volar bien: más bien da saltos largos y planea. Cuernitos aún blandos, panza clara y un humito permanente que sale por una sola fosa nasal. Al atacar, infla todo el pecho y el brillo interno se filtra entre las escamas; quieto, se enrosca junto a su dueño como un brasero vivo."},
    "pet-snapvine": {"name":"Bocarra","description":"Planta carnívora en una maceta de barro rajada que carga caminando con dos raíces-piernas. Cabeza-boca enorme, labios verdes con manchas amarillentas, dientes blancos triangulares demasiado grandes para el cuerpo y una lengua roja larga que asoma cuando está feliz. Dos hojas en la base del tallo hacen de cejas y delatan el humor. Ataca estirando el tallo de un lance y mordiendo el tobillo; después se queda con la boca cerrada, masticando, con las hojas erguidas de orgullo."},
    "pet-galehawk": {"name":"Rasga-Ar","description":"Águila flaca de plumas gris claro con las puntas casi transparentes, como si el aire le comiera los bordes. Envergadura mayor que la altura de un héroe, pecho blanco, ojos amarillos sin párpado visible. Vuela siempre un poco sobre la línea de las cabezas y deja una raya fina de viento atrás. Al atacar, pliega las alas, se zambulle y lo abre todo de golpe a un palmo del objetivo: el estallido de aire es el golpe, las garras son solo el susto."},
    "pet-dewling": {"name":"Borbulha","description":"Una gota de agua del tamaño de un perro sentado, con piel tensa que hace ondas al caminar. Por dentro flotan tres hojitas y una piedrita lisa que nunca explica. No tiene boca: los ojos son dos burbujas más oscuras que suben y bajan. Anda a saltitos con un plop. Para curar, se aprieta como esponja y rocía; para limpiar, se vierte entera sobre el aliado y se rearma en el suelo enseguida, un poco más bajita."},
    "pet-lodestone": {"name":"Pedrinha-Guia","description":"Una cría de gólem del tamaño de un gato rechoncho, de piedra lisa con musgo en las juntas y ojos de cristal blanco llenos de lealtad. En el pecho, un surco en espiral con polvo de hierro gira como una brújula viva y señala el peligro antes que nadie. Tres piedritas orbitan a su alrededor como cachorritos. Se sienta como perro esperando orden, y cuando bendice a alguien la espiral pulsa en luz blanca."},
    "pet-heartshard": {"name":"Caco Vivo","description":"Una zorrita de vidrio ahumado del tamaño de un gato, con un corazón de brasa multicolor que pulsa visible en el pecho: una esquirla del propio Corazón Partido, que tomó cuerpo y se encariñó. La cola termina en astillas de cristal sueltas, y seis astillitas orbitan a su alrededor a ritmos distintos, como un cortejo. El corazón cambia de color con el clima de la sala; al proteger a alguien, las seis astillitas salen disparadas y forman una cúpula corta, y luego vuelven una a una."},
    "pet-colecionador": {"name":"Selinho","description":"Una cría de león blanco de melena dorada que anda en pie, con un medallón de oro al cuello: el Sello Primero en miniatura. Cuando está feliz, da vuelta al medallón para \"mostrar la otra cara\". No muerde: cobra."}
  },
  "items": {
    "gh-firefly-crown": {"name":"Garra de Luciérnagas","description":"Guante de alambre con tres redomas minúsculas en los nudillos, cada una con una luciérnaga de la gotera viva en su propio charco. +8 de iniciativa, +3 de poder.","flavor":"Se encienden medio segundo antes del puñetazo. Aprende de ellas."},
    "gh-widow-shears": {"name":"Tijerón de la Viuda","description":"La tijera de poda de la Jardinera Viuda, más alta que un niño y aún pegajosa de savia. +1 PA, +14 de poder.","flavor":"Ella podaba el jardín. Ahora tú podas el mundo."},
    "gh-moss-treads": {"name":"Suelas de Musgo","description":"Sandalias forradas con musgo vivo que se agarra al piso mojado y no hace ruido. +8 de esquiva, +4 de iniciativa.","flavor":"El musgo vuelve a crecer cada noche. No preguntes de qué."},
    "gh-vine-stirrups": {"name":"Estribos de Hiedra","description":"Dos hiedras vivas enroscadas en las espinillas que empujan el paso siguiente antes de que lo pidas. +1 PP, +10 de esquiva.","flavor":"Saben adónde vas. Discrepan poco."},
    "gh-trellis-guard": {"name":"Guarda de Celosía","description":"Placa de celosía de madera cubierta de hiedra, atada al pecho con soga de invernadero. +15 PV, +5% de resistencia a tierra.","flavor":"La hiedra que te cubre te aprieta el brazo con cariño."},
    "gh-sap-apron": {"name":"Delantal de Savia","description":"Delantal de jardinero empapado de savia endurecida, duro como cuero cocido. +30 PV, +10% tierra, +5% agua.","flavor":"Los bolsillos aún tienen semillas. No plantes ninguna."},
    "gh-seed-pouch": {"name":"Candil de Vainas","description":"Candil de vidrio cuyo combustible son vainas reventonas cosechadas verdes: brillan verde mientras fermentan y se van junto con el vidrio al abrirse. Otorga el hechizo Bomba de Semillas.","flavor":"Agitarlo es desaconsejable. Todos lo agitan."},
    "gh-briar-charm": {"name":"Hachón de Zarza","description":"Un nudo de zarza de la canal que arde sin consumirse, preso en una jaula de alambre. Cuando el dueño se asusta, la llama sube y las espinas se cierran a su alrededor. Otorga el hechizo Redoma de Espinas.","flavor":"Arde hace mil años y sigue verde por dentro. Nadie lo explicó."},
    "ci-lantern-fob": {"name":"Garra del Ahogadizo","description":"La mano hinchada de un cargador de la corte, endurecida en salmuera y calzada como guante. Sigue agarrando primero y preguntando después. +10 de iniciativa.","flavor":"Agarra antes de que decidas agarrar. Déjala."},
    "ci-harpoon-flute": {"name":"Flauta-Arpón","description":"Hueso largo con tres agujeros de flauta y una punta con púas; silba grave al cortar el aire. +10 de poder, +5 de iniciativa.","flavor":"Silba la misma nota grave en cada golpe: baja."},
    "ci-current-fins": {"name":"Membranas de Corriente","description":"Membranas finas estiradas entre los dedos de los pies y sujetas al tobillo: cada zancada empuja el agua quieta como si estuviera de acuerdo. +10 de esquiva, +4 de iniciativa.","flavor":"Sirven en tierra firme. Nadie entiende cómo."},
    "ci-baroness-collar": {"name":"Escarpines de la Baronesa","description":"Los zapatos de baile de la Baronesa Salmoura, con hebillas de perla de lodo y suela que no toca el fondo. El agua les abre camino. +1 PP, +15 PV, +8 de iniciativa, +12 de esquiva.","flavor":"La marea abre camino a quien los calza. Por respeto, o por miedo."},
    "ci-brine-cuirass": {"name":"Coraza de Salmuera","description":"Peto de placas de sal cristalizada, ligero y cortante en los bordes. +20 PV, +8% de resistencia a agua.","flavor":"Cuanto más se rompe, más filo tiene. Igual que su dueño anterior."},
    "ci-drowned-coat": {"name":"Casaca del Cargador","description":"Casaca de cuello alto que chorrea agua para siempre y pesa como un abrazo. +35 PV, +12% agua, +5% fuego.","flavor":"Quien la viste nunca suelta lo que carga. Cuidado con lo que cargas."},
    "ci-tide-flask": {"name":"Linterna de Marea","description":"Farol sumergido cuya llama nunca supo que se ahogó. La línea de agua dentro del vidrio queda siempre inclinada, y el agua de afuera se inclina con ella. Otorga el hechizo Resaca.","flavor":"Dos veces al día la linterna tira. Nadie sabe hacia dónde."},
    "ci-jelly-vial": {"name":"Ampolla de Medusa","description":"Ampolla tibia con una medusa-brillo viva dentro, que pulsa despacio e ilumina tres casillas de corredor en cada pulso. Otorga el hechizo Marea Mansa.","flavor":"Ilumina y cura porque cree que tú eres el acuario."},
    "em-bellows-valve": {"name":"Manopla de Fuelle","description":"Manopla de latón con un fuelle de acordeón en el antebrazo: el puño se cierra, la válvula se abre y el aire comprimido llega antes que la mano. +12 de iniciativa.","flavor":"El silbido es medio segundo de ventaja. En los Cierres, una vida."},
    "em-forge-grate": {"name":"Mazo del Primer Fuego","description":"El mazo de Magno, con la cabeza calada en rejilla y brasa viva presa entre las barras. Cada golpe respira. +1 PA, +12 de poder, +10% fuego.","flavor":"Golpeó el primer fuego del mundo. No se impresiona fácil."},
    "em-cinder-treads": {"name":"Suelas de Escoria","description":"Suelas de escoria fría que no se queman en el piso de la fragua y encima dan un empujón en cada zancada. +1 PP, +6 de iniciativa, +14 de esquiva.","flavor":"Caminar sobre brasa es cuestión de suela, dicen ellos."},
    "em-chain-harness": {"name":"Grilletes de Fragua","description":"Cadenas del techo de la fragua cerradas en los tobillos: dan vaivén de péndulo para esquivar y peso de ancla para sujetar a quien intente huir. +12 de esquiva, +8 de traba.","flavor":"Antes sujetaban algo. Ahora andan contigo, de buena gana."},
    "em-riveted-plate": {"name":"Chapa Remachada","description":"Placa rectangular arrancada del portón de la fragua, con cuatro remaches en las esquinas. +25 PV, +8% fuego.","flavor":"El portón no la extraña. Probablemente."},
    "em-soot-mantle": {"name":"Manto de Hollín","description":"Manto que se deshace en partículas en el borde y se rehace solo mientras haya humo en la sala. +40 PV, +15% fuego, +5% aire.","flavor":"A veces recuerda que fue alguien, y te abraza."},
    "em-ember-flask": {"name":"Farol de Chispa","description":"Farol de vidrio grueso con una chispa inquieta golpeando las paredes por dentro. Siempre sabe el camino de vuelta al dueño, y a veces va adelante. Otorga el hechizo Salto de Brasa.","flavor":"Ella va primero. Tú vas junto. Pónganse de acuerdo antes."},
    "em-brand-iron": {"name":"Hierro al Rojo","description":"Hierro de marcar con el sello del Cierre en la punta, rojo vivo hace mil años sin fragua alguna cerca. Ilumina el corredor de naranja y huele a metal caliente. Otorga el hechizo Hierro de Marcar.","flavor":"El Herrero sin Rostro marcaba todo. Incluso a sí mismo."},
    "av-kite-crest": {"name":"Garra de Varilla","description":"Cinco varillas de cometa atadas a los dedos con tela estirada entre ellas: la mano se vuelve ala y el golpe viene con la corriente. +14 de iniciativa, +8 de poder.","flavor":"Tira hacia arriba todo el tiempo. Te acostumbras a inclinarte."},
    "av-plank-gauntlet": {"name":"Manopla de Tabla","description":"Tabla de andamio atada al antebrazo con soga alquitranada: golpea como remo y sujeta como pasamanos. +14 de poder, +6 de traba.","flavor":"Fue piso. Prefiere ser argumento."},
    "av-glider-cloak": {"name":"Espuelas de Vano","description":"Espuelas de varilla y tela que se abren como abanico en cada zancada y atrapan la corriente que sube del vano: convierten la caída en paso. +1 PP, +12 de esquiva.","flavor":"En los Andamios, caer es solo una forma lenta de andar."},
    "av-updraft-boots": {"name":"Botas de Respiradero","description":"Botas con rejillas en las suelas que aspiran el aire de los respiraderos y lo devuelven por debajo en cada zancada. +1 PP, +12 de iniciativa, +14 de esquiva.","flavor":"Ellas dan el paso. Tú solo decides la dirección."},
    "av-rope-vest": {"name":"Chaleco de Jarcia","description":"Chaleco trenzado con la jarcia de los andamios, ajustado al pecho con nudos de marinero. +30 PV, +8% aire.","flavor":"Cada nudo tiene nombre. Aprende dos, al menos."},
    "av-storm-harness": {"name":"Arnés de Tormenta","description":"Arnés de cuero con anillos de latón que zumban en el vendaval y mantienen el cuerpo pegado a la pasarela. +45 PV, +15% aire, +6% tierra.","flavor":"Sujeta el cuerpo. El coraje es problema tuyo."},
    "av-wind-whistle": {"name":"Farolito de Vano","description":"Farolito de señales de las pasarelas: la llama dentro se inclina hacia la corriente antes de que llegue, y si soplas el vidrio, la corriente viene. Otorga el hechizo Soplido.","flavor":"Los Alientos lo usaban para hallar el respiradero. Tú lo usas para limpiar la pasarela."},
    "av-lightning-coil": {"name":"Espiral de Rayo","description":"Bobina de alambre fino enrollada en un clavo de cobre, siempre erizada y encendida por dentro en un azul de tormenta que chasquea bajito. Otorga el hechizo Corriente de Tormenta.","flavor":"Eriza todo el brazo antes de decidir por ti."},
    "mt-drill-bit": {"name":"Broca de Veta","description":"Broca helicoidal de mineral bruto, demasiado pesada para una sola mano y afilada por fricción. +16 de poder, +8 de traba.","flavor":"Cavó demasiado hondo. Por eso tiembla la mina."},
    "mt-quake-crown": {"name":"Puño de Falla","description":"Un bloque de roca rajada moldeado alrededor de la mano, que tiembla bajito al ritmo de la mina y deja de temblar en el instante del impacto. +1 PA, +20 PV, +10% tierra.","flavor":"El temblor ya no viene del suelo. Viene de ti."},
    "mt-ore-greaves": {"name":"Grebas de Mineral","description":"Canilleras de mineral que encuentran solas la piedra firme en medio del derrumbe. +1 PP, +10 de traba, +8 de esquiva.","flavor":"Saben dónde el suelo aún existe. Confía en ellas."},
    "mt-cart-wheels": {"name":"Ruedas de Vagoneta","description":"Dos ruedas de vagoneta adaptadas a los talones, buenas en riel y pésimas en escalera. +14 de iniciativa, +12 de esquiva.","flavor":"Bajar es rápido. Bajar siempre es rápido."},
    "mt-slate-plate": {"name":"Peto de Pizarra","description":"Lajas de pizarra superpuestas como escamas, atadas con hilo de cobre. +45 PV, +12% tierra, +6% agua.","flavor":"Se rompe una laja por golpe. Vinieron muchas lajas."},
    "mt-bedrock-carapace": {"name":"Caparazón de Roca Madre","description":"Bloque excavado de la roca madre de la mina, moldeado a la espalda del dueño y pesado como una promesa. +55 PV, +18% tierra, +6% aire.","flavor":"La mina lo prestó. La mina cobra después."},
    "mt-quake-nail": {"name":"Candil de Plomada","description":"Candil colgado de un hilo de plomada: apunta siempre hacia abajo, aunque toda la galería esté torcida, y donde su luz toca el suelo, el clavo baja. Otorga el hechizo Clavo de Temblor.","flavor":"La mina miente sobre dónde es abajo. El candil no."},
    "mt-shoring-charm": {"name":"Lamparilla del Entibador","description":"La lamparilla de quien apuntalaba el techo: llama baja, vidrio rayado y una viga tallada en miniatura soldada al asa. Donde se posa, el mineral recuerda que sabía mantenerse en pie. Otorga el hechizo Puntal de Mineral.","flavor":"Quien bajaba sin una de ellas no subía con historias."},
    "cp-heart-crown": {"name":"Puño del Corazón","description":"Manopla montada con las cuatro esquirlas mayores del Corazón Partido, una de cada elemento, girando despacio alrededor de los dedos sin tocarse nunca. +1 PA, +22 de poder, +10 de iniciativa.","flavor":"Cuatro elementos discutiendo dentro de tu mano. Gana la discusión."},
    "cp-shard-ring": {"name":"Nudillera de Esquirla","description":"Barra de metal para los cuatro dedos con trozos del Corazón clavados en las crestas, que se calientan cuando el dueño decide golpear. +20 de poder, +8 de iniciativa.","flavor":"Aprieta los dedos antes del golpe. Es su modo de asentir."},
    "cp-quicksilver-boots": {"name":"Botas de Azogue","description":"Botas con suela de metal líquido que se rehace en cada paso y nunca se enfría. +1 PP, +16 de esquiva, +12 de iniciativa.","flavor":"Llegan medio paso antes de que decidas ir."},
    "cp-ashen-anklets": {"name":"Tobilleras de Ceniza","description":"Dos argollas de ceniza prensada que dejan un rastro corto en el suelo y confunden a quien intenta seguirlo. +1 PP, +10 de esquiva, +8 de traba.","flavor":"El rastro se borra solo. Siempre un poco tarde."},
    "cp-scar-plate": {"name":"Peto de Cicatriz","description":"Placa remendada con grapas gruesas sobre una grieta que atraviesa el metal de lado a lado. +50 PV, +15% neutro, +6% fuego, +6% agua.","flavor":"Ya falló una vez. No piensa repetir."},
    "cp-worldshell": {"name":"Casco del Mundo","description":"Un pedazo de la propia Gran Lousa, fino como teja y frío como el cielo que se volvió piedra. +60 PV y +12% de resistencia a todos los elementos.","flavor":"El cielo bajó sobre el mundo. Un trozo de él ahora baja sobre ti, del lado correcto."},
    "cp-heart-horn": {"name":"Cuerno de Brasa","description":"Trompa corta tallada en una esquirla hueca del Corazón, con un carbón vivo alojado en la boquilla: soplar enciende el carbón, y la nota que sale es lo bastante roja para que toda la sala vea de dónde vino. +16 de poder. Otorga el hechizo Llamado del Corazón.","flavor":"Llama a todos. Todos vienen. Ese es el problema y la gracia."},
    "cp-eclipse-lens": {"name":"Lente de Eclipse","description":"Disco de vidrio ahumado tallado del Corazón Partido: el único Lume que en vez de dar luz la recoge. Mirando por él, el clima de la sala pasa a ser una sugerencia. Otorga el hechizo Eclipse.","flavor":"Todo Lume enciende. Este apaga, y por eso vale doble."},
    "gh-wasp-sting": {"name":"Aguijón de Avispa-Brillo","description":"El aguijón de una Avispa-Brillo montado en un mango de bambú, con un resto de la linterna del abdomen aún pegado en la base. Llega antes que la mano. +9 de iniciativa, +4 de poder.","flavor":"Aún parpadea. Nadie tuvo valor de preguntar por qué."},
    "gh-pollen-slippers": {"name":"Pantuflas de Polen","description":"Suelas cubiertas de polen prensado que levantan una nubecita amarilla en cada zancada y difuminan el contorno de quien camina. +9 de esquiva, +6 de iniciativa.","flavor":"Estornudar delata la posición. Aguanta."},
    "gh-chitin-vest": {"name":"Chaleco de Quitina","description":"Placas del dorso del enjambre cosidas en teja, livianas como papel y duras como uña. El viento pasa por ellas sin hallar nada que empujar. +18 PV, +8% de resistencia a aire.","flavor":"Pesa menos que la camisa que llevas puesta."},
    "gh-hive-lantern": {"name":"Linterna de Panal","description":"Un trozo de panal con tres avispas-brillo vivas presas en las celdas, brillando amarillo a través de la cera. Abrir la portezuela suelta a las tres. Otorga el hechizo Picadura en Enjambre.","flavor":"La luz es el alquiler. Ellas cobran el resto al instante."},
    "gh-dew-fang": {"name":"Colmillo de Rocío","description":"El quelícero de una Araña de Rocío atado al puño con hilo de tela endurecida, siempre con una gota colgando en la punta que nunca cae. +11 de poder, +2 de iniciativa.","flavor":"La gota pesa menos que el aire. El colmillo, no."},
    "gh-gutter-shell": {"name":"Corteza de Canal","description":"Media canal de cobre del invernadero doblada en concha sobre el pecho, con mil años de limo verde por dentro de forro. La lluvia resbala por ella como siempre resbaló. +32 PV, +12% agua, +5% aire.","flavor":"Cuida el agua hace mil años. No va a parar por tu culpa."},
    "gh-root-spur": {"name":"Espuelas de Vergajo","description":"Dos trozos de Vergajo aún vivos atados a los talones: alejan el pie del golpe y, cuando el dueño planta los talones, echan raíz sobre quien intente huir. +11 de esquiva, +8 de traba.","flavor":"Podadas del quiosco, y aún de mal humor."},
    "ci-crab-claw": {"name":"Pinza de Sumidero","description":"La pinza grande del Cangrejo de Sumidero, encajada en el antebrazo con correas de cuero mojado. Cierra una vez y no abre por decisión de nadie. +14 de poder, +10 de traba.","flavor":"Arrastraba esta cosa por el suelo. Tú también lo harás."},
    "ci-silt-boots": {"name":"Botas de Azolve","description":"Botas de caña corta atascadas de lodo compactado hasta volverse lastre: se escurren del golpe y luego se hunden en el lugar, arrastrando a quien esté pegado. +8 de esquiva, +8 de traba.","flavor":"El desagüe se atasca de abajo hacia arriba. Aprende de él."},
    "ci-crust-carapace": {"name":"Caparazón de Costra","description":"El dorso del cangrejo entero, con la costra de sal y piedra que acumuló toda una vida aún pegada a los bordes. Pesa como una mesa. +32 PV, +12% tierra, +6% agua.","flavor":"Cada capa es un año en que nadie logró sacarlo del desagüe."},
    "ci-sump-lamp": {"name":"Lamparilla de Sumidero","description":"Lamparilla de latón que pasó décadas presa en la reja del desagüe, con la llama enlodada de verde y el vidrio rayado por dentro. Donde su luz toca el suelo, el lodo obedece. Concede el hechizo Agarrón de Lodo.","flavor":"Encendida bajo el agua, y ningún ahogado lo halló extraño."},
    "ci-piper-fang": {"name":"Colmillo de Morena Flauta","description":"La mandíbula inferior de una Morena Flauta, con los dientes hacia dentro y un agujero de flauta a cada lado que silba grave cuando el brazo baja. +18 de poder, +6 de iniciativa.","flavor":"El silbido llega antes. Es lo único que ella te da."},
    "ci-pearl-mail": {"name":"Malla de Perla de Lodo","description":"Miles de perlas calcificadas del fondo de la cisterna, perforadas y cosidas en malla. Cada una se formó alrededor de un grano de suciedad de la corte. +24 PV, +10% de resistencia a agua.","flavor":"Bonita de lejos. De cerca, es una lista de nombres."},
    "ci-bone-lamp": {"name":"Candil de Huesos","description":"Una jaula de costillas pulidas con un grumo de luz fría colgado dentro. Golpear el hueso mayor con el nudillo hace que toda la cisterna responda. Concede el hechizo Tañido de Huesos.","flavor":"La corte era grande. Siempre queda alguien que responda."},
    "em-quench-fang": {"name":"Colmillo de Temple","description":"La mandíbula del Perro de Temple, aún goteando el vapor condensado que la formó. Cada mordida chirría como hoja entrando al foso. +14 de poder, +4 de iniciativa.","flavor":"El agua del Cierre tiene dientes. Ahora es tu diente."},
    "em-quench-treads": {"name":"Suelas de Foso","description":"Suelas empapadas en el agua de los fosos de temple que nunca se secan: pisan la parrilla al rojo sin chirriar y dejan una huella fría a su paso. +13 de esquiva, +6 de iniciativa.","flavor":"La brasa retrocede un paso. Siempre el mismo paso."},
    "em-quench-vest": {"name":"Peto de Vapor","description":"Dos chapas con un dedo de agua atrapada entre ellas, que se vuelve vapor cuando el calor aprieta y engrosa la defensa justo cuando hace falta. +36 PV, +12% agua, +8% fuego.","flavor":"Chirría antes de que lo sientas. Es el aviso incluido."},
    "em-quench-lamp": {"name":"Farol de Temple","description":"Farol de vidrio grueso lleno hasta el borde con el agua de los fosos, encendido por dentro en un azul frío que no viene de ninguna llama. Inclinarlo derrama. Concede el hechizo Chirrido de Temple.","flavor":"Lo único encendido aquí que no es fuego."},
    "em-imp-gauntlet": {"name":"Manopla de Tizón","description":"Un Tizón entero endurecido en molde de arena y hueco por dentro para caber la mano. Sigue caliente y de mal humor. +15 de poder, +6% de resistencia a fuego.","flavor":"Magno fabricaba estos sin mirar. Uno quedó entero."},
    "em-cinder-plate": {"name":"Placa de Escoria Viva","description":"Placa de escoria arrancada del Montón antes de enfriarse, con vetas naranjas aún corriendo dentro del gris. Calienta la espalda del dueño toda la noche. +28 PV, +14% de resistencia a fuego.","flavor":"Se enfría en mil años. Faltan novecientos."},
    "em-hauler-links": {"name":"Cadenas de Arrastre","description":"Tres eslabones del carrete del Tira-Cadenas arrastrados tras los talones: dan contrapeso para girar fuera del golpe y se enredan en el tobillo de quien intente soltarse. +11 de esquiva, +12 de traba.","flavor":"Él no perseguía a nadie. Los traía a todos."},
    "av-noose-grip": {"name":"Puño de Nudo Ciego","description":"Un nudo de cuerda de obra del tamaño de un puño, endurecido con alquitrán e imposible de deshacer, con media braza de cabo sobrante para lazar. +16 de poder, +10 de traba.","flavor":"Nadie deshizo ese nudo. Nadie lo hará."},
    "av-hemp-boots": {"name":"Botas de Cáñamo","description":"Botas con la suela envuelta en cáñamo trenzado que muerde la tabla mojada y no deja que el pie resbale al vano. +10 de esquiva, +8 de iniciativa.","flavor":"En los Andamios, la diferencia entre andar y caer es la fricción."},
    "av-knot-jerkin": {"name":"Jubón de Nudos","description":"Jubón trenzado entero en nudos de marinero superpuestos, tan apretado que el viento no encuentra holgura alguna para levantarlo. +40 PV, +14% neutro, +5% aire.","flavor":"Cada nudo tiene nombre. Este tiene cuarenta."},
    "av-hangman-lamp": {"name":"Farolito de Polea","description":"Farolito de señalero colgado de un gancho de polea, con un carrete de cabo enrollado en la base y la llama siempre hacia el vano. Tirar del cabo trae de vuelta lo que el lazo atrapó. Concede el hechizo Lazo de Polea.","flavor":"Sirve para izar material. Tú eres material."},
    "av-shrike-talon": {"name":"Garra de Alcaudón","description":"La garra de un Alcaudón de Tabla calzada como nudillera, con los huesitos que él ensartaba en los clavos aún colgando de un hilo. +18 de iniciativa, +8 de poder.","flavor":"Su nido era una vitrina. Te llevaste una pieza."},
    "av-serpent-sash": {"name":"Faja de Sierpe-Pipa","description":"La cola de cintas de una Sierpe-Pipa enrollada dos vueltas en el pecho, con el vidrio molido aún pegado al encerado. Sube con la corriente y lleva el cuerpo medio palmo consigo. +34 PV, +16% de resistencia a aire.","flavor":"Una cometa que aprendió a tirar de su propio hilo. Ahora el hilo lo sostienes tú."},
    "av-ballast-greaves": {"name":"Grebas de Lastre","description":"Dos sacos de grava del Gólem de Lastre atados a las canillas: dan inercia para esquivar sin salir de la tabla y peso de ancla contra quien quiera pasar. +11 de esquiva, +12 de traba.","flavor":"Sostuvo el andamio mil años. Ahora te sostiene a ti, y a quien se acerque."},
    "mt-firedamp-fist": {"name":"Puño de Grisú","description":"Una bolsa de cuero llena del gas azul de la galería, cosida alrededor de la mano y sellada con brea. Cada puñetazo eructa un poco de llama por las costuras. +20 de poder, +6 de iniciativa.","flavor":"Se escapa un poco. Siempre se escapa un poco."},
    "mt-wisp-treads": {"name":"Suelas de Hachón","description":"Suelas que flotan un dedo sobre la grava, igual que el Hachón de Grisú flota a la altura del pecho. No hacen ruido y no pisan trampas. +13 de esquiva, +7 de iniciativa.","flavor":"El polvo no sube. Así sabe la mina que llegaste."},
    "mt-damp-mantle": {"name":"Manto de Llama Azul","description":"Un manto de lona de minero con una película de gas encendido corriendo por fuera de la tela, azul y sin calor. Lo que llega caliente encuentra fuego antes que tela. +44 PV, +16% fuego, +6% tierra.","flavor":"Frío al tacto. Mentira de las buenas."},
    "mt-firedamp-lamp": {"name":"Lamparilla de Seguridad","description":"La lamparilla de malla de alambre que avisaba al minero del grisú: la llama crece y se vuelve azul cuando llega el gas. La malla se abre, y para eso la tomaste. Concede el hechizo Estallido de Grisú.","flavor":"Inventada para salvar vidas. Depende de qué lado de la malla."},
    "mt-blast-knuckles": {"name":"Nudillera de Detonación","description":"Cuatro cápsulas de dinamita húmeda engastadas en una barra de hierro, una por dedo. Ninguna ha explotado aún; todas oyeron la invitación. +21 de poder, +8% de resistencia a fuego.","flavor":"La caja decía \"húmeda\". La caja mentía sobre muchas cosas."},
    "mt-seep-plate": {"name":"Peto de Escurrimiento","description":"Una placa de mineral depositado capa por capa por el agua que escurre pared arriba, lisa de un lado y áspera del otro. Escudo que la propia mina fabricó sola. +42 PV, +14% agua, +6% tierra.","flavor":"El agua de mina no quita la sed. Sirve para otra cosa."},
    "mt-grisu-wick": {"name":"Mecha de Grisú","description":"Un rollo de mecha de mina empapado en gas azul, con una punta siempre encendida en una llama del tamaño de una uña. Arde despacio y no se apaga con el viento. +7 de poder. Concede el hechizo Mecha Larga.","flavor":"Enciende en un rincón de la galería y cobra en otro."},
    "cp-gale-fist": {"name":"Manopla de Vendaval","description":"El guantelete vacío del Heraldo de Vendaval, mantenido en forma de mano solo por el viento que sigue corriendo dentro. Se cierra solo medio instante antes del golpe. +18 de poder, +11 de iniciativa.","flavor":"No hay nada ahí dentro. Sigue doliendo."},
    "cp-gale-steps": {"name":"Grebas de Vendaval","description":"Dos grebas huecas de la misma armadura, con el viento entrando por la rodilla y saliendo por el talón a cada zancada. Llegan donde apuntaron y no donde el enemigo esperó. +12 de esquiva, +12 de iniciativa.","flavor":"Difícil de atrapar, peor de acertar. Era su lema."},
    "cp-gale-plate": {"name":"Coraza Hueca","description":"El torso de la armadura del Heraldo, sin forro, sin dueño y sin peso: por dentro es solo corriente de aire girando. El golpe entra y no halla dónde pegar. +48 PV, +16% aire, +6% neutro.","flavor":"Vacía de verdad. Compruébalo golpeando: suena como campana."},
    "cp-gale-lamp": {"name":"Faro de Vendaval","description":"El yelmo del Heraldo puesto boca arriba y usado como faro, con su viento atrapado dentro empujando una llama blanca tendida. Soltar el viento corta en línea recta. Concede el hechizo Corte del Heraldo.","flavor":"La llama nunca está de pie. Tampoco se apaga."},
    "cp-herald-ember": {"name":"Manopla del Heraldo de Brasa","description":"El guantelete del cuarto de brasa del Corazón, lleno hasta la muñeca de carbón que no termina de arder. Marca la palma de quien lo viste el primer día y no marca más. +21 de poder, +10% de resistencia a fuego.","flavor":"La marca es el contrato. Ya firmaste."},
    "cp-ember-censer": {"name":"Incensario de Brasa","description":"Un incensario de cadena corta con un trozo del cuarto de brasa alojado en el fondo, encendido y soltando humo rojo. Girado una vuelta entera, deja un anillo de fuego en el suelo. +11 de poder. Concede el hechizo Rastro de Brasa.","flavor":"Alguien rezaba con esto. No terminó el rezo."},
    "cp-tide-anklets": {"name":"Tobilleras de Marea","description":"Dos argollas llenas del agua oscura del Heraldo de Marea, siempre en movimiento dentro del metal. Tiran del pie hacia el lado correcto medio tiempo antes de que llegue el golpe. +13 de esquiva, +10 de iniciativa.","flavor":"El agua decide primero. Tú solo no discrepas."},
    "cp-herald-stone": {"name":"Coraza del Heraldo de Piedra","description":"El torso del Heraldo de Piedra, arrancado entero y aún de pie: un bloque del cuarto de piedra del Corazón con vetas claras corriendo por dentro, hueco a la medida exacta de un pecho humano. Pesa como si estuviera descendiendo. +50 PV, +16% tierra, +6% neutro.","flavor":"El heraldo no cayó al morir. Hubo que empujarlo."},
    "sl-cetro": {"name":"Hoja Alba","description":"Una espada larga de acero blanco nacarado, con un hilo de luz dorada corriendo por el centro y la guarda en alas de oro. Pesa exactamente lo que la mano necesite que pese.","flavor":"Ya cobró deudas de cosas más grandes que tú."},
    "sl-botas": {"name":"Grebas de Marfil","description":"Placas de acero blanco con rodilleras de oro en filigrana y suelas forradas de monedas fuera de circulación. Quien las viste llega antes de que suba el precio.","flavor":"El primer paso siempre es la ganancia."},
    "sl-cofre": {"name":"Coraza del Caballero Blanco","description":"Peto de acero blanco nacarado con hombreras de oro en alas y el blasón de las cinco llamas en el pecho. Por dentro sigue siendo una caja fuerte: la cerradura funciona y nadie halló jamás la llave.","flavor":"Lo que guarda ahora eres tú."},
    "sl-selo-primeiro": {"name":"Sello Primero","description":"Un medallón de oro macizo, tachonado de cristales blancos, con un halo que gira despacio. Es la moneda que pagó la primera deuda del mundo enterrado: no tiene cara ni cruz, tiene los cinco elementos, uno en cada borde, y el silencio en el medio.","flavor":"Toda moneda desciende. Esta descendió primero."}
  },
  "sets": {
    "gh-set-flora": {"name":"Traje de la Flora Voraz","description":"Arrancado pieza por pieza de las plantas que aprendieron a cazar en la oscuridad. Quien lo viste echa raíz en el lugar donde decidió quedarse."},
    "gh-set-dew": {"name":"Traje de la Gotera","description":"El invernadero llueve por dentro hace mil años. Lo que vive en las canaletas está hecho de agua estancada, y se escurre entre los dedos de quien intenta sujetarlo."},
    "ci-set-drowned": {"name":"Traje de la Corte Ahogada","description":"Las ropas de baile de la corte que la cisterna bebió. Aún escurren, aún pesan, aún saben bailar."},
    "ci-set-brine": {"name":"Traje de Sal y Hueso","description":"Sal cristalizada, hueso pulido y luz de medusa: las criaturas que soltaron estas piezas no tenían elemento alguno, solo paciencia."},
    "em-set-forge": {"name":"Traje de la Prole de la Fragua","description":"Hecho de lo que la primera llama del mundo escupió. No protege del fuego: convence al fuego de que eres de la casa."},
    "em-set-slag": {"name":"Traje de Escoria","description":"Hierro frío, escoria y cadena: el desecho de la fragua, endurecido por mil años de nada ocurriendo. Pesa como un argumento definitivo."},
    "av-set-gale": {"name":"Traje del Vendaval","description":"Todo lo que vive en los vanos abiertos está hecho de prisa. Estas piezas cantan en la corriente y llegan medio paso antes que el dueño."},
    "av-set-rigging": {"name":"Traje de la Jarcia","description":"Tabla, cuerda y alambre: lo que quedó de quienes construyeron las pasarelas y siguieron caminando por ellas después de muertos."},
    "mt-set-bedrock": {"name":"Traje de la Roca Madre","description":"Tallado en el hueso de la montaña por las cosas que viven debajo. Mientras la mina tiembla, esto no."},
    "mt-set-tools": {"name":"Traje del Minero","description":"Broca, rueda, pizarra y clavo: herramienta de gente, sin elemento alguno. Siguió trabajando mucho después de que la gente paró."},
    "cp-set-heart": {"name":"Traje del Corazón","description":"Las cuatro piezas legendarias del último Cierre, montadas sobre un trozo de la propia Gran Lousa. Solo caen en el Corazón Partido, y caen poco: completar esto es el final del juego, y el comienzo del juego de verdad."},
    "cp-set-cinder": {"name":"Traje de la Brasa Partida","description":"La mitad del Corazón que aún arde. No calienta nada: solo quiere terminar lo que hacía cuando se rajó."},
    "gh-set-swarm": {"name":"Traje del Enjambre","description":"Quitina, polen y tres avispas presas en un panal. Lo que zumba en el invernadero no pelea: llega primero, resuelve y desaparece antes de que la planta note que perdió a alguien."},
    "ci-set-sump": {"name":"Traje del Sumidero","description":"Piedra, sal y lodo compactado: lo que se acumuló en el desagüe por donde la cisterna se vacía. No flota, no esquiva y no se mueve del lugar que eligió."},
    "em-set-quench": {"name":"Traje del Temple","description":"La única agua del Cierre, vestida. Fue hecha para apagar hoja al rojo, y no lo olvidó: donde pasa este traje, el fuego de la casa retrocede un paso y se queda mirando."},
    "av-set-noose": {"name":"Traje del Ahorca-Soga","description":"Cuerda, nudo y polea: el material de obra que sobrevivió a los obreros. No tiene elemento alguno, así que el vendaval ni ayuda ni estorba, y en los Andamios eso es una ventaja entera."},
    "mt-set-firedamp": {"name":"Traje del Grisú","description":"El gas azul que el turno de noche aprendió a temer, cosido en ropa. En una mina entera de piedra y paciencia, es lo único que resuelve rápido, y resuelve para ambos lados."},
    "cp-set-gale": {"name":"Traje del Vendaval Partido","description":"El cuarto de aire del Corazón, desmontado pieza por pieza del Heraldo que lo guardaba. Por dentro es hueco: quien lo viste anda medio paso delante de su propio cuerpo y llega antes de ser esperado."},
    "sl-set-colecionador": {"name":"Traje del Coleccionista","description":"Pagado en sellos, un giro a la vez, al único NPC que no regatea. Quien cierra las cuatro piezas anda con un fuego blanco que no quema nada, solo recuerda."}
  },
  "stones": {
    "stone-ember": {"name":"Brasa Coagulada","description":"Una gota de fuego que se enfrió por fuera y desistió de enfriarse por dentro. Queda tibia en la mano y más caliente cerca del yunque."},
    "stone-tear": {"name":"Lágrima de Cisterna","description":"Gota de agua quieta que se endureció sin volverse hielo. Aún tiene una ondita atrapada girando dentro, despacio."},
    "stone-root": {"name":"Grano de Roca Madre","description":"Una semilla de piedra del fondo de la mina, con vetas claras corriendo por dentro como raíces. Pesa más de lo que debería."},
    "stone-breath": {"name":"Soplo Embotellado","description":"Una burbuja de viento comprimida hasta volverse mineral. Silba bajito cuando alguien pasa corriendo al lado."},
    "stone-slate": {"name":"Esquirla de la Lousa","description":"Una esquirla del cielo vuelta piedra. No es de ningún elemento porque es de todos a la vez: sirve en cualquier forja."},
    "stone-anchor": {"name":"Ancla de Forja","description":"Un diente de yunque arrancado entero, pesado como la culpa. Pegado a la pieza durante el golpe, no deja que el nivel retroceda; solo los jefes más profundos cargan uno."},
    "stone-gem": {"name": "Gema Enterrada", "description": "Cien fragmentos apretados hasta volver a ser una sola piedra. Engastada en una pieza, le da una bonificación que la forja común no da — y cada pieza acepta solo una."},
    "stone-gem-frag": {"name": "Fragmento de Gema", "description": "Un pedazo de gema que aún recuerda el brillo entero. Solo no sirve de nada; cien de ellos, apretados, vuelven a ser la Gema Enterrada."}
  },
  "consumiveis": {
    "pocao-pequena": {"name":"Poción de Vida Pequeña","description":"Un trago de jarabe rojo. Cura 30 PV a quien lo bebe."},
    "pocao-media": {"name":"Poción de Vida Media","description":"El frasco que el mercader más vende. Cura 70 PV a quien lo bebe."},
    "pocao-grande": {"name":"Poción de Vida Grande","description":"Botella panzuda para la sala del jefe. Cura 150 PV a quien la bebe."}
  },
  "eco": {
    "golpes/fogo": {"nome":"Lluvia del Núcleo"},
    "golpes/agua": {"nome":"Marea Profunda"},
    "golpes/terra": {"nome":"Rajadura"},
    "golpes/ar": {"nome":"Corrientes Rotas"}
  }
} });
